var precedence = func() map[string]int {
	table := map[string]int{}
	for index, operators := range [][]string{
		{"|>"}, {"??"}, {"||"}, {"&&"}, {"|"}, {"^"}, {"&"},
		{"==", "===", "!=", "!=="},
		{"<", ">", "<=", ">=", "in", "instanceof"},
		{">>", "<<", ">>>"},
		{"+", "-"},
		{"*", "/", "%"},
		{"**"},
	} {
		for _, operator := range operators {
			table[operator] = index
		}
	}
	return table
}()

