var CorrectnessRequireOrmColumnNullableParity = rule.Rule{
	Name: "base/correctness-require-orm-column-nullable-parity",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindDecorator: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if _, isColumnDecorator := ormNullableColumnDecorators[decorators.CallName(node)]; !isColumnDecorator {
					return
				}

				declaredNullable, skip, found := decorators.BooleanOption(node, "nullable")
				if skip || !found || !declaredNullable {
					return
				}

				owner := node.Parent
				if owner == nil {
					return
				}
				if owner.Kind != ast.KindPropertyDeclaration {
					return
				}

				if decorators.HasDecoratorInSet(owner, ormRelationDecorators) {
					return
				}

				name := owner.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}

				propertyType := ctx.TypeChecker.GetTypeAtLocation(name)
				if propertyType == nil || decorators.IsNullableType(propertyType) {
					return
				}

				ctx.ReportNode(name, buildColumnNullableButTypeNotMessage(
					ctx.TypeChecker.TypeToString(propertyType)))
			},
		}
	},
}

var CorrectnessRequireSerializableNullableParity = rule.Rule{
	Name: "base/correctness-require-serializable-nullable-parity",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindDecorator: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if decorators.CallName(node) != "SerializableField" {
					return
				}

				if _, _, hasDefault := decorators.BooleanOption(node, "defaultValue"); hasDefault {
					return
				}

				declaredOptional, skip, _ := decorators.BooleanOption(node, "optional")
				if skip {
					return
				}

				owner := node.Parent
				if owner == nil || owner.Kind != ast.KindPropertyDeclaration {
					return
				}
				name := owner.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}

				propertyType := ctx.TypeChecker.GetTypeAtLocation(name)
				if propertyType == nil {
					return
				}
				typeIsNullable := decorators.IsNullableType(propertyType)
				typeText := ctx.TypeChecker.TypeToString(propertyType)

				switch {
				case declaredOptional && !typeIsNullable:
					ctx.ReportNode(name, buildDecoratorOptionalButTypeNotMessage(typeText))
				case !declaredOptional && typeIsNullable:
					ctx.ReportNode(name, buildTypeOptionalButDecoratorNotMessage(typeText))
				}
			},
		}
	},
}

