var MaxLines = rule.Rule{
	Name:       "max-lines",
	NoListener: rule.NoListenerAnswersInRun,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}
		settings, hasSettings := rule.OptionsAs[MaxLinesOptions](options)
		if !hasSettings {
			settings = DefaultMaxLinesOptions()
		}

		text := ctx.SourceFile.Text()
		var commentOnly func(start int, end int) bool
		if settings.SkipComments {
			commentOnly = maxLinesCommentOnly(text, comments.ForFile(ctx))
		}

		counted := 0
		excessStart := 0
		for start, end := range maxLinesEach(text) {
			if settings.SkipBlankLines && maxLinesIsBlank(text[start:end]) {
				continue
			}
			if commentOnly != nil && commentOnly(start, end) {
				continue
			}
			if counted == settings.Maximum {
				excessStart = start
			}
			counted++
		}
		if counted <= settings.Maximum {
			return nil
		}
		ctx.ReportRange(core.NewTextRange(excessStart, len(text)), maxLinesMessage(counted, settings.Maximum))
		return nil
	},
}

var MaxNestedCallbacks = rule.Rule{
	Name: "max-nested-callbacks",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		settings, isSettings := rule.OptionsAs[MaxNestedCallbacksOptions](options)
		if !isSettings {
			settings = DefaultMaxNestedCallbacksSettings()
		}
		maximum := 10
		if settings.Maximum != nil {
			maximum = *settings.Maximum
		}
		checkConstructorCallCallbacks := settings.CheckConstructorCallCallbacks != nil &&
			*settings.CheckConstructorCallCallbacks

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				var walk func(current *ast.Node, depth int)
				walk = func(current *ast.Node, depth int) {
					next := depth
					if maxNestedCallbacksIsCountedCallback(current, checkConstructorCallCallbacks) {
						next = depth + 1
						if next > maximum {
							ctx.ReportRange(maxNestedCallbacksHeadRange(ctx, current),
								maxNestedCallbacksMessage(next, maximum))
						}
					}
					current.ForEachChild(func(child *ast.Node) bool {
						walk(child, next)
						return false
					})
				}
				walk(node, 0)
			},
		}
	},
}

