var NoAlert = rule.Rule{
	Name:             "no-alert",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				callee := ast.SkipParentheses(node.AsCallExpression().Expression)
				if callee == nil {
					return
				}

				if callee.Kind == ast.KindIdentifier {
					name := callee.Text()
					if noAlertProhibited[name] && !identifierIsShadowed(ctx, callee) {
						ctx.ReportNode(node, buildNoAlertMessage(name))
					}
					return
				}

				object := memberAccessObject(callee)
				if object == nil {
					return
				}
				object = ast.SkipParentheses(object)
				if !isGlobalObjectReference(ctx, object) {
					return
				}

				name, _ := property.AccessedName(callee, property.Static)
				if noAlertProhibited[name] {
					ctx.ReportNode(node, buildNoAlertMessage(name))
				}
			},
		}
	},
}

var messageUseAnArrayLiteral = rule.Message{
	Id:          "useAnArrayLiteral",
	Description: "Replace the `Array` call with an array literal.",
}

var NoArrayConstructor = rule.Rule{
	Name: "@typescript-eslint/no-array-constructor",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		report := func(node *ast.Node) {
			callee, arguments, typeArguments, isOptionalCall := arrayConstructorCallParts(node)

			if callee == nil || callee.Kind != ast.KindIdentifier || callee.Text() != "Array" {
				return
			}

			if typeArguments != nil {
				return
			}

			if isOptionalCall {
				return
			}

			if arguments != nil && len(arguments.Nodes) == 1 &&
				arguments.Nodes[0].Kind != ast.KindSpreadElement {
				return
			}

			if ctx.TypeChecker == nil || !resolvesToAGlobal(ctx, callee) {
				return
			}

			ctx.ReportNodeWithSuggestions(node, messageNoArrayConstructor, rule.Suggestion{
				Message: messageUseAnArrayLiteral,
				Fixes: []rule.Fix{
					ctx.ReplaceNode(node, arrayLiteralReplacing(ctx, node, arguments)),
				},
			})
		}

		return rule.Listeners{

			ast.KindNewExpression:  report,
			ast.KindCallExpression: report,
		}
	},
}

var NoAsyncPromiseExecutor = rule.Rule{
	Name: "no-async-promise-executor",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindNewExpression: func(node *ast.Node) {
				newExpression := node.AsNewExpression()

				callee := ast.SkipParentheses(newExpression.Expression)
				if !ast.IsIdentifier(callee) || callee.AsIdentifier().Text != "Promise" {
					return
				}

				if newExpression.Arguments == nil || len(newExpression.Arguments.Nodes) == 0 {
					return
				}

				executor := ast.SkipParentheses(newExpression.Arguments.Nodes[0])
				asyncKeyword := asyncModifierOf(executor)
				if asyncKeyword == nil {
					return
				}

				ctx.ReportNode(asyncKeyword, messageNoAsyncPromiseExecutor)
			},
		}
	},
}

var NoAwaitInLoop = rule.Rule{
	Name: "no-await-in-loop",
	Run: func(ctx rule.Context, options any) rule.Listeners {
