var messageAddBraces = rule.Message{
	Id:          "addBraces",
	Description: "Wrap the clause body in braces.",
}

var NoCaseDeclarations = rule.Rule{
	Name: "no-case-declarations",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindCaseBlock: func(node *ast.Node) {
				caseBlock := node.AsCaseBlock()
				if caseBlock == nil || caseBlock.Clauses == nil {
					return
				}

				for _, clauseNode := range caseBlock.Clauses.Nodes {
					clause := clauseNode.AsCaseOrDefaultClause()
					if clause == nil || clause.Statements == nil {
						continue
					}
					statements := clause.Statements.Nodes
					if len(statements) == 0 {
						continue
					}

					firstStatement := statements[0]
					lastStatement := statements[len(statements)-1]

					for _, statement := range statements {
						if !isLexicalDeclaration(statement) {
							continue
						}
						ctx.ReportNodeWithSuggestions(statement, messageCaseDeclaration, rule.Suggestion{
							Message: messageAddBraces,
							Fixes: []rule.Fix{
								ctx.InsertBefore(firstStatement, "{ "),
								ctx.InsertAfter(lastStatement, " }"),
							},
						})
					}
				}
			},
		}
	},
}

var NoClassAssign = rule.Rule{
	Name: "no-class-assign",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		reportWritesTo := func(node *ast.Node) {

			if ctx.TypeChecker == nil {
				return
			}

			name := node.Name()
			if name == nil || name.Kind != ast.KindIdentifier {
				return
			}

			declaration := declarationAnchoredAt(ctx, name)
			if declaration == nil {
				return
			}

			sourceFile := ast.GetSourceFileOfNode(node)
			if sourceFile == nil {
				return
			}

			var visit func(*ast.Node)
			visit = func(current *ast.Node) {
				if current == nil {
					return
				}

				if current.Kind == ast.KindIdentifier &&
					current.Text() == name.Text() &&
					reference.WritesToBinding(current) &&
					resolvesToDeclaration(ctx, current, declaration) {
					ctx.ReportNode(current, messageNoClassAssign)
				}
				current.ForEachChild(func(child *ast.Node) bool {
					visit(child)
					return false
				})
			}
			visit(sourceFile.AsNode())
		}

		return rule.Listeners{
			ast.KindClassDeclaration: reportWritesTo,
			ast.KindClassExpression:  reportWritesTo,
		}
	},
}

var NoCompareNegZero = rule.Rule{
	Name: "no-compare-neg-zero",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{

			ast.KindBinaryExpression: func(node *ast.Node) {
				binaryExpression := node.AsBinaryExpression()
				if binaryExpression == nil || binaryExpression.OperatorToken == nil {
					return
				}

				operatorText, isComparison := negativeZeroComparisonOperators[binaryExpression.OperatorToken.Kind]
				if !isComparison {
					return
				}

				if !isNegativeZeroLiteral(binaryExpression.Left) && !isNegativeZeroLiteral(binaryExpression.Right) {
					return
				}

				ctx.ReportNode(node, rule.Message{
					Id: "unexpected",
					Description: "Comparing against `-0` with `" + operatorText + "`: every comparison " +
						"operator treats `-0` and `0` as the same number, so this is true for positive " +
						"zero too and does not test what it looks like it tests. `Object.is(x, -0)` is " +
						"the only comparison that distinguishes them.",
				})
			},
		}
	},
}

var NoCondAssign = rule.Rule{
	Name: "no-cond-assign",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		always := false
		if mode, configured := rule.OptionsAs[NoCondAssignOptions](options); configured && mode == NoCondAssignAlways {
			always = true
		}

		if always {
			return rule.Listeners{
				ast.KindBinaryExpression: func(node *ast.Node) {
					if !isAssignmentExpression(node) {
						return
					}
					if assignmentSitsInAConditionalTest(node) {
						reportCondAssign(ctx, node)
					}
				},
			}
		}

		reportIfTestIsAssignment := func(test *ast.Node) {
			if !isAssignmentExpression(test) {
				return
			}
			reportCondAssign(ctx, test)
		}

		return rule.Listeners{
			ast.KindIfStatement: func(node *ast.Node) {
				reportIfTestIsAssignment(node.AsIfStatement().Expression)
			},
			ast.KindWhileStatement: func(node *ast.Node) {
				reportIfTestIsAssignment(node.AsWhileStatement().Expression)
			},
			ast.KindDoStatement: func(node *ast.Node) {
				reportIfTestIsAssignment(node.AsDoStatement().Expression)
			},
			ast.KindForStatement: func(node *ast.Node) {

				reportIfTestIsAssignment(node.AsForStatement().Condition)
			},
			ast.KindConditionalExpression: func(node *ast.Node) {

				reportIfTestIsAssignment(ast.SkipParentheses(node.AsConditionalExpression().Condition))
			},
		}
	},
}

var NoConstAssign = rule.Rule{
	Name: "no-const-assign",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		judged := map[*ast.Node]bool{}
		return rule.Listeners{
			ast.KindVariableDeclarationList: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}

				if node.Flags&ast.NodeFlagsConstant == 0 {
					return
				}
				for _, declaration := range node.AsVariableDeclarationList().Declarations.Nodes {

					forEachBoundName(declaration.AsVariableDeclaration().Name(), func(boundName *ast.Node) {
						if boundName != nil && boundName.Kind == ast.KindIdentifier {
							reportConstWrites(ctx, boundName, judged)
						}
					})
				}
			},
		}
	},
}

var messageBothAlwaysNew = rule.Message{
	Id: "bothAlwaysNew",
	Description: "Both sides build a fresh object, and two fresh objects are never the same " +
		"object, so this comparison is always false even under loose equality: two objects are " +
		"compared by identity whichever equality operator is used.",
}

var messageConstantRelationalComparison = rule.Message{
	Id: "constantRelationalComparison",
	Description: "Both sides of this comparison are literals, so the answer is fixed and could be " +
		"written as true or false. A comparison that decides nothing is usually a leftover from " +
		"code that used to compare something real.",
}

var NoConstantBinaryExpression = rule.Rule{
	Name: "no-constant-binary-expression",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		judge := constantJudge{isGlobal: func(identifier *ast.Node) bool {
			return ctx.TypeChecker == nil || !rule.IsDeclaredInASourceFile(ctx.TypeChecker.GetSymbolAtLocation(identifier))
		}}
		checkRelationalComparisons := false
		if parsed, ok := rule.OptionsAs[NoConstantBinaryExpressionOptions](options); ok {
			checkRelationalComparisons = parsed.CheckRelationalComparisons
		}

		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil {
					return
				}
				left := ast.SkipParentheses(binary.Left)
				right := ast.SkipParentheses(binary.Right)
				if left == nil || right == nil {
					return
				}

				switch binary.OperatorToken.Kind {
				case ast.KindAmpersandAmpersandToken, ast.KindBarBarToken:

					if isConstantExpression(left, true) {
						ctx.ReportNode(left, messageConstantShortCircuit)
					}

				case ast.KindQuestionQuestionToken:
					if judge.hasConstantNullishness(left, false) {
						ctx.ReportNode(left, messageConstantShortCircuit)
					}

				case ast.KindEqualsEqualsEqualsToken, ast.KindExclamationEqualsEqualsToken:
					if operand := judge.constantComparisonOperand(left, right, true); operand != nil {
						ctx.ReportNode(operand, messageConstantBinaryOperand)
					} else if operand := judge.constantComparisonOperand(right, left, true); operand != nil {
						ctx.ReportNode(operand, messageConstantBinaryOperand)
					} else if judge.isAlwaysNew(left) {
						ctx.ReportNode(left, messageAlwaysNew)
					} else if judge.isAlwaysNew(right) {
						ctx.ReportNode(right, messageAlwaysNew)
					}

				case ast.KindEqualsEqualsToken, ast.KindExclamationEqualsToken:
					if operand := judge.constantComparisonOperand(left, right, false); operand != nil {
						ctx.ReportNode(operand, messageConstantBinaryOperand)
					} else if operand := judge.constantComparisonOperand(right, left, false); operand != nil {
						ctx.ReportNode(operand, messageConstantBinaryOperand)
					} else if judge.isAlwaysNew(left) && judge.isAlwaysNew(right) {

						ctx.ReportNode(left, messageBothAlwaysNew)
					}

				case ast.KindLessThanToken, ast.KindLessThanEqualsToken,
					ast.KindGreaterThanToken, ast.KindGreaterThanEqualsToken:
					if checkRelationalComparisons && judge.isStaticLiteral(left) && judge.isStaticLiteral(right) {
						ctx.ReportNode(node, messageConstantRelationalComparison)
					}
				}
			},
		}
	},
}

var NoConstantCondition = rule.Rule{
	Name: "no-constant-condition",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		checkLoops := NoConstantConditionCheckLoops("allExceptWhileTrue")
		if parsed, ok := rule.OptionsAs[NoConstantConditionOptions](options); ok && parsed.CheckLoops != "" {
			checkLoops = parsed.CheckLoops
		}

		reportIfConstant := func(condition *ast.Node) {
			if condition != nil && isConstantExpression(condition, true) {
				ctx.ReportNode(condition, messageUnexpectedConstantCondition)
			}
		}

		checkLoopCondition := func(condition *ast.Node, isWhileTrue bool) {
			switch checkLoops {
			case "none":
				return
			case "allExceptWhileTrue":
				if isWhileTrue {
					return
				}
			}
			reportIfConstant(condition)
		}

		return rule.Listeners{
			ast.KindIfStatement: func(node *ast.Node) {
				reportIfConstant(node.AsIfStatement().Expression)
			},

			ast.KindConditionalExpression: func(node *ast.Node) {
				reportIfConstant(node.AsConditionalExpression().Condition)
			},

			ast.KindWhileStatement: func(node *ast.Node) {
				condition := node.AsWhileStatement().Expression
				checkLoopCondition(condition, isTrueLiteral(condition))
			},

			ast.KindDoStatement: func(node *ast.Node) {
				checkLoopCondition(node.AsDoStatement().Expression, false)
			},

			ast.KindForStatement: func(node *ast.Node) {

				checkLoopCondition(node.AsForStatement().Condition, false)
			},
		}
	},
}

var NoConstructorReturn = rule.Rule{
	Name: "no-constructor-return",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindReturnStatement: func(node *ast.Node) {
				statement := node.AsReturnStatement()

				if statement == nil || statement.Expression == nil {
					return
				}

				if enclosingConstructor(node) == nil {
					return
				}

				ctx.ReportNode(node, rule.Message{
					Id: "noConstructorReturn",
					Description: "This returns a value from a constructor, where it is either " +
						"discarded or worse. `new C()` evaluates to the new instance and throws " +
						"the returned value away, unless that value is an object, in which case " +
						"the language substitutes it for the instance and every field this " +
						"constructor assigned is lost. Neither outcome is one a reader expects " +
						"from a `new`, so return nothing and assign to `this` instead.",
				})
			},
		}
	},
}

var NoContinue = rule.Rule{
	Name: "no-continue",
	Run: func(ctx rule.Context, options any) rule.Listeners {
