var NoDupeClassMembers = rule.Rule{
	Name: "no-dupe-class-members",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		check := func(members *ast.NodeList) {
			classmembers.ForEachDuplicate(members, func(name *ast.Node, key classmembers.Key) {
				ctx.ReportNode(name, rule.Message{
					Id: "noDupeClassMembers",
					Description: fmt.Sprintf(
						"This class already declares a member named %s. The later declaration wins "+
							"silently, so the earlier one is dead code that reads as live, and "+
							"nothing in the language or at runtime tells the two apart.", key.Name),
				})
			})
		}

		return rule.Listeners{
			ast.KindClassDeclaration: func(node *ast.Node) {
				check(node.AsClassDeclaration().Members)
			},
			ast.KindClassExpression: func(node *ast.Node) {
				check(node.AsClassExpression().Members)
			},
		}
	},
}

var NoDupeElseIf = rule.Rule{
	Name: "no-dupe-else-if",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindIfStatement: func(node *ast.Node) {
				test := node.AsIfStatement().Expression
				if test == nil {
					return
				}

				conditionsToCheck := []*ast.Node{test}
				if isLogicalOperator(test, ast.KindAmpersandAmpersandToken) {
					conditionsToCheck = append(conditionsToCheck, splitByOperator(test, ast.KindAmpersandAmpersandToken)...)
				}

				remaining := make([][][]*ast.Node, 0, len(conditionsToCheck))
				for _, condition := range conditionsToCheck {
					orGroups := splitByOperator(condition, ast.KindBarBarToken)
					groups := make([][]*ast.Node, 0, len(orGroups))
					for _, orGroup := range orGroups {
						groups = append(groups, splitByOperator(orGroup, ast.KindAmpersandAmpersandToken))
					}
					remaining = append(remaining, groups)
				}

				for current := node; ; {
					parent := current.Parent
					if parent == nil || parent.Kind != ast.KindIfStatement {
						return
					}
					if parent.AsIfStatement().ElseStatement != current {
						return
					}
					current = parent

					earlierTest := current.AsIfStatement().Expression
					if earlierTest == nil {
						return
					}

					earlierGroups := make([][]*ast.Node, 0, 4)
					for _, orGroup := range splitByOperator(earlierTest, ast.KindBarBarToken) {
						earlierGroups = append(earlierGroups, splitByOperator(orGroup, ast.KindAmpersandAmpersandToken))
					}

					for conditionIndex, groups := range remaining {
						kept := groups[:0]
						for _, group := range groups {
							if !anyGroupIsSubsetOf(ctx.SourceFile, earlierGroups, group) {
								kept = append(kept, group)
							}
						}
						remaining[conditionIndex] = kept
					}

					for _, groups := range remaining {
						if len(groups) == 0 {
							ctx.ReportNode(test, messageUnexpectedDuplicateElseIf)
							return
						}
					}
				}
			},
		}
	},
}

var NoDuplicateCase = rule.Rule{
	Name: "no-duplicate-case",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindSwitchStatement: func(node *ast.Node) {
				switchStatement := node.AsSwitchStatement()
				if switchStatement == nil || switchStatement.CaseBlock == nil {
					return
				}
				caseBlock := switchStatement.CaseBlock.AsCaseBlock()
				if caseBlock == nil || caseBlock.Clauses == nil {
					return
				}

				seenTests := map[string]bool{}

				for _, clauseNode := range caseBlock.Clauses.Nodes {
					if clauseNode.Kind != ast.KindCaseClause {
						continue
					}
					clause := clauseNode.AsCaseOrDefaultClause()
					if clause == nil || clause.Expression == nil {
						continue
					}

					signature := tokenSignature(ctx.SourceFile, clause.Expression)
					if seenTests[signature] {

						ctx.Report(rule.Diagnostic{
							Range:      rule.TokenRange(ctx.SourceFile, clause.Expression),
							Message:    messageDuplicateCase,
							SourceFile: ctx.SourceFile,
						})
						continue
					}
					seenTests[signature] = true
				}
			},
		}
	},
}

