var NoLabels = rule.Rule{
	Name: "no-labels",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		settings := NoLabelsOptions{}
		if decoded, ok := rule.OptionsAs[NoLabelsOptions](options); ok {
			settings = decoded
		}

		isAllowed := func(body *ast.Node) bool {

			if ast.IsIterationStatement(body, false) {
				return settings.AllowLoop
			}
			if body.Kind == ast.KindSwitchStatement {
				return settings.AllowSwitch
			}
			return false
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {

				var labelFindings []*ast.Node
				var jumpFindings []struct {
					node    *ast.Node
					message rule.Message
				}

				type labelEntry struct {
					name string
					body *ast.Node
				}
				var stack []labelEntry

				kindOf := func(name string) bool {
					for index := len(stack) - 1; index >= 0; index-- {
						if stack[index].name == name {
							return isAllowed(stack[index].body)
						}
					}
					return false
				}

				var visit func(*ast.Node) bool
				visit = func(current *ast.Node) bool {
					switch current.Kind {
					case ast.KindLabeledStatement:
						labeled := current.AsLabeledStatement()
						if labeled == nil || labeled.Label == nil {
							break
						}
						if !isAllowed(labeled.Statement) {
							labelFindings = append(labelFindings, current)
						}
						stack = append(stack, labelEntry{
							name: labeled.Label.Text(),
							body: labeled.Statement,
						})
						current.ForEachChild(visit)

						stack = stack[:len(stack)-1]
						return false

					case ast.KindBreakStatement:
						if label := current.AsBreakStatement().Label; label != nil &&
							!kindOf(label.Text()) {
							jumpFindings = append(jumpFindings, struct {
								node    *ast.Node
								message rule.Message
							}{current, messageUnexpectedLabelInBreak})
						}

					case ast.KindContinueStatement:
						if label := current.AsContinueStatement().Label; label != nil &&
							!kindOf(label.Text()) {
							jumpFindings = append(jumpFindings, struct {
								node    *ast.Node
								message rule.Message
							}{current, messageUnexpectedLabelInContinue})
						}
					}

					current.ForEachChild(visit)
					return false
				}
				node.ForEachChild(visit)

				for _, labeled := range labelFindings {
					ctx.ReportNode(labeled, messageUnexpectedLabel)
				}
				for _, jump := range jumpFindings {
					ctx.ReportNode(jump.node, jump.message)
				}
			},
		}
	},
}

var NoLoneBlocks = rule.Rule{
	Name: "no-lone-blocks",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				type finding struct {
					node    *ast.Node
					message rule.Message
				}
				var findings []finding

				report := func(block *ast.Node) {
					message := messageRedundantBlock

					if parent := block.Parent; parent != nil && parent.Kind == ast.KindBlock {
						message = messageRedundantNestedBlock
					}
					findings = append(findings, finding{block, message})
				}

				var visit func(*ast.Node) bool
				visit = func(current *ast.Node) bool {

					if current.Kind == ast.KindBlock {
						switch {
						case isLoneBlock(current) && !holdsBlockScopedBinding(current):
							report(current)
						case isOnlyStatementOfABlock(current):

							report(current)
						}
					}
					current.ForEachChild(visit)
					return false
				}
				node.ForEachChild(visit)

				for _, found := range findings {
					ctx.ReportNode(found.node, found.message)
				}
			},
		}
	},
}

var NoLonelyIf = rule.Rule{
	Name: "no-lonely-if",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindIfStatement: func(node *ast.Node) {
				block := node.Parent
				if block == nil || block.Kind != ast.KindBlock {
					return
				}
				if len(block.AsBlock().Statements.Nodes) != 1 {
					return
				}
				enclosing := block.Parent
				if enclosing == nil || enclosing.Kind != ast.KindIfStatement {
					return
				}

				if enclosing.AsIfStatement().ElseStatement != block {
					return
				}
				if noLonelyIfBracesAreNecessary(ctx, node, block) {
					return
				}

				if fix, canFix := noLonelyIfFix(ctx, node, block, enclosing); canFix {
					ctx.ReportNodeWithFixes(node, messageUnexpectedLonelyIf, fix)
					return
				}
				ctx.ReportNode(node, messageUnexpectedLonelyIf)
			},
		}
	},
}

