var NoParamReassign = rule.Rule{
	Name: "no-param-reassign",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		var settings NoParamReassignOptions
		if parsed, ok := rule.OptionsAs[NoParamReassignOptions](options); ok {
			settings = parsed
		}
		ignored := compileIgnoredNames(settings)

		checkFunction := func(node *ast.Node) {

			if ctx.TypeChecker == nil {
				return
			}
			parameters := node.Parameters()
			if len(parameters) == 0 {
				return
			}

			anchors := map[*ast.Node]string{}
			for _, parameter := range parameters {
				collectParameterBindings(parameter.Name(), anchors)
			}
			if len(anchors) == 0 {
				return
			}

			var visit func(*ast.Node)
			visit = func(current *ast.Node) {
				if current == nil {
					return
				}
				if current.Kind == ast.KindIdentifier && !isOwnParameterBinding(current, anchors) {
					if name, isAnchored := anchoredParameterName(ctx, current, anchors); isAnchored {
						reportParameterUse(ctx, current, name, settings.Props, ignored)
					}
				}
				current.ForEachChild(func(child *ast.Node) bool {
					visit(child)
					return false
				})
			}
			for _, parameter := range parameters {
				visit(parameter)
			}
			if body := node.Body(); body != nil {
				visit(body)
			}
		}

		return rule.Listeners{
			ast.KindFunctionDeclaration: checkFunction,
			ast.KindFunctionExpression:  checkFunction,
			ast.KindArrowFunction:       checkFunction,
			ast.KindMethodDeclaration:   checkFunction,
			ast.KindConstructor:         checkFunction,
			ast.KindGetAccessor:         checkFunction,
			ast.KindSetAccessor:         checkFunction,
		}
	},
}

var NoPlusplus = rule.Rule{
	Name: "no-plusplus",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		allowForLoopAfterthoughts := false
		if resolved, isNoPlusplusOptions := rule.OptionsAs[NoPlusplusOptions](options); isNoPlusplusOptions {
			allowForLoopAfterthoughts = resolved.AllowForLoopAfterthoughts
		}

		return rule.Listeners{
			ast.KindPostfixUnaryExpression: func(node *ast.Node) {
				expression := node.AsPostfixUnaryExpression()
				if expression == nil {
					return
				}
				if allowForLoopAfterthoughts && noPlusplusIsForLoopAfterthought(node) {
					return
				}
				ctx.ReportNode(node, noPlusplusUnexpectedUnaryOp(
					noPlusplusOperatorText(expression.Operator)))
			},

			ast.KindPrefixUnaryExpression: func(node *ast.Node) {
				expression := node.AsPrefixUnaryExpression()
				if expression == nil {
					return
				}

				if expression.Operator != ast.KindPlusPlusToken &&
					expression.Operator != ast.KindMinusMinusToken {
					return
				}
				if allowForLoopAfterthoughts && noPlusplusIsForLoopAfterthought(node) {
					return
				}
				ctx.ReportNode(node, noPlusplusUnexpectedUnaryOp(
					noPlusplusOperatorText(expression.Operator)))
			},
		}
	},
}

var messageNoPromiseExecutorReturnPrependVoid = rule.Message{
	Id:          "prependVoid",
	Description: "Prepend `void` to the expression, saying the value is deliberately discarded.",
}

var messageNoPromiseExecutorReturnWrapBraces = rule.Message{
	Id:          "wrapBraces",
	Description: "Wrap the expression in `{}`, making the arrow body a statement rather than a return.",
}

var NoPromiseExecutorReturn = rule.Rule{
	Name:             "no-promise-executor-return",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {

		settings, _ := rule.OptionsAs[NoPromiseExecutorReturnOptions](options)
		allowVoid := settings.AllowVoid != nil && *settings.AllowVoid

		reportArrowBody := func(node *ast.Node) {

			if ctx.TypeChecker == nil {
				return
			}
			arrow := node.AsArrowFunction()
			body := arrow.Body
			if body == nil || body.Kind == ast.KindBlock {
				return
			}
			if !isPromiseExecutorFunction(ctx, node) {
				return
			}

			if allowVoid && unwrapParentheses(body).Kind == ast.KindVoidExpression {
				return
			}

			suggestions := []rule.Suggestion{}
			if allowVoid {
				suggestions = append(suggestions, promiseExecutorPrependVoidSuggestion(ctx, body))
			}
			if promiseExecutorCanWrapInBraces(body) {
				suggestions = append(suggestions, promiseExecutorWrapBracesSuggestion(ctx, body))
			}

			ctx.ReportNodeWithSuggestions(unwrapParentheses(body), messageNoPromiseExecutorReturn,
				suggestions...)
		}

		return rule.Listeners{
			ast.KindArrowFunction: reportArrowBody,
			ast.KindReturnStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				argument := node.AsReturnStatement().Expression

				if argument == nil {
					return
				}
				enclosing := enclosingFunctionOf(node)
				if enclosing == nil || !isPromiseExecutorFunction(ctx, enclosing) {
					return
				}

				if !allowVoid {

					ctx.ReportNode(node, messageNoPromiseExecutorReturn)
					return
				}
				if unwrapParentheses(argument).Kind == ast.KindVoidExpression {
					return
				}
				ctx.ReportNodeWithSuggestions(node, messageNoPromiseExecutorReturn,
					promiseExecutorPrependVoidSuggestion(ctx, argument))
			},
		}
	},
}

