var NoRestrictedProperties = rule.Rule{
	Name: "no-restricted-properties",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, configured := rule.OptionsAs[NoRestrictedPropertiesOptions](options)
		if !configured || len(settings.Restrictions) == 0 {

			return rule.Listeners{}
		}
		index := buildNoRestrictedPropertiesIndex(settings.Restrictions)

		return rule.Listeners{
			ast.KindPropertyAccessExpression: func(node *ast.Node) {
				checkNoRestrictedPropertiesAccess(ctx, node, index)
			},
			ast.KindElementAccessExpression: func(node *ast.Node) {
				checkNoRestrictedPropertiesAccess(ctx, node, index)
			},
			ast.KindObjectBindingPattern: func(node *ast.Node) {
				checkNoRestrictedPropertiesPattern(ctx, node, index)
			},

			ast.KindObjectLiteralExpression: func(node *ast.Node) {
				checkNoRestrictedPropertiesAssignmentPattern(ctx, node, index)
			},
		}
	},
}

var NoReturnAssign = rule.Rule{
	Name: "no-return-assign",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		always := false
		if mode, configured := rule.OptionsAs[NoReturnAssignOptions](options); configured && mode == NoReturnAssignAlways {
			always = true
		}

		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				if !isAssignmentExpression(node) {
					return
				}
				if !always && isPositionallyParenthesized(ctx.SourceFile, node) {
					return
				}

				child, sentinel := climbToTheEnclosingSentinel(node)
				if sentinel == nil {
					return
				}

				switch sentinel.Kind {
				case ast.KindReturnStatement:
					ctx.ReportNode(sentinel, messageReturnAssignment)
				case ast.KindArrowFunction:

					if sentinel.AsArrowFunction().Body == child {
						ctx.ReportNode(sentinel, messageArrowAssignment)
					}
				}
			},
		}
	},
}

var NoScriptUrl = rule.Rule{
	Name: "no-script-url",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindStringLiteral: func(node *ast.Node) {
				if !beginsWithScriptScheme(node.Text()) {
					return
				}
				ctx.ReportNode(node, messageScriptUrl)
			},

			ast.KindNoSubstitutionTemplateLiteral: func(node *ast.Node) {

				if node.Parent != nil && node.Parent.Kind == ast.KindTaggedTemplateExpression {
					return
				}
				if !beginsWithScriptScheme(node.Text()) {
					return
				}
				ctx.ReportNode(node, messageScriptUrl)
			},
		}
	},
}

var messageSelfAssignment = rule.Message{
	Id: "selfAssignment",
	Description: "This assigns a value to itself, so it does nothing. The statement is not merely " +
		"redundant: it is almost always a typo for an assignment that was meant to happen, so the " +
		"value the author intended to write is still missing and nothing reports that it is.",
}

var NoSelfAssign = rule.Rule{
	Name: "no-self-assign",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		props := DefaultNoSelfAssignOptions().Props
		if resolved, isNoSelfAssignOptions := rule.OptionsAs[NoSelfAssignOptions](options); isNoSelfAssignOptions {
			props = resolved.Props
		}

		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil {
					return
				}
				switch binary.OperatorToken.Kind {
				case ast.KindEqualsToken,
					ast.KindAmpersandAmpersandEqualsToken,
					ast.KindBarBarEqualsToken,
					ast.KindQuestionQuestionEqualsToken:
				default:
					return
				}

				if ast.IsAssignmentTarget(node) {
					return
				}

				reportSelfAssignments(ctx, binary.Left, binary.Right, props)
			},
		}
	},
}

var NoSelfCompare = rule.Rule{
	Name: "no-self-compare",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				binaryExpression := node.AsBinaryExpression()
				if binaryExpression == nil || binaryExpression.OperatorToken == nil {
					return
				}
				if !noSelfCompareOperators[binaryExpression.OperatorToken.Kind] {
					return
				}
				if hasSameTokens(ctx.SourceFile, binaryExpression.Left, binaryExpression.Right) {
					ctx.ReportNode(node, messageNoSelfCompareComparingToSelf)
				}
			},
		}
	},
}

var NoSequences = rule.Rule{
	Name: "no-sequences",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		var settings NoSequencesOptions
		if parsed, ok := rule.OptionsAs[NoSequencesOptions](options); ok {
			settings = parsed
		}
		allowInParentheses := settings.allowInParentheses()

		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				if node.AsBinaryExpression().OperatorToken.Kind != ast.KindCommaToken {
					return
				}

				if isCommaExpression(node.Parent) {
					return
				}

				if standsInForHeaderSlot(node) {
					return
				}

				if allowInParentheses && parenthesizedEnough(node) {
					return
				}

				comma := leftmostCommaOf(ctx, node)
				if comma == nil {
					return
				}
				ctx.ReportRange(*comma, messageUnexpectedCommaExpression)
			},
		}
	},
}

var NoSetterReturn = rule.Rule{
	Name: "no-setter-return",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		isGlobal := func(identifier *ast.Node) bool {
			return ctx.TypeChecker != nil && rule.IsDeclaredOnlyInDeclarationFiles(ctx.TypeChecker.GetSymbolAtLocation(identifier))
		}
		report := func(node *ast.Node) {
			ctx.ReportNode(node, rule.Message{
				Id: "noSetterReturn",
				Description: "This returns a value from a setter, and the language discards " +
					"it: an assignment evaluates to the value assigned, never to what the " +
					"setter returned, so nothing can ever read this. Either the value is dead " +
					"and the return should be bare, or it was meant to reach a caller and this " +
					"is a bug that stays silent at runtime.",
			})
		}

		return rule.Listeners{

			ast.KindArrowFunction: func(node *ast.Node) {
				body := node.AsArrowFunction().Body
				if body == nil || body.Kind == ast.KindBlock {
					return
				}
				if descriptor.IsFunctionUnder(node, "set", isGlobal) {
					report(body)
				}
			},
			ast.KindReturnStatement: func(node *ast.Node) {
				statement := node.AsReturnStatement()

				if statement == nil || statement.Expression == nil {
					return
				}

				function := enclosingFunction(node)
				if function == nil {
					return
				}
				if ast.IsSetAccessorDeclaration(function) || descriptor.IsFunctionUnder(function, "set", isGlobal) {
					report(node)
				}
			},
		}
	},
}

var NoShadowRestrictedNames = rule.Rule{
	Name: "no-shadow-restricted-names",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings := NoShadowRestrictedNamesOptions{}
		if configured, isConfigured := rule.OptionsAs[NoShadowRestrictedNamesOptions](options); isConfigured {
			settings = configured
		}

		isRestricted := func(name string) bool {
			if restrictedNames[name] {
				return true
			}
			return name == "globalThis" && !settings.AllowGlobalThis
		}

		report := func(name *ast.Node) {
			if name == nil || name.Kind != ast.KindIdentifier || !isRestricted(name.Text()) {
				return
			}
			if name.Text() == "undefined" && safelyShadowsUndefined(ctx, name) {
				return
			}
			ctx.ReportNode(name, messageShadowingRestrictedName)
		}

		reportName := func(node *ast.Node) { report(node.Name()) }

		return rule.Listeners{

			ast.KindVariableDeclaration: reportName,

			ast.KindBindingElement: reportName,

			ast.KindParameter: reportName,

			ast.KindFunctionDeclaration: reportName,
			ast.KindFunctionExpression:  reportName,

			ast.KindClassDeclaration: reportName,
			ast.KindClassExpression:  reportName,

			ast.KindImportClause: reportName,

			ast.KindImportSpecifier: reportName,

			ast.KindNamespaceImport: reportName,
		}
	},
}

var NoSparseArrays = rule.Rule{
	Name: "no-sparse-arrays",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindArrayLiteralExpression: func(node *ast.Node) {
				literal := node.AsArrayLiteralExpression()
				if literal == nil || literal.Elements == nil {
					return
				}

				if ast.IsAssignmentTarget(node) {
					return
				}

				for _, element := range literal.Elements.Nodes {
					if element.Kind == ast.KindOmittedExpression {
						ctx.ReportNode(node, messageUnexpectedSparseArray)
						return
					}
				}
			},
		}
	},
}

var NoTemplateCurlyInString = rule.Rule{
	Name: "no-template-curly-in-string",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindStringLiteral: func(node *ast.Node) {
				if !containsTemplatePlaceholder(node.Text()) {
					return
				}
				ctx.ReportNode(node, messageTemplateCurlyInString)
			},
		}
	},
}

var NoThisBeforeSuper = rule.Rule{
	Name: "no-this-before-super",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		check := func(constructor *ast.Node) {
			if !isDerivedClassConstructor(constructor) {
				return
			}
			declaration := constructor.AsConstructorDeclaration()

			if declaration.Body == nil {
				return
			}

			scanner := &superScanner{}

			violated := false
			if declaration.Parameters != nil {
				for _, parameter := range declaration.Parameters.Nodes {
					if scanner.scanStatements(parameter) {
						violated = true
						break
					}
				}
			}
			if !violated && !scanner.scanStatements(declaration.Body.AsNode()) {
				return
			}
			ctx.ReportRange(rule.TokenRange(ctx.SourceFile, constructor), rule.Message{
				Id: "thisBeforeSuper",
				Description: "This derived constructor reads `this` or `super` on a path that has " +
					"not called `super()` yet, which throws a ReferenceError because the `this` " +
					"binding does not exist until `super()` returns.",
			})
		}

		return rule.Listeners{
			ast.KindConstructor: check,
		}
	},
}

var messageNoThrowLiteralUndef = rule.Message{
	Id: "undef",
	Description: "This throws `undefined`, which reaches the handler carrying nothing at all: no " +
		"message, no stack, no type. It is almost always an expression that was meant to produce " +
		"an error and did not. Throw `new Error(...)` instead.",
}

var NoThrowLiteral = rule.Rule{
	Name:             "no-throw-literal",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindThrowStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				argument := node.AsThrowStatement().Expression
				if argument == nil {

					return
				}

				if !couldBeError(argument) {
					ctx.ReportNode(node, messageNoThrowLiteralObject)
					return
				}

				if argument.Kind == ast.KindIdentifier && argument.Text() == "undefined" &&
					!undefinedIsShadowed(ctx, argument) {
					ctx.ReportNode(node, messageNoThrowLiteralUndef)
				}
			},
		}
	},
}

var NoUnassignedVars = rule.Rule{
	Name: "no-unassigned-vars",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}

				declaration := node.AsVariableDeclaration()

				if declaration.Initializer != nil {
					return
				}

				name := node.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}

				if ast.IsVarConstLike(node) ||
					ast.GetCombinedNodeFlags(node)&ast.NodeFlagsAmbient != 0 {
					return
				}

				if node.Parent != nil && node.Parent.Kind == ast.KindCatchClause {
					return
				}

				if list := node.Parent; list != nil && list.Parent != nil {
					switch list.Parent.Kind {
					case ast.KindForStatement, ast.KindForInStatement, ast.KindForOfStatement:
						return
					}
				}

				if isInsideModuleDeclaration(node) {
					return
				}

				anchor := declarationAnchoredAt(ctx, name)
				if anchor == nil {
					return
				}

				sourceFile := ast.GetSourceFileOfNode(node)
				if sourceFile == nil {
					return
				}

				hasRead := false
				hasWrite := false

				var visit func(*ast.Node)
				visit = func(current *ast.Node) {
					if current == nil || hasWrite {
						return
					}

					if current.Kind == ast.KindIdentifier && current.Text() == name.Text() &&
						current != name && resolvesToDeclaration(ctx, current, anchor) {
						if reference.WritesToBinding(current) {

							hasWrite = true
							return
						}
						hasRead = true
					}

					current.ForEachChild(func(child *ast.Node) bool {
						visit(child)
						return false
					})
				}
				visit(sourceFile.AsNode())

				if hasWrite || !hasRead {
					return
				}

				ctx.ReportNode(name, messageNoUnassignedVars)
			},
		}
	},
}

var NoUndefInit = rule.Rule{
	Name:             "no-undef-init",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				declaration := node.AsVariableDeclaration()
				if declaration == nil || declaration.Initializer == nil {
					return
				}

				initializer := declaration.Initializer
				if initializer.Kind != ast.KindIdentifier || initializer.Text() != "undefined" {
					return
				}

				if ast.IsVarConstLike(node) {
					return
				}

				if undefinedIsShadowed(ctx, initializer) {
					return
				}

				name := declaration.Name()
				if name == nil {
					return
				}

				message := buildNoUndefInitMessage(ctx.SourceFile.Text()[rule.TokenRange(ctx.SourceFile, name).Pos():name.End()])
				if fix, offered := noUndefInitFix(ctx, node, name); offered {
					ctx.ReportNodeWithFixes(node, message, fix)
					return
				}
				ctx.ReportNode(node, message)
			},
		}
	},
}

var messageNoUnderscoreDangle = rule.Message{
	Id: "unexpectedUnderscore",
	Description: "A leading or trailing underscore is a convention for privacy that the language " +
		"does not enforce, so it tells a reader something is off limits while doing nothing to " +
		"keep them out. Where privacy is real, `#private` or a closure says so and is checked.",
}

var NoUnderscoreDangle = rule.Rule{
	Name: "no-underscore-dangle",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[NoUnderscoreDangleOptions](options)

		reportNamed := func(node *ast.Node, identifier string) {
			ctx.ReportNode(node, rule.Message{
				Id: messageNoUnderscoreDangle.Id,
				Description: fmt.Sprintf("Unexpected dangling '_' in '%s'. %s",
					identifier, messageNoUnderscoreDangle.Description),
			})
		}

		checkFunction := func(node *ast.Node) {

			if node.Kind == ast.KindFunctionDeclaration {
				if name := node.Name(); name != nil && name.Kind == ast.KindIdentifier {
					if noUnderscoreDangleReportable(name.Text(), settings) {
						reportNamed(node, name.Text())
					}
				}
			}
			if noUnderscoreDangleFlag(settings.AllowFunctionParams, true) {
				return
			}
			functionLike := node.FunctionLikeData()
			if functionLike == nil || functionLike.Parameters == nil {
				return
			}
			for _, parameter := range functionLike.Parameters.Nodes {

				name := parameter.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					continue
				}
				if noUnderscoreDangleReportable(name.Text(), settings) {

					reportNamed(parameter, name.Text())
				}
			}
		}

		checkMember := func(node *ast.Node, expression *ast.Node, name *ast.Node) {
			if name == nil || name.Kind != ast.KindIdentifier {
				return
			}
			identifier := name.Text()
			if !noUnderscoreDangleHasDanglingUnderscore(identifier) {
				return
			}
			if expression != nil {
				if expression.Kind == ast.KindThisKeyword && settings.AllowAfterThis {
					return
				}
				if expression.Kind == ast.KindSuperKeyword && settings.AllowAfterSuper {
					return
				}
				if settings.AllowAfterThisConstructor &&
					noUnderscoreDangleIsThisConstructor(expression) {
					return
				}
			}

			if identifier == "__proto__" {
				return
			}
			if slices.Contains(settings.Allow, identifier) {
				return
			}
			reportNamed(node, identifier)
		}

		checkMemberName := func(node *ast.Node, gated bool) {
			if !gated {
				return
			}
			name := node.Name()
			if name == nil {
				return
			}

			identifier := name.Text()
			bare := identifier
			if name.Kind == ast.KindPrivateIdentifier {
				bare = identifier[1:]
			} else if name.Kind != ast.KindIdentifier {

				return
			}
			if !noUnderscoreDangleHasDanglingUnderscore(bare) {
				return
			}
			if slices.Contains(settings.Allow, bare) {
				return
			}
			reportNamed(node, identifier)
		}

		return rule.Listeners{
			ast.KindFunctionDeclaration: checkFunction,
			ast.KindFunctionExpression:  checkFunction,
			ast.KindArrowFunction:       checkFunction,

			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()
				noUnderscoreDangleWalkBindings(declaration.Name(), declaration.Name(),
					func(name string, coinedBy ast.Kind) {
						if !noUnderscoreDangleReportable(name, settings) {
							return
						}
						if coinedBy == ast.KindArrayBindingPattern &&
							noUnderscoreDangleFlag(settings.AllowInArrayDestructuring, true) {
							return
						}
						if coinedBy == ast.KindObjectBindingPattern &&
							noUnderscoreDangleFlag(settings.AllowInObjectDestructuring, true) {
							return
						}

						reportNamed(node, name)
					})
			},

			ast.KindPropertyAccessExpression: func(node *ast.Node) {
				access := node.AsPropertyAccessExpression()
				checkMember(node, access.Expression, access.Name())
			},

			ast.KindMethodDeclaration: func(node *ast.Node) {
				checkMemberName(node, settings.EnforceInMethodNames)

				checkFunction(node)
			},
			ast.KindPropertyDeclaration: func(node *ast.Node) {
				checkMemberName(node, settings.EnforceInClassFields)
			},
		}
	},
}

var messageUnexpectedMultilineFunction = rule.Message{
	Id: "function",
	Description: "A newline sits between this expression and the `(` that follows it, so what reads " +
		"as two statements is one call. Automatic semicolon insertion does not fire before an open " +
		"paren, so the line above is being invoked rather than ended.",
}

var messageUnexpectedMultilineProperty = rule.Message{
	Id: "property",
	Description: "A newline sits between this expression and the `[` that follows it, so what reads " +
		"as an array on its own line is a computed property access on the line above. Automatic " +
		"semicolon insertion does not fire before an open bracket.",
}

var messageUnexpectedMultilineTaggedTemplate = rule.Message{
	Id: "taggedTemplate",
	Description: "A newline sits between this expression and the template literal that follows it, " +
		"so the template is being used as a tag argument rather than standing alone. Automatic " +
		"semicolon insertion does not fire before a backtick.",
}

var messageUnexpectedMultilineDivision = rule.Message{
	Id: "division",
	Description: "A newline sits between the numerator and the `/` that follows it, and what comes " +
		"after reads as a regular expression with flags rather than a division. The two parse " +
		"differently and only one of them is what the line above looks like.",
}

var NoUnexpectedMultiline = rule.Rule{
	Name: "no-unexpected-multiline",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		text := ctx.SourceFile.Text()

		reportIfLineBreaks := func(expression *ast.Node, message rule.Message) {
			if expression == nil {
				return
			}
			openToken := scanner.SkipTrivia(text, expression.End())
			if openToken >= len(text) {
				return
			}

			if scanner.GetECMALineOfPosition(ctx.SourceFile, expression.End()-1) ==
				scanner.GetECMALineOfPosition(ctx.SourceFile, openToken) {
				return
			}
			ctx.ReportRange(core.NewTextRange(openToken, openToken+1), message)
		}

		return rule.Listeners{
			ast.KindElementAccessExpression: func(node *ast.Node) {
				access := node.AsElementAccessExpression()

				if access.QuestionDotToken != nil {
					return
				}
				reportIfLineBreaks(access.Expression, messageUnexpectedMultilineProperty)
			},

			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()
				if call.QuestionDotToken != nil {
					return
				}

				if call.Arguments == nil || len(call.Arguments.Nodes) == 0 {
					return
				}
				reportIfLineBreaks(call.Expression, messageUnexpectedMultilineFunction)
			},

			ast.KindTaggedTemplateExpression: func(node *ast.Node) {
				tagged := node.AsTaggedTemplateExpression()
				if tagged.Template == nil {
					return
				}

				templateToken := scanner.GetRangeOfTokenAtPosition(ctx.SourceFile, tagged.Template.Pos()).Pos()
				if templateToken >= len(text) {
					return
				}

				lastTokenEnd := tagged.Tag.End()
				if tagged.TypeArguments != nil && tagged.TypeArguments.End() > lastTokenEnd {
					closingAngle := scanner.SkipTrivia(text, tagged.TypeArguments.End())
					if closingAngle >= len(text) {
						return
					}
					lastTokenEnd = closingAngle + 1
				}

				if lastTokenEnd <= 0 {
					return
				}
				if scanner.GetECMALineOfPosition(ctx.SourceFile, lastTokenEnd-1) ==
					scanner.GetECMALineOfPosition(ctx.SourceFile, templateToken) {
					return
				}
				ctx.ReportRange(core.NewTextRange(templateToken, templateToken+1),
					messageUnexpectedMultilineTaggedTemplate)
			},

			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil || binary.OperatorToken.Kind != ast.KindSlashToken {
					return
				}

				left := binary.Left
				if left == nil || left.Kind != ast.KindBinaryExpression {
					return
				}
				leftBinary := left.AsBinaryExpression()
				if leftBinary.OperatorToken == nil || leftBinary.OperatorToken.Kind != ast.KindSlashToken {
					return
				}

				flagsStart := binary.OperatorToken.End()
				flagsEnd := flagsStart
				for flagsEnd < len(text) && noUnexpectedMultilineIsFlagCharacter(text[flagsEnd]) {
					flagsEnd++
				}
				if flagsEnd == flagsStart {
					return
				}

				if flagsEnd < len(text) && scanner.IsIdentifierPart(rune(text[flagsEnd])) {
					return
				}
				reportIfLineBreaks(leftBinary.Left, messageUnexpectedMultilineDivision)
			},
		}
	},
}

var NoUnmodifiedLoopCondition = rule.Rule{
	Name: "no-unmodified-loop-condition",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		judged := false
		judge := func(node *ast.Node) {
			if judged || ctx.TypeChecker == nil || unmodifiedLoopTestOf(node) == nil {
				return
			}
			judged = true
			reportUnmodifiedLoopConditions(ctx)
		}
		return rule.Listeners{
			ast.KindWhileStatement: judge,
			ast.KindDoStatement:    judge,
			ast.KindForStatement:   judge,
		}
