var messageUnsafeFinallyBreak = rule.Message{
	Id: "unsafeBreak",
	Description: "A `break` inside `finally` leaves the try statement before the pending return or " +
		"throw can complete, so the value is discarded and the exception never surfaces. Execution " +
		"continues after the loop as though nothing had failed.",
}

var messageUnsafeFinallyContinue = rule.Message{
	Id: "unsafeContinue",
	Description: "A `continue` inside `finally` leaves the try statement before the pending return " +
		"or throw can complete, so the value is discarded and the exception never surfaces. The loop " +
		"advances to its next iteration as though nothing had failed.",
}

var NoUnsafeFinally = rule.Rule{
	Name: "no-unsafe-finally",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindReturnStatement: func(node *ast.Node) {
				if escapesIntoFinally(node, stopsReturnOrThrow, nil) {
					ctx.ReportNode(node, messageUnsafeFinallyReturn)
				}
			},

			ast.KindThrowStatement: func(node *ast.Node) {
				if escapesIntoFinally(node, stopsReturnOrThrow, nil) {
					ctx.ReportNode(node, messageUnsafeFinallyThrow)
				}
			},

			ast.KindBreakStatement: func(node *ast.Node) {
				breakStatement := node.AsBreakStatement()
				if breakStatement == nil {
					return
				}

				if breakStatement.Label != nil {
					if escapesIntoFinally(node, stopsReturnOrThrow, breakStatement.Label) {
						ctx.ReportNode(node, messageUnsafeFinallyBreak)
					}
					return
				}
				if escapesIntoFinally(node, stopsUnlabeledBreak, nil) {
					ctx.ReportNode(node, messageUnsafeFinallyBreak)
				}
			},

			ast.KindContinueStatement: func(node *ast.Node) {
				continueStatement := node.AsContinueStatement()
				if continueStatement == nil {
					return
				}

				if continueStatement.Label != nil {
					if escapesIntoFinally(node, stopsContinue, continueStatement.Label) {
						ctx.ReportNode(node, messageUnsafeFinallyContinue)
					}
					return
				}
				if escapesIntoFinally(node, stopsContinue, nil) {
					ctx.ReportNode(node, messageUnsafeFinallyContinue)
				}
			},
		}
	},
}

var relationalOperatorText = map[ast.Kind]string{
	ast.KindInKeyword:         "in",
	ast.KindInstanceOfKeyword: "instanceof",
}

var orderingOperatorText = map[ast.Kind]string{
	ast.KindLessThanToken:          "<",
	ast.KindLessThanEqualsToken:    "<=",
	ast.KindGreaterThanToken:       ">",
	ast.KindGreaterThanEqualsToken: ">=",
}

var NoUnsafeNegation = rule.Rule{
	Name: "no-unsafe-negation",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		enforceForOrderingRelations := false
		if parsed, ok := rule.OptionsAs[NoUnsafeNegationOptions](options); ok {
			enforceForOrderingRelations = parsed.EnforceForOrderingRelations
		}

		return rule.Listeners{

			ast.KindBinaryExpression: func(node *ast.Node) {
				binaryExpression := node.AsBinaryExpression()
				if binaryExpression == nil || binaryExpression.OperatorToken == nil ||
					binaryExpression.Left == nil || binaryExpression.Right == nil {
					return
				}

				operatorText, isChecked := relationalOperatorText[binaryExpression.OperatorToken.Kind]
				if !isChecked && enforceForOrderingRelations {
					operatorText, isChecked = orderingOperatorText[binaryExpression.OperatorToken.Kind]
				}
				if !isChecked {
					return
				}

				left := binaryExpression.Left
				if left.Kind != ast.KindPrefixUnaryExpression {
					return
				}
				prefixExpression := left.AsPrefixUnaryExpression()
				if prefixExpression == nil || prefixExpression.Operator != ast.KindExclamationToken ||
					prefixExpression.Operand == nil {
					return
				}

				sourceText := ctx.SourceFile.Text()
				operandRange := rule.TokenRange(ctx.SourceFile, prefixExpression.Operand)
				rightRange := rule.TokenRange(ctx.SourceFile, binaryExpression.Right)
				negationRange := rule.TokenRange(ctx.SourceFile, left)
				operandText := sourceText[operandRange.Pos():operandRange.End()]
				rightText := sourceText[rightRange.Pos():rightRange.End()]
				negationText := sourceText[negationRange.Pos():negationRange.End()]

				ctx.ReportNodeWithSuggestions(left, rule.Message{
					Id:          "unexpected",
					Description: describeUnsafeNegation(operatorText),
				}, rule.Suggestion{
					Message: rule.Message{
						Id: "negateTheComparison",
						Description: "Negate the whole `" + operatorText + "` comparison, which is " +
							"what the parentheses in `!(a " + operatorText + " b)` say and is " +
							"almost certainly the intent. This changes what the code does.",
					},
					Fixes: []rule.Fix{ctx.ReplaceNode(node,
						"!("+operandText+" "+operatorText+" "+rightText+")")},
				}, rule.Suggestion{
					Message: rule.Message{
						Id: "parenthesiseTheNegation",
						Description: "Wrap the negation in parentheses to say the `!` was meant to " +
							"apply to the left operand alone. This preserves what the code does " +
							"today and only makes it explicit.",
					},
					Fixes: []rule.Fix{ctx.ReplaceNode(left, "("+negationText+")")},
				})
			},
		}
	},
}

var relationalOperators = map[ast.Kind]bool{
	ast.KindInKeyword:         true,
	ast.KindInstanceOfKeyword: true,
}

var NoUnsafeOptionalChaining = rule.Rule{
	Name: "no-unsafe-optional-chaining",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		disallowArithmeticOperators := false
		if settings, hasSettings := rule.OptionsAs[NoUnsafeOptionalChainingOptions](options); hasSettings {
			disallowArithmeticOperators = settings.DisallowArithmeticOperators
		}

		reportUnsafeUsage := func(node *ast.Node) {
			reportChainsReaching(ctx, node, messageUnsafeOptionalChain)
		}
		reportUnsafeArithmetic := func(node *ast.Node) {
			reportChainsReaching(ctx, node, messageUnsafeArithmetic)
		}

		listeners := rule.Listeners{

			ast.KindPropertyAccessExpression: func(node *ast.Node) {
				if !ast.IsOptionalChainRoot(node) {
					reportUnsafeUsage(node.Expression())
				}
			},
			ast.KindElementAccessExpression: func(node *ast.Node) {
				if !ast.IsOptionalChainRoot(node) {
					reportUnsafeUsage(node.Expression())
				}
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if !ast.IsOptionalChainRoot(node) {
					reportUnsafeUsage(node.Expression())
				}
			},

			ast.KindNewExpression: func(node *ast.Node) {
				reportUnsafeUsage(node.Expression())
			},
			ast.KindTaggedTemplateExpression: func(node *ast.Node) {
				reportUnsafeUsage(node.AsTaggedTemplateExpression().Tag)
			},

			ast.KindForOfStatement: func(node *ast.Node) {
				reportUnsafeUsage(node.AsForInOrOfStatement().Expression)
			},
			ast.KindWithStatement: func(node *ast.Node) {
				reportUnsafeUsage(node.AsWithStatement().Expression)
			},

			ast.KindClassDeclaration: func(node *ast.Node) {
				reportUnsafeUsage(classHeritageExpression(node))
			},
			ast.KindClassExpression: func(node *ast.Node) {
				reportUnsafeUsage(classHeritageExpression(node))
			},

			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()
				if isDestructuringPattern(declaration.Name()) {
					reportUnsafeUsage(declaration.Initializer)
				}
			},

			ast.KindParameter: func(node *ast.Node) {
				parameter := node.AsParameterDeclaration()
				if isDestructuringPattern(parameter.Name()) {
					reportUnsafeUsage(parameter.Initializer)
				}
			},
			ast.KindBindingElement: func(node *ast.Node) {
				element := node.AsBindingElement()
				if isDestructuringPattern(element.Name()) {
					reportUnsafeUsage(element.Initializer)
				}
			},

			ast.KindSpreadElement: func(node *ast.Node) {
				reportUnsafeUsage(node.Expression())
			},
			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				operator := binary.OperatorToken.Kind

				if relationalOperators[operator] {
					reportUnsafeUsage(binary.Right)
				}

				if operator == ast.KindEqualsToken && isDestructuringPattern(binary.Left) {
					reportUnsafeUsage(binary.Right)
					return
				}

				if !disallowArithmeticOperators {
					return
				}

				if arithmeticOperators[operator] {
					reportUnsafeArithmetic(binary.Right)
					reportUnsafeArithmetic(binary.Left)
					return
				}

				if arithmeticAssignmentOperators[operator] {
					reportUnsafeArithmetic(binary.Right)
				}
			},
			ast.KindPrefixUnaryExpression: func(node *ast.Node) {
				if !disallowArithmeticOperators {
					return
				}
				unary := node.AsPrefixUnaryExpression()

				if unary.Operator == ast.KindPlusToken || unary.Operator == ast.KindMinusToken {
					reportUnsafeArithmetic(unary.Operand)
				}
			},
		}

		return listeners
	},
}

