var preferNumericLiteralsRadix = map[int]struct {
	system string
	prefix string
}{
	2:  {"binary", "0b"},
	8:  {"octal", "0o"},
	16: {"hexadecimal", "0x"},
}

var PreferNumericLiterals = rule.Rule{
	Name:             "prefer-numeric-literals",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				call := node.AsCallExpression()
				if call.Arguments == nil || len(call.Arguments.Nodes) != 2 {
					return
				}

				stringValue, hasStringValue := preferNumericLiteralsStringValue(call.Arguments.Nodes[0])
				if !hasStringValue {
					return
				}
				radix, hasRadix := preferNumericLiteralsRadixValue(call.Arguments.Nodes[1])
				if !hasRadix {
					return
				}
				spelling, isSpellable := preferNumericLiteralsRadix[radix]
				if !isSpellable {
					return
				}
				if !preferNumericLiteralsIsParseInt(ctx, call.Expression) {
					return
				}

				calleeRange := rule.TokenRange(ctx.SourceFile, call.Expression)
				functionName := ctx.SourceFile.Text()[calleeRange.Pos():calleeRange.End()]
				message := preferNumericLiteralsMessage(spelling.system, functionName)

				if fix, canFix := preferNumericLiteralsFix(ctx, node, spelling.prefix, stringValue,
					radix); canFix {
					ctx.ReportNodeWithFixes(node, message, fix)
					return
				}
				ctx.ReportNode(node, message)
			},
		}
	},
}

var PreferObjectHasOwn = rule.Rule{
	Name:             "prefer-object-has-own",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				callee := preferObjectHasOwnUnwrap(node.AsCallExpression().Expression)
				if !preferObjectHasOwnIsMemberAccess(callee) {
					return
				}
				calleeObject := preferObjectHasOwnUnwrap(preferObjectHasOwnAccessedObject(callee))
				if !preferObjectHasOwnIsMemberAccess(calleeObject) {
					return
				}

				if name, isStatic := property.AccessedName(callee, property.Static); !isStatic ||
					name != "call" {
					return
				}
				if name, isStatic := property.AccessedName(calleeObject, property.Static); !isStatic ||
					name != "hasOwnProperty" {
					return
				}
				if !preferObjectHasOwnHasLeftHandObject(ctx, calleeObject) {
					return
				}

				if fix, canFix := preferObjectHasOwnFix(ctx, callee); canFix {
					ctx.ReportNodeWithFixes(node, messagePreferObjectHasOwn, fix)
					return
				}
				ctx.ReportNode(node, messagePreferObjectHasOwn)
			},
		}
	},
}

