var PreferRestParams = rule.Rule{
	Name: "prefer-rest-params",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindIdentifier: func(node *ast.Node) {
				if node.Text() != "arguments" {
					return
				}
				if !isImplicitArgumentsBinding(ctx, node) {
					return
				}
				if isNormalMemberAccess(node) {
					return
				}

				ctx.ReportNode(node, rule.Message{
					Id: "preferRestParams",
					Description: "This reads the implicit `arguments` object, which is array-like " +
						"rather than an array and carries none of `Array.prototype`, so iterating " +
						"or slicing it needs a conversion first. Declare a rest parameter " +
						"(`...args`) and use that instead.",
				})
			},
		}
	},
}

var PreferSpread = rule.Rule{
	Name: "prefer-spread",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				callExpression := node.AsCallExpression()
				if callExpression == nil || callExpression.Arguments == nil {
					return
				}

				arguments := callExpression.Arguments.Nodes
				if len(arguments) != 2 {
					return
				}

				callee := ast.SkipParentheses(callExpression.Expression)
				if callee == nil || !isApplyMemberAccess(callee) {
					return
				}

				secondArgument := ast.SkipParentheses(arguments[1])
				if secondArgument == nil ||
					secondArgument.Kind == ast.KindArrayLiteralExpression ||
					secondArgument.Kind == ast.KindSpreadElement {
					return
				}

				appliedFunction := ast.SkipParentheses(memberAccessObject(callee))
				if appliedFunction == nil {
					return
				}

				thisArgument := ast.SkipParentheses(arguments[0])
				if thisArgument == nil {
					return
				}

				expectedReceiver := memberAccessObject(appliedFunction)
				if expectedReceiver == nil {
					if !isNullOrUndefined(thisArgument) {
						return
					}
					ctx.ReportNode(node, messagePreferSpread)
					return
				}

				if !hasSameTokens(ctx.SourceFile, expectedReceiver, thisArgument) {
					return
				}

				ctx.ReportNode(node, messagePreferSpread)
			},
		}
	},
}

var PreferTemplate = rule.Rule{
	Name: "prefer-template",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		reported := map[*ast.Node]bool{}

		check := func(node *ast.Node) {
			if !preferTemplateIsStringLiteral(node) {
				return
			}
			if node.Parent == nil || !preferTemplateIsConcatenation(node.Parent) {
				return
			}
			top := preferTemplateTopConcatenation(node.Parent)
			if reported[top] {
				return
			}
			reported[top] = true

			if !preferTemplateHasNonStringLiteral(top) {
				return
			}
			if fixes, repairable := preferTemplateFix(ctx, top); repairable {
				ctx.ReportNodeWithFixes(top, messagePreferTemplateUnexpectedStringConcatenation, fixes...)
				return
			}
			ctx.ReportNode(top, messagePreferTemplateUnexpectedStringConcatenation)
		}

		return rule.Listeners{
			ast.KindStringLiteral:                 check,
			ast.KindNoSubstitutionTemplateLiteral: check,
			ast.KindTemplateExpression:            check,
			ast.KindNumericLiteral:                check,
			ast.KindBigIntLiteral:                 check,
			ast.KindTrueKeyword:                   check,
			ast.KindFalseKeyword:                  check,
			ast.KindNullKeyword:                   check,
			ast.KindRegularExpressionLiteral:      check,
		}
	},
}

