var Strict = rule.Rule{
	Name: "strict",

	ProgramReads: rule.ReadsCompilerOptions,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		mode := StrictSafe
		if decoded, configured := rule.OptionsAs[StrictMode](options); configured {
			mode = decoded
		}
		return rule.Listeners{
			ast.KindSourceFile: func(file *ast.Node) {
				checkStrict(ctx, file, mode)
			},
		}
	},
}

var SymbolDescription = rule.Rule{
	Name:             "symbol-description",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}

				call := node.AsCallExpression()
				if call.Expression == nil {
					return
				}

				if call.Arguments != nil && len(call.Arguments.Nodes) != 0 {
					return
				}

				callee := ast.SkipParentheses(call.Expression)
				if !ast.IsIdentifier(callee) || callee.Text() != "Symbol" {
					return
				}
				if !resolvesToAGlobal(ctx, callee) {
					return
				}

				ctx.ReportNode(node, messageSymbolDescription)
			},
		}
	},
}

var messageUnicodeBomExpected = rule.Message{
	Id: "expected",
	Description: "This file is configured to start with a byte order mark and does not. The mark " +
		"is what tells a reader that has no other signal which encoding and endianness the bytes " +
		"are in, so a project that requires it wants every file to carry it rather than most.",
}

var UnicodeBom = rule.Rule{
	Name: "unicode-bom",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		settings, _ := rule.OptionsAs[UnicodeBomOptions](options)
		if settings.Require == nil {
			settings = DefaultUnicodeBomSettings()
		}
		require := *settings.Require

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				hasMark := strings.HasPrefix(ctx.SourceFile.Text(), unicodeBomMark)

				start := core.NewTextRange(0, 0)

				switch {
				case require == UnicodeBomAlways && !hasMark:
					ctx.ReportRangeWithFixes(start, messageUnicodeBomExpected,
						rule.ReplaceRange(start, unicodeBomMark))
				case require == UnicodeBomNever && hasMark:
					markRange := core.NewTextRange(0, len(unicodeBomMark))
					ctx.ReportRangeWithFixes(start, messageUnicodeBomUnexpected,
						rule.RemoveRange(markRange))
				}
			},
		}
	},
}

var messageSwitchOnNaN = rule.Message{
	Id: "switchOnNaN",
	Description: "This switch tests NaN against each case, and NaN equals nothing including " +
		"itself, so every case is dead and only the default runs. Whatever this switch was " +
		"written to dispatch on, it dispatches on nothing.",
}

var UseIsNaN = rule.Rule{
	Name: "use-isnan",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {

		enforceForSwitchCase := true
		settings, hasSettings := rule.OptionsAs[UseIsNaNOptions](options)
		if hasSettings && settings.EnforceForSwitchCase != nil {
			enforceForSwitchCase = *settings.EnforceForSwitchCase
		}

		return rule.Listeners{
			ast.KindSwitchStatement: func(node *ast.Node) {
				if !enforceForSwitchCase {
					return
				}

				statement := node.AsSwitchStatement()

				if isNaNReference(ctx, statement.Expression) {
					ctx.ReportNode(node, messageSwitchOnNaN)
				}

				if statement.CaseBlock == nil {
					return
				}
				for _, clause := range statement.CaseBlock.AsCaseBlock().Clauses.Nodes {
					if clause.Kind != ast.KindCaseClause {
						continue
					}
					if isNaNReference(ctx, clause.AsCaseOrDefaultClause().Expression) {
						ctx.ReportNode(clause, messageCaseWithNaN)
					}
				}
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if !settings.EnforceForIndexOf {
					return
				}
				call := node.AsCallExpression()
				methodName := staticMethodName(ast.SkipParentheses(call.Expression))
				if methodName != "indexOf" && methodName != "lastIndexOf" {
					return
				}
				arguments := call.Arguments.Nodes
				if len(arguments) == 0 || len(arguments) > 2 || !isNaNReference(ctx, arguments[0]) {
					return
				}
				ctx.ReportNode(node, buildIndexOfNaNMessage(methodName))
			},

			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil || !comparisonOperators[binary.OperatorToken.Kind] {
					return
				}
				if isNaNReference(ctx, binary.Left) || isNaNReference(ctx, binary.Right) {
					ctx.ReportNode(node, messageComparisonWithNaN)
				}
			},
		}
	},
}

var messageTypeofNotString = rule.Message{
	Id: "notString",
	Description: "Typeof comparisons should be to string literals. A literal is the one operand the " +
		"rule can check against the eight strings typeof produces, so with requireStringLiterals on, " +
		"anything else, a variable or a template with substitutions, is reported rather than trusted.",
}

var messageSuggestTypeofString = rule.Message{
	Id:          "suggestString",
	Description: "Use `\"undefined\"` instead of `undefined`.",
}

var typeofResults = map[string]bool{
	"undefined": true, "object": true, "boolean": true, "number": true,
	"string": true, "function": true, "symbol": true, "bigint": true,
}

var ValidTypeof = rule.Rule{
	Name: "valid-typeof",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[ValidTypeofOptions](options)

		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil {
					return
				}
				switch binary.OperatorToken.Kind {
				case ast.KindEqualsEqualsToken, ast.KindEqualsEqualsEqualsToken,
					ast.KindExclamationEqualsToken, ast.KindExclamationEqualsEqualsToken:
				default:
					return
				}

				switch {
				case isTypeofExpression(binary.Left):
					reportUnreachableTypeofComparison(ctx, binary.Right, settings)
				case isTypeofExpression(binary.Right):
					reportUnreachableTypeofComparison(ctx, binary.Left, settings)
				}
			},
		}
	},
}

var VarsOnTop = rule.Rule{
	Name: "vars-on-top",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		return rule.Listeners{
			ast.KindVariableDeclarationList: func(declarationList *ast.Node) {

				if declarationList.Flags&(ast.NodeFlagsLet|ast.NodeFlagsConst|ast.NodeFlagsUsing|
					ast.NodeFlagsAwaitUsing) != 0 {
					return
				}

				subject := declarationList
				if declarationList.Parent != nil &&
					declarationList.Parent.Kind == ast.KindVariableStatement {
					subject = declarationList.Parent
				}
				container := subject.Parent
				if container == nil {
					return
				}

				switch container.Kind {
				case ast.KindSourceFile:
					if !varsOnTopIsOnTop(subject, container.AsSourceFile().Statements, false) {
						ctx.ReportNode(subject, messageVarsOnTop)
					}
				case ast.KindBlock:
					grandparent := container.Parent
					if grandparent != nil && ast.IsFunctionLike(grandparent) &&
						varsOnTopIsOnTop(subject, container.AsBlock().Statements, false) {
						return
					}
					if grandparent != nil && grandparent.Kind == ast.KindClassStaticBlockDeclaration &&
						varsOnTopIsOnTop(subject, container.AsBlock().Statements, true) {
						return
					}
					ctx.ReportNode(subject, messageVarsOnTop)
				default:
					ctx.ReportNode(subject, messageVarsOnTop)
				}
			},
		}
	},
}

