var NoTitleInDocumentHead = rule.Rule{

	Name:             "@next/next/no-title-in-document-head",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {

		var watched []*ast.Node

		collect := func(node *ast.Node) {
			declaration := node.AsImportDeclaration()
			if declaration == nil || declaration.ModuleSpecifier == nil {
				return
			}

			if !ast.IsStringLiteralLike(declaration.ModuleSpecifier) {
				return
			}
			if declaration.ModuleSpecifier.Text() != "next/document" {
				return
			}

			named := imports.BindingsOf(node).Named
			if len(named) == 0 {
				return
			}
			watched = append(watched, named[0])
		}

		reportTitleChildren := func(element *ast.Node, headTagName *ast.Node) {

			if element == nil || element.Kind != ast.KindJsxElement {
				return
			}
			children := element.AsJsxElement().Children
			if children == nil {
				return
			}
			for _, child := range children.Nodes {

				var tagName *ast.Node
				switch child.Kind {
				case ast.KindJsxElement:
					tagName, _ = jsx.ElementParts(child.AsJsxElement().OpeningElement)
				case ast.KindJsxSelfClosingElement:
					tagName, _ = jsx.ElementParts(child)
				default:
					continue
				}
				if !jsx.IsIntrinsicElementNamed(tagName, "title") {
					continue
				}

				ctx.ReportNode(headTagName, messageNoTitleInDocumentHead)
			}
		}

		return rule.Listeners{
			ast.KindImportDeclaration: collect,
			ast.KindJsxOpeningElement: func(node *ast.Node) {
				if len(watched) == 0 {
					return
				}

				tagName, _ := jsx.ElementParts(node)

				if tagName == nil || tagName.Kind != ast.KindIdentifier {
					return
				}
				if !resolvesToWatchedSpecifier(ctx, tagName, watched) {
					return
				}
				reportTitleChildren(node.Parent, tagName)
			},
		}
	},
}

var messageNoTypos = rule.Message{
	Id: "noTypos",
	Description: "Next.js calls its data fetching functions by exact name, so a misspelled export " +
		"is never called and the page renders with no data at all. There is no error: the function " +
		"is simply dead code the framework never looks for.",
}

var NoTypos = rule.Rule{

	Name: "@next/next/no-typos",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if !nextjs.IsInPagesDirectory(ctx.SourceFile.FileName().AsString()) {
			return nil
		}

		checkName := func(name *ast.Node) {
			if name == nil || name.Kind != ast.KindIdentifier {
				return
			}
			suggestion, ok := text.BestMatch(name.Text(), dataFetchingFunctions, typoThreshold)
			if !ok {
				return
			}

			message := messageNoTypos
			message.Description = fmt.Sprintf(
				"`%s` may be a typo. Did you mean `%s`? %s",
				name.Text(), suggestion, messageNoTypos.Description,
			)

			ctx.ReportNode(name, message)
		}

		return rule.Listeners{
			ast.KindFunctionDeclaration: func(node *ast.Node) {
				declaration := node.AsFunctionDeclaration()
				if declaration == nil || !module.IsExportedByName(node.Modifiers()) {
					return
				}
				checkName(declaration.Name())
			},
			ast.KindVariableStatement: func(node *ast.Node) {
				statement := node.AsVariableStatement()
				if statement == nil || statement.DeclarationList == nil {
					return
				}
				if !module.IsExportedByName(node.Modifiers()) {
					return
				}

				declarationList := statement.DeclarationList.AsVariableDeclarationList()
				if declarationList == nil || declarationList.Declarations == nil {
					return
				}
				for _, declaration := range declarationList.Declarations.Nodes {

					checkName(declaration.AsVariableDeclaration().Name())
				}
			},
		}
	},
}

var messageNoUnwantedPolyfillioDuplicate = rule.Message{
	Id: "noUnwantedPolyfillioDuplicate",
	Description: "This script asks a polyfill service for features Next.js already ships, so the " +
		"bytes are downloaded and parsed to redefine what is present.",
}

var NoUnwantedPolyfillio = rule.Rule{

	Name: "@next/next/no-unwanted-polyfillio",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		nextScriptLocalName := ""

		recordImport := func(node *ast.Node) {
			if nextScriptLocalName != "" {
				return
			}
			declaration := node.AsImportDeclaration()
			if declaration == nil || declaration.ModuleSpecifier == nil {
				return
			}
			if !ast.IsStringLiteralLike(declaration.ModuleSpecifier) {
				return
			}
			if declaration.ModuleSpecifier.Text() != "next/script" {
				return
			}

			bindings := imports.BindingsOf(node)
			candidates := append([]*ast.Node{bindings.Default, bindings.Namespace}, bindings.Named...)
			for _, binding := range candidates {
				name := localBindingName(binding)
				if name != "" {
					nextScriptLocalName = name
					return
				}
			}
		}

		report := func(node *ast.Node) {
			tagName, attributes := jsx.ElementParts(node)
			if !jsx.IsIntrinsicElementNamed(tagName, "script") {

				if nextScriptLocalName == "" {
					return
				}
				if tagName == nil || tagName.Kind != ast.KindIdentifier || tagName.Text() != nextScriptLocalName {
					return
				}
			}

			source, sourceNode := stringAttributeWithNode(attributes, "src")
			if sourceNode == nil {
				return
			}

			if strings.HasPrefix(source, "https://cdn.polyfill.io/v2/") || strings.HasPrefix(source, "https://polyfill.io/v3/") {
				ctx.ReportNode(sourceNode, messageNoUnwantedPolyfillioSecurity)
				return
			}

			if !strings.HasPrefix(source, "https://polyfill-fastly.net/") &&
				!strings.HasPrefix(source, "https://polyfill-fastly.io/") &&
				!strings.HasPrefix(source, "https://cdnjs.cloudflare.com/polyfill/") {
				return
			}

			features, hasFeatures := urlQueryValue(source, "features")
			if !hasFeatures {
				return
			}

			features = strings.ReplaceAll(features, "%2C", ",")

			var unwanted []string
			for _, feature := range strings.Split(features, ",") {
				if _, shipped := nextPolyfilledFeatures[feature]; shipped {
					unwanted = append(unwanted, feature)
				}
			}
			if len(unwanted) == 0 {
				return
			}

			verb := "is"
			if len(unwanted) > 1 {
				verb = "are"
			}
			message := messageNoUnwantedPolyfillioDuplicate
			named := strings.Join(unwanted, ", ")
			message.Description = fmt.Sprintf(
				"This script asks a polyfill service for %s, which Next.js already ships, so the "+
					"bytes are downloaded and parsed to redefine what %s already there. Drop %s "+
					"from the `features` list.",
				named, verb, named,
			)
			ctx.ReportNode(sourceNode, message)
		}

		return rule.Listeners{
			ast.KindImportDeclaration:     recordImport,
			ast.KindJsxOpeningElement:     report,
			ast.KindJsxSelfClosingElement: report,
		}
	},
}

