var ConsistencyNoMultilineArrowFunction = rule.Rule{
	Name: "nexus/consistency-no-multiline-arrow-function",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}
		sourceFile := ctx.SourceFile

		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()
				if call == nil || call.Expression == nil || call.Arguments == nil {
					return
				}
				if call.Expression.Kind != ast.KindPropertyAccessExpression {
					return
				}
				access := call.Expression.AsPropertyAccessExpression()
				if access == nil || access.Expression == nil || access.Name() == nil {
					return
				}
				objectName := ""
				if access.Expression.Kind == ast.KindIdentifier {
					objectName = access.Expression.Text()
				}
				propertyName := access.Name().Text()

				arguments := call.Arguments.Nodes

				if isReactHookCallee(objectName, propertyName) && len(arguments) > 0 &&
					arguments[0].Kind == ast.KindArrowFunction {
					reportArrow(ctx, arguments[0], messageReactHookArrow(propertyName))
					return
				}
				if propertyName == "addEventListener" && len(arguments) > 1 &&
					arguments[1].Kind == ast.KindArrowFunction {
					reportArrow(ctx, arguments[1], messageAddEventListenerArrow())
				}
			},

			ast.KindArrowFunction: func(node *ast.Node) {
				arrow := node.AsArrowFunction()
				if arrow == nil || arrow.Body == nil {
					return
				}

				if usesThis(arrow.Body) {
					return
				}

				if arrow.Body.Kind != ast.KindBlock {
					return
				}

				if spansOneLine(sourceFile, node) {
					return
				}

				if isClaimedByCallExpressionCase(node) {
					return
				}

				reportArrow(ctx, node, messageMultilineArrow())
			},
		}
	},
}

var ConsistencyNoPropertyAlias = rule.Rule{
	Name: "nexus/consistency-no-property-alias",

	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()

				name := declaration.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}
				localName := name.Text()

				initializer := declaration.Initializer
				if initializer == nil || initializer.Kind != ast.KindPropertyAccessExpression {
					return
				}
				access := initializer.AsPropertyAccessExpression()

				if chainContainsOptional(initializer) {
					return
				}

				property := access.Name()
				if property == nil || property.Kind != ast.KindIdentifier {
					return
				}
				if property.Text() != localName {
					return
				}

				if chainContainsCall(access.Expression) {
					return
				}

				enclosing := scope.EnclosingFunctionLike(node)
				if enclosing == nil {
					return
				}

				if isReadInsideHookDependencyArray(enclosing, localName, name) {
					return
				}

				if isWrittenAfterItsDeclaration(enclosing, localName, name) {
					return
				}

				if isSnapshotTakenBeforeItsSourceIsWritten(enclosing, node, localName, name, initializer) {
					return
				}

				if chainContainsTypeAssertion(access.Expression) {
					return
				}

				if ctx.TypeChecker != nil {
					if chainReadsAGetter(ctx, initializer) {
						return
					}
					if isReadInsideANestedFunction(enclosing, localName, name) && chainIsNarrowed(ctx, initializer) {
						return
					}
					if isNarrowedWhereAClosureReadsIt(ctx, enclosing, localName, name) {
						return
					}
					if declaration.Type != nil &&
						ctx.TypeChecker.GetTypeFromTypeNode(declaration.Type) != ctx.TypeChecker.GetTypeAtLocation(initializer) {
						return
					}
				}

				sourceText := rule.TokenRange(ctx.SourceFile, access.Expression)
				objectText := ctx.SourceFile.Text()[sourceText.Pos():sourceText.End()]

				ctx.ReportNode(node, rule.Message{
					Id:          consistencyNoPropertyAliasText.Id,
					Description: consistencyNoPropertyAliasText.Render(map[string]string{"name": localName, "object": objectText}),
				})
			},
		}
	},
}

var ConsistencyNoReturnVoid = rule.Rule{
	Name: "nexus/consistency-no-return-void",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindReturnStatement: func(node *ast.Node) {
				expression := node.AsReturnStatement().Expression
				if expression == nil {
					return
				}
				voidExpression := ast.SkipParentheses(expression)
				if voidExpression.Kind != ast.KindVoidExpression {
					return
				}

				replacement, fixable := consistencyNoReturnVoidReplacement(ctx, node, voidExpression)
				if !fixable {
					ctx.ReportNode(node, consistencyNoReturnVoidMessage())
					return
				}
				ctx.ReportNodeWithFixes(node, consistencyNoReturnVoidMessage(), ctx.ReplaceNode(node, replacement))
			},
		}
	},
}

