var ConsistencyNoScreamingSnakeCase = rule.Rule{
	Name: "nexus/consistency-no-screaming-snake-case",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		allowed := map[string]bool{}
		if settings, hasSettings := rule.OptionsAs[ConsistencyNoScreamingSnakeCaseOptions](options); hasSettings {
			for _, name := range settings.Allow {
				allowed[name] = true
			}
		}

		return rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()
				if declaration == nil {
					return
				}
				name := declaration.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}
				if !isScreamingSnakeCase(name.Text()) || allowed[name.Text()] {
					return
				}
				if isProcessEnvironmentAccess(declaration.Initializer) {
					return
				}

				declarationList := node.Parent
				if declarationList == nil || declarationList.Flags&ast.NodeFlagsConst == 0 {
					return
				}

				if module.IsExported(declarationList.Parent) {
					ctx.ReportNode(name, messageScreamingSnakeCaseExported(name.Text(), toPascalCase(name.Text())))
					return
				}
				ctx.ReportNode(name, messageScreamingSnakeCaseLocal(name.Text(), toCamelCase(name.Text())))
			},
		}
	},
}

var ConsistencyNoShouting = rule.Rule{
	Name: "nexus/consistency-no-shouting",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		additionalAllowed := map[string]bool{}
		if settings, hasSettings := rule.OptionsAs[ConsistencyNoShoutingOptions](options); hasSettings {
			for _, token := range settings.Allow {
				additionalAllowed[token] = true
			}
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				for _, comment := range comments.ForFile(ctx) {
					tokens := shoutedTokensIn(comment.Text)

					kept := tokens[:0]
					for _, token := range tokens {
						if !additionalAllowed[token] {
							kept = append(kept, token)
						}
					}
					if len(kept) == 0 {
						continue
					}

					ctx.ReportRange(comment.Range, messageShoutingInComment(kept))
				}
			},
		}
	},
}

var ConsistencyNoSingleLineJsDoc = rule.Rule{
	Name: "nexus/consistency-no-single-line-jsdoc",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				for _, comment := range comments.ForFile(ctx) {
					if !comment.IsJsDoc() {
						continue
					}

					lines := comment.ContentLines()

					if len(lines) != 1 || strings.HasPrefix(lines[0], "@") {
						continue
					}

					description := lines[0]
					isSingleSourceLine := comment.StartLine == comment.EndLine
					if strings.Contains(description, "//") || !isSingleSourceLine ||
						consistencyNoSingleLineJsDocCodeFollows(ctx.SourceFile.Text(), comment.Range.End()) {
						ctx.ReportRange(comment.Range, messageUseSimpleComment())
						continue
					}

					ctx.Report(rule.Diagnostic{
						Range:      comment.Range,
						Message:    messageUseSimpleComment(),
						SourceFile: ctx.SourceFile,
						Fixes: []rule.Fix{
							rule.ReplaceRange(comment.Range, "// "+description),
						},
					})
				}
			},
		}
	},
}

