				ctx.ReportNode(name, messageNoTypeAliasSuffix(name.Text()))
			},

			ast.KindInterfaceDeclaration: func(node *ast.Node) {
				name := node.AsInterfaceDeclaration().Name()
				if name == nil || hasAnySuffix(name.Text(), interfaceSuffixes) {
					return
