var DefaultPropsMatchPropTypes = rule.Rule{
	Name: "react/default-props-match-prop-types",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		settings := DefaultDefaultPropsMatchPropTypesOptions()
		if configured, isConfigured := rule.OptionsAs[DefaultPropsMatchPropTypesOptions](options); isConfigured {
			settings = configured
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				checkDefaultPropsAgainstPropTypes(ctx, node, settings)
			},
		}
	},
}

var messageNoDisplayName = rule.Message{
	Id:          "noDisplayName",
	Description: "Component definition is missing display name",
}

var messageNoContextDisplayName = rule.Message{
	Id:          "noContextDisplayName",
	Description: "Context definition is missing display name",
}

var DisplayName = rule.Rule{
	Name: "react/display-name",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		settings := DefaultDisplayNameOptions()
		if configured, isConfigured := rule.OptionsAs[DisplayNameOptions](options); isConfigured {
			settings = configured
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}
				reportMissingDisplayNames(ctx, node, settings)
			},
		}
	},
}

var ErrorBoundaries = rule.Rule{

	Name: "react-hooks/error-boundaries",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		report := func(node *ast.Node) {
			enclosing := enclosingFunctionOf(node)
			if enclosing == nil || !isInsideTryBlockWithin(node, enclosing) {
				return
			}
			if !isReactCompiledFunction(enclosing) {
				return
			}
			ctx.ReportNode(node, messageJsxInTryStatement)
		}

		return rule.Listeners{
			ast.KindJsxElement:            report,
			ast.KindJsxSelfClosingElement: report,
			ast.KindJsxFragment:           report,
		}
	},
}

var (
	messageExhaustiveDepsMissing = rule.Message{
