var ForbidDomProps = rule.Rule{
	Name: "react/forbid-dom-props",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[ForbidDomPropsOptions](options)

		forbidden := make(map[string]ForbidDomPropsEntry, len(settings.Forbid))
		for _, entry := range settings.Forbid {
			forbidden[entry.PropName] = entry
		}

		return rule.Listeners{
			ast.KindJsxAttribute: func(node *ast.Node) {

				attributeName, named := jsx.AttributeName(node)
				if !named {
					return
				}

				attributes := node.Parent
				if attributes == nil || attributes.Kind != ast.KindJsxAttributes {
					return
				}
				tagName, _ := jsx.ElementParts(attributes.Parent)

				if tagName == nil || tagName.Kind != ast.KindIdentifier {
					return
				}
				tag := tagName.Text()
				if !forbidDomPropsIsDomNodeName(tag) {
					return
				}

				entry, listed := forbidden[attributeName]
				if !listed || !forbidDomPropsIsForbidden(entry, tag) {
					return
				}

				ctx.ReportNode(node, forbidDomPropsMessage(attributeName, entry.Message))
			},
		}
	},
}

var ForbidElements = rule.Rule{
	Name: "react/forbid-elements",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[ForbidElementsOptions](options)

		forbidden := make(map[string]ForbidElementsEntry, len(settings.Forbid))
		for _, entry := range settings.Forbid {
			forbidden[entry.Element] = entry
		}

		sourceTextOf := func(node *ast.Node) string {
			span := rule.TokenRange(ctx.SourceFile, node)
			text := ctx.SourceFile.Text()
			if span.Pos() < 0 || span.End() > len(text) || span.Pos() > span.End() {
				return ""
			}
			return text[span.Pos():span.End()]
		}

		reportIfForbidden := func(element string, node *ast.Node) {
			entry, found := forbidden[element]
			if !found {
				return
			}
			ctx.ReportNode(node, forbidElementsMessage(element, entry.Message))
		}

		checkJsxElement := func(node *ast.Node) {

			tagName, _ := jsx.ElementParts(node)
			if tagName == nil {
				return
			}
			reportIfForbidden(sourceTextOf(tagName), tagName)
		}

		return rule.Listeners{
			ast.KindJsxOpeningElement: checkJsxElement,

			ast.KindJsxSelfClosingElement: checkJsxElement,

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if !isPragmaCreateElementCall(ctx, node) {
					return
				}
				arguments := node.AsCallExpression().Arguments
				if arguments == nil || len(arguments.Nodes) == 0 {
					return
				}
				argument := arguments.Nodes[0]

				switch {
				case argument.Kind == ast.KindIdentifier:

					name := argument.Text()
					if forbidElementsStartsUpperOrUnderscore(name) {
						reportIfForbidden(name, argument)
					}

				case forbidElementsIsUpstreamLiteral(argument):

					value := forbidElementsLiteralText(argument)
					if forbidElementsIsLowercaseUndotted(value) {
						reportIfForbidden(value, argument)
					}

				case argument.Kind == ast.KindPropertyAccessExpression ||
					argument.Kind == ast.KindElementAccessExpression:

					reportIfForbidden(sourceTextOf(argument), argument)
				}
			},
		}
	},
}

var ForbidForeignPropTypes = rule.Rule{
	Name: "react/forbid-foreign-prop-types",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[ForbidForeignPropTypesOptions](options)

		unwrapParentheses := func(node *ast.Node) *ast.Node {
			for node != nil && node.Kind == ast.KindParenthesizedExpression {
				node = node.Parent
			}
			return node
		}

		isAssignmentTarget := func(node *ast.Node) bool {
			parent := unwrapParentheses(node.Parent)
			if parent == nil || !ast.IsAssignmentExpression(parent, false) {
				return false
			}

			left := parent.AsBinaryExpression().Left
			for left != nil && left.Kind == ast.KindParenthesizedExpression {
				left = left.AsParenthesizedExpression().Expression
			}
			return left == node
		}

		isAllowedAssignment := func(node *ast.Node) bool {
			if !settings.AllowInPropTypes {
				return false
			}

			for parent := node.Parent; parent != nil && parent.Kind != ast.KindSourceFile; parent = parent.Parent {
				if !ast.IsAssignmentExpression(parent, false) {
					continue
				}
				left := parent.AsBinaryExpression().Left
				for left != nil && left.Kind == ast.KindParenthesizedExpression {
					left = left.AsParenthesizedExpression().Expression
				}
				if left == nil || left.Kind != ast.KindPropertyAccessExpression {
					continue
				}
				property := left.AsPropertyAccessExpression().Name()
				if property != nil && property.Kind == ast.KindIdentifier && property.Text() == "propTypes" {
					return true
				}
			}

			for parent := node.Parent; parent != nil && parent.Kind != ast.KindSourceFile; parent = parent.Parent {
				if parent.Kind != ast.KindPropertyDeclaration {
					continue
				}
				key := parent.Name()
				if key != nil && key.Kind == ast.KindIdentifier && key.Text() == "propTypes" {
					return true
				}
			}

			return false
		}

		reportProperty := func(access *ast.Node, property *ast.Node) {
			if isAssignmentTarget(access) || isAllowedAssignment(access) {
				return
			}
			ctx.ReportNode(property, messageForbidForeignPropTypes)
		}

		return rule.Listeners{
			ast.KindPropertyAccessExpression: func(node *ast.Node) {

				property := node.AsPropertyAccessExpression().Name()
				if property == nil || property.Kind != ast.KindIdentifier || property.Text() != "propTypes" {
					return
				}
				reportProperty(node, property)
			},

			ast.KindElementAccessExpression: func(node *ast.Node) {

				argument := node.AsElementAccessExpression().ArgumentExpression
				if argument == nil || argument.Kind != ast.KindStringLiteral || argument.Text() != "propTypes" {
					return
				}
				reportProperty(node, argument)
			},

			ast.KindObjectBindingPattern: func(node *ast.Node) {
				elements := node.AsBindingPattern().Elements
				if elements == nil {
					return
				}

				for _, element := range elements.Nodes {
					if element.Kind != ast.KindBindingElement {
						continue
					}

					key := bindingElementPropertyKey(element)
					if key == nil || key.Kind != ast.KindIdentifier || key.Text() != "propTypes" {
						continue
					}

					ctx.ReportNode(element, messageForbidForeignPropTypes)
					return
				}
			},
		}
	},
}

var ForbidPropTypes = rule.Rule{
