var messageForwardRefAddRefParameter = rule.Message{
	Id:          "forwardRefAddRefParameter",
	Description: "Add a `ref` parameter.",
}

var messageForwardRefRemoveWrapper = rule.Message{
	Id:          "forwardRefRemoveWrapper",
	Description: "Remove the `forwardRef` wrapper.",
}

var ForwardRefUsesRef = rule.Rule{
	Name: "react/forward-ref-uses-ref",
	Run: func(ctx rule.Context, _ any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()

				if calleeName(call.Expression) != "forwardRef" {
					return
				}
				if call.Arguments == nil || len(call.Arguments.Nodes) == 0 {
					return
				}

				first := call.Arguments.Nodes[0]

				var parameters []*ast.Node
				switch first.Kind {
				case ast.KindArrowFunction:
					parameters = parameterNodesOf(first.AsArrowFunction().Parameters)
				case ast.KindFunctionExpression:
					parameters = parameterNodesOf(first.AsFunctionExpression().Parameters)
				default:
					return
				}

				if !hasExactlyOneCountedParameter(parameters) {
					return
				}

				ctx.ReportNodeWithSuggestions(first, messageForwardRefUsesRef,
					suggestionsFor(ctx, node, first, parameters)...)
			},
		}
	},
}

var Gating = rule.Rule{

	Name: "react-hooks/gating",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		gatingOptions, _ := rule.OptionsAs[GatingOptions](options)
		if gatingOptions.RequireDynamicGatingOption {
			return nil
		}

		check := func(statements []*ast.Node) {
			var matched []*ast.Node
			invalid := false

			for _, statement := range leadingDirectives(statements) {
				condition, isGating := parseGatingDirective(directiveText(statement))
				if !isGating {
					continue
				}
				if !isValidGatingCondition(condition) {

					ctx.ReportNode(statement, messageInvalidGatingDirective)
					invalid = true
					continue
				}
				matched = append(matched, statement)
			}

			if invalid || len(matched) < 2 {
				return
			}

			ctx.ReportNode(matched[0], messageMultipleGatingDirectives)
		}

		return rule.Listeners{
			ast.KindBlock: func(node *ast.Node) {
				check(node.AsBlock().Statements.Nodes)
			},
			ast.KindSourceFile: func(node *ast.Node) {
				check(node.AsSourceFile().Statements.Nodes)
			},
		}
	},
}

var Globals = rule.Rule{

	Name: "react-hooks/globals",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindIdentifier: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}

				if !reference.WritesToBinding(node) {
					return
				}

				if !isGlobalStoreTarget(node) {
					return
				}

				root := enclosingCompilationRoot(node)
				if root == nil {
					return
				}

				if crossesNestedFunctionBoundary(node, root) {
					return
				}
				if isInsideCatchOrFinally(node, root) {
					return
				}
				if followsAnAbruptCompletion(node, root) {
					return
				}

				if !declaredOutsideCompilationRoot(ctx, node, root) {
					return
				}

				ctx.ReportNode(globalStoreReportNode(node), rule.Message{
					Id: messageGlobalReassignmentId,
					Description: fmt.Sprintf(
						"This writes to `%s`, which is declared outside the component or hook, "+
							"while the component is rendering. %s",
						node.Text(), messageGlobalReassignmentReason),
				})
			},
		}
	},
}

var IframeMissingSandbox = rule.Rule{
	Name: "react/iframe-missing-sandbox",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		validateSandboxValue := func(reported *ast.Node, value string, reportsPair func() bool) {
			allowScripts := false
			allowSameOrigin := false

			for _, token := range strings.Split(value, " ") {
				token = text.TrimWhitespace(token)
				if !iframeMissingSandboxAllowedValues[token] {
					ctx.ReportNode(reported, iframeMissingSandboxInvalidValue(token))
				}
				if token == "allow-scripts" {
					allowScripts = true
				}
				if token == "allow-same-origin" {
					allowSameOrigin = true
				}
			}
			if allowScripts && allowSameOrigin && reportsPair() {
				ctx.ReportNode(reported, messageIframeMissingSandboxInvalidCombination)
			}
		}

		checkJsxElement := func(node *ast.Node) {
			tagName, attributes := jsx.ElementParts(node)
			if !jsx.IsIntrinsicElementNamed(tagName, "iframe") {
				return
			}

			sandboxFound := false
			if attributes != nil && attributes.Kind == ast.KindJsxAttributes {
				properties := attributes.AsJsxAttributes().Properties
				if properties != nil {
					reportsPair := func() bool {
						var frame iframeMissingSandboxFrame
						for _, property := range properties.Nodes {
							attributeName, named := jsx.AttributeName(property)
							if !named {

								frame.opaque()
								continue
							}
							switch attributeName {
							case "src":
								frame.source(iframeMissingSandboxJsxValue(property.AsJsxAttribute().Initializer))
							case "srcDoc", "srcdoc":
								frame.sourceDocument = true
							}
						}
						return !frame.provablyCrossOrigin(ctx)
					}
					for _, property := range properties.Nodes {
						attributeName, named := jsx.AttributeName(property)
						if !named || !jsx.MatchExactly(attributeName, "sandbox") {
							continue
						}
						sandboxFound = true

						initializer := property.AsJsxAttribute().Initializer
						if initializer != nil && initializer.Kind == ast.KindStringLiteral {
							validateSandboxValue(node, initializer.Text(), reportsPair)
						}
					}
				}
			}

			if !sandboxFound {
				ctx.ReportNode(node, messageIframeMissingSandboxAttributeMissing)
			}
		}

		return rule.Listeners{
			ast.KindJsxOpeningElement: checkJsxElement,

			ast.KindJsxSelfClosingElement: checkJsxElement,

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if !isPragmaCreateElementCall(ctx, node) {
					return
				}
				arguments := node.AsCallExpression().Arguments
				if arguments == nil || len(arguments.Nodes) == 0 {
					return
				}

				first := arguments.Nodes[0]
				if first.Kind != ast.KindStringLiteral || first.Text() != "iframe" {
					return
				}

				sandboxFound := false

				if len(arguments.Nodes) > 1 && arguments.Nodes[1].Kind == ast.KindObjectLiteralExpression {
					properties := arguments.Nodes[1].AsObjectLiteralExpression().Properties
					if properties != nil {
						reportsPair := func() bool {
							var frame iframeMissingSandboxFrame
							for _, property := range properties.Nodes {

								name := propertyIdentifierName(property)
								if keyNode := property.Name(); name == "" && keyNode != nil && keyNode.Kind == ast.KindStringLiteral {
									name = keyNode.Text()
								}
								switch {
								case name == "src" && property.Kind == ast.KindPropertyAssignment:
									frame.source(property.AsPropertyAssignment().Initializer)
								case name == "src" && property.Kind == ast.KindShorthandPropertyAssignment:

									frame.source(property)
								case name == "srcDoc" || name == "srcdoc":
									frame.sourceDocument = true
								default:

									if name == "" || name == "src" {
										frame.opaque()
									}
								}
							}
							return !frame.provablyCrossOrigin(ctx)
						}
						for _, property := range properties.Nodes {

							if propertyIdentifierName(property) != "sandbox" {
								continue
							}
							sandboxFound = true

							if property.Kind == ast.KindPropertyAssignment {
								initializer := property.AsPropertyAssignment().Initializer
								if initializer != nil && initializer.Kind == ast.KindStringLiteral {
									validateSandboxValue(node, initializer.Text(), reportsPair)
								}
							}
						}
					}
				}

				if !sandboxFound {
					ctx.ReportNode(node, messageIframeMissingSandboxAttributeMissing)
				}
			},
		}
	},
}

var Immutability = rule.Rule{
	Name:             "react-hooks/immutability",
	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{

			ast.KindSourceFile: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if !high_level_intermediate_representation.MayHoldComponentOrHook(ctx) {
					return
				}
				immutabilityForEachCompiledFunction(node, func(functionNode *ast.Node) {
					lowered := high_level_intermediate_representation.ForFunction(ctx, functionNode)
					if lowered == nil {
						return
					}
					immutabilityAnalyzeCompilationUnit(ctx, lowered, functionNode)
				})
			},
		}
	},
}

var IncompatibleLibrary = rule.Rule{

	Name: "react-hooks/incompatible-library",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {

				incompatible := incompatibleLibraryBindings(node)
				if len(incompatible.direct) == 0 && len(incompatible.indirect) == 0 {
					return
				}
				incompatibleLibraryReport(ctx, node, incompatible)
			},
		}
	},
}

