var JsxCurlyBracePresence = rule.Rule{
	Name: "react/jsx-curly-brace-presence",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[JsxCurlyBracePresenceOptions](options)
		if !ok {
			settings = DefaultJsxCurlyBracePresenceOptions()
		}

		return rule.Listeners{
			ast.KindJsxExpression: func(node *ast.Node) {

				if jsxCurlyBracePresenceIsElementValuedProp(node) {
					if settings.PropElementValues == jsxCurlyBracePresenceNever {
						jsxCurlyBracePresenceReportUnnecessary(ctx, node)
					}
					return
				}
				if jsxCurlyBracePresenceShouldCheckUnnecessary(ctx, node, settings) {
					jsxCurlyBracePresenceLintUnnecessary(ctx, node, settings)
				}
			},

			ast.KindJsxText: func(node *ast.Node) {
				if jsxCurlyBracePresenceShouldCheckMissing(node, settings) {
					jsxCurlyBracePresenceReportMissing(ctx, node)
				}
			},

			ast.KindStringLiteral: func(node *ast.Node) {
				if node.Parent == nil || node.Parent.Kind != ast.KindJsxAttribute {
					return
				}
				if jsxCurlyBracePresenceShouldCheckMissing(node, settings) {
					jsxCurlyBracePresenceReportMissing(ctx, node)
				}
			},

			ast.KindJsxSelfClosingElement: func(node *ast.Node) {
				jsxCurlyBracePresenceCheckBareElementAttribute(ctx, node, settings)
			},
			ast.KindJsxElement: func(node *ast.Node) {
				jsxCurlyBracePresenceCheckBareElementAttribute(ctx, node, settings)
			},
		}
	},
}

var messagePreferFragmentShorthand = rule.Message{
	Id: "preferFragment",
	Description: "Prefer fragment shorthand over React.Fragment. The shorthand `<>` says the same " +
		"thing with less to read, and a named fragment that carries no props is only the long " +
		"spelling of it.",
}

var messagePreferFragmentPragma = rule.Message{
	Id: "preferPragma",
	Description: "Prefer React.Fragment over fragment shorthand. The named form is the one this " +
		"file is configured to use, and it is the only spelling that can carry a `key`.",
}

var JsxFragments = rule.Rule{
	Name:             "react/jsx-fragments",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		settings := DefaultJsxFragmentsOptions()
		if configured, isConfigured := rule.OptionsAs[JsxFragmentsOptions](options); isConfigured {
			settings = configured
		}

		judgeNamed := func(node *ast.Node, tagName *ast.Node, attributes *ast.Node) {
			if settings.Mode != JsxFragmentsSyntax {
				return
			}
			if ctx.TypeChecker == nil {
				return
			}
			if !jsxFragmentsNameIsFragment(ctx, tagName) {
				return
			}

			if jsxFragmentsHasAttributes(attributes) {
				return
			}
			ctx.ReportNode(node, messagePreferFragmentShorthand)
		}

		return rule.Listeners{
			ast.KindJsxFragment: func(node *ast.Node) {
				if settings.Mode != JsxFragmentsElement {
					return
				}
				ctx.ReportNode(node, messagePreferFragmentPragma)
			},

			ast.KindJsxElement: func(node *ast.Node) {
				opening := node.AsJsxElement().OpeningElement
				if opening == nil {
					return
				}

				tagName, attributes := jsx.ElementParts(opening)
				judgeNamed(node, tagName, attributes)
			},

			ast.KindJsxSelfClosingElement: func(node *ast.Node) {
				tagName, attributes := jsx.ElementParts(node)
				judgeNamed(node, tagName, attributes)
			},
		}
	},
}

var (
	messageJsxKeyMissingIterKey = rule.Message{
		Id: "missingIterKey",
		Description: "This element is produced by an iterator and carries no `key`. React reconciles a " +
			"list by position when it has no key, so inserting or reordering an item makes every " +
			"element after it adopt the previous one's state: focus jumps, inputs keep the wrong " +
			"text, and animations restart on rows that did not change. Give each element a `key` " +
			"that identifies the item rather than its position.",
	}
	messageJsxKeyMissingIterKeyUsePragma = rule.Message{
		Id: "missingIterKeyUsePrag",
		Description: "This element is produced by an iterator and is written as a shorthand fragment, " +
			"which has no syntax for a `key`. React reconciles the list by position instead, so " +
			"inserting or reordering an item makes the elements after it adopt the wrong state. " +
			"Write `React.Fragment` in full, which does accept a `key`.",
	}
	messageJsxKeyMissingArrayKey = rule.Message{
		Id: "missingArrayKey",
		Description: "This element sits in an array literal and carries no `key`. React reconciles " +
			"the array by position when it has no key, so changing the order or the length makes " +
			"the surviving elements adopt their neighbours' state. Give each element a `key` that " +
			"identifies it rather than its position.",
	}
	messageJsxKeyMissingArrayKeyUsePragma = rule.Message{
		Id: "missingArrayKeyUsePrag",
		Description: "This element sits in an array literal and is written as a shorthand fragment, " +
			"which has no syntax for a `key`. React reconciles the array by position instead. " +
			"Write `React.Fragment` in full, which does accept a `key`.",
	}
	messageJsxKeyBeforeSpread = rule.Message{
		Id: "keyBeforeSpread",
		Description: "The `key` prop is written after a `{...spread}`. Under the new JSX transform " +
			"`key` is read out of the props object rather than passed separately, so a spread that " +
			"also carries a `key` silently wins over the one written here and the element is " +
			"reconciled by the wrong identity. Move `key` before every spread.",
	}
	messageJsxKeyNonUniqueKeys = rule.Message{
		Id: "nonUniqueKeys",
		Description: "Two elements in this collection carry the same `key`. React uses the key as " +
