var JsxKey = rule.Rule{

	Name: "react/jsx-key",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[JsxKeyOptions](options)
		pragma := reactPragmaFor(ctx)

		reportCollection := func(node *ast.Node, elements []*ast.Node, isArrayLiteral bool) {
			if isWithinChildrenToArray(node, pragma) {
				return
			}
			jsxElements := jsxElementsAmong(elements)
			if len(jsxElements) == 0 {
				return
			}

			byKeyText := map[string][]*ast.Node{}

			keyOrder := []string{}

			for _, element := range jsxElements {
				attributes := attributesOfJsxElement(element)
				keyAttributes := exactlyNamedAttributes(attributes, "key")

				if len(keyAttributes) == 0 {

					if isArrayLiteral {
						ctx.ReportNode(element, messageJsxKeyMissingArrayKey)
					}
					continue
				}

				for _, keyAttribute := range keyAttributes {
					text := keyAttributeValueText(ctx, keyAttribute)
					if _, seen := byKeyText[text]; !seen {
						keyOrder = append(keyOrder, text)
					}
					byKeyText[text] = append(byKeyText[text], keyAttribute)

					if settings.CheckKeyMustBeforeSpread && isKeyAfterSpread(attributes) {
						ctx.ReportNode(node, messageJsxKeyBeforeSpread)
					}
				}
			}

			if !settings.WarnOnDuplicates {
				return
			}
			for _, text := range keyOrder {
				group := byKeyText[text]
				if len(group) < 2 {
					continue
				}
				for _, keyAttribute := range group {

					ctx.ReportNode(keyAttribute, messageJsxKeyNonUniqueKeys)
				}
			}
		}

		checkIteratorElement := func(node *ast.Node) {

			node = skipParenthesesSafely(node)
			if node == nil {
				return
			}
			if isJsxElementNode(node) {
				attributes := attributesOfJsxElement(node)

				if !hasKeyAttributeIgnoringCase(attributes) {
					ctx.ReportNode(node, messageJsxKeyMissingIterKey)
					return
				}
				if settings.CheckKeyMustBeforeSpread && isKeyAfterSpread(attributes) {

					ctx.ReportNode(node, messageJsxKeyBeforeSpread)
				}
				return
			}
			if settings.CheckFragmentShorthand && node.Kind == ast.KindJsxFragment {
				ctx.ReportNode(node, messageJsxKeyMissingIterKeyUsePragma)
			}
		}

		checkIteratorCallback := func(callback *ast.Node) {

			callback = skipParenthesesSafely(callback)
			if !isFunctionLikeExpressionForJsxKey(callback) {
				return
			}
			checkArrowFunctionWithJsx(callback, checkIteratorElement)
			checkFunctionsBlockStatement(callback, checkIteratorElement)
		}

		return rule.Listeners{
			ast.KindArrayLiteralExpression: func(node *ast.Node) {
				elements := node.AsArrayLiteralExpression().Elements
				if elements == nil {
					return
				}
				reportCollection(node, elements.Nodes, true)
			},

			ast.KindJsxElement: func(node *ast.Node) {
				children := node.AsJsxElement().Children
				if children == nil {
					return
				}
				reportCollection(node, children.Nodes, false)
			},

			ast.KindJsxFragment: func(node *ast.Node) {
				if !settings.CheckFragmentShorthand || isWithinChildrenToArray(node, pragma) {
					return
				}
				if node.Parent == nil || node.Parent.Kind != ast.KindArrayLiteralExpression {
					return
				}
				ctx.ReportNode(node, messageJsxKeyMissingArrayKeyUsePragma)
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if isWithinChildrenToArray(node, pragma) {
					return
				}
				call := node.AsCallExpression()
				callee := skipParenthesesSafely(call.Expression)
				if callee == nil {
					return
				}
				name, named := calleePropertyName(callee)
				if !named {
					return
				}
				arguments := []*ast.Node{}
				if call.Arguments != nil {
					arguments = call.Arguments.Nodes
				}

				switch name {
				case "map":

					if len(arguments) == 0 {
						return
					}
					checkIteratorCallback(arguments[0])
				case "from":

					if len(arguments) < 2 {
						return
					}
					checkIteratorCallback(arguments[1])
				}
			},
		}
	},
}

var JsxNoCommentTextnodes = rule.Rule{

	Name: "react/jsx-no-comment-textnodes",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		sourceText := ctx.SourceFile.Text()

		return rule.Listeners{
			ast.KindJsxText: func(node *ast.Node) {

				raw := sourceText[node.Pos():node.End()]
				if !jsxNoCommentTextnodesLooksLikeAComment(raw) {
					return
				}

				ctx.ReportRange(core.NewTextRange(node.Pos(), node.End()), messageJsxNoCommentTextnodes)
			},
		}
	},
}

var JsxNoConstructedContextValues = rule.Rule{
	Name:             "react/jsx-no-constructed-context-values",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.TypeChecker == nil {
			return nil
		}

		check := func(node *ast.Node, tagName *ast.Node, attributes *ast.Node) {
			if ctx.TypeChecker == nil {
				return
			}
			if !jsxNoConstructedContextValuesIsProvider(ctx, tagName) {
				return
			}

			value := jsxNoConstructedContextValuesValueExpression(attributes)
			if value == nil {
				return
			}

			construction := jsxNoConstructedContextValuesConstructionOf(ctx, value, 0)
			if construction == nil {

				if jsxNoConstructedContextValuesInComponent(node) {
					jsxNoConstructedContextValuesCheckMemo(ctx, value, node)
				}
				return
			}

			if !jsxNoConstructedContextValuesInComponent(node) {
				return
			}

			nodeLine, _ := scanner.GetLineAndCharacterOfPosition(ctx.SourceFile,
				rule.TokenRange(ctx.SourceFile, construction.node).Pos())
			usageLine, variableName := 0, ""
			if construction.usage != nil {
				usageLine, _ = scanner.GetLineAndCharacterOfPosition(ctx.SourceFile,
					rule.TokenRange(ctx.SourceFile, construction.usage).Pos())
				usageLine++
				if construction.usage.Kind == ast.KindIdentifier {
					variableName = construction.usage.Text()
				}
			}

			ctx.ReportNode(construction.node, jsxNoConstructedContextValuesMessage(
				*construction, nodeLine+1, usageLine, variableName,
			))
		}

		return rule.Listeners{
			ast.KindJsxOpeningElement: func(node *ast.Node) {
				opening := node.AsJsxOpeningElement()
				check(node, opening.TagName, opening.Attributes)
			},
			ast.KindJsxSelfClosingElement: func(node *ast.Node) {
				element := node.AsJsxSelfClosingElement()
				check(node, element.TagName, element.Attributes)
			},
		}
	},
}

var JsxNoDuplicateProps = rule.Rule{

	Name: "react/jsx-no-duplicate-props",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		settings, _ := rule.OptionsAs[JsxNoDuplicatePropsOptions](options)

		report := func(node *ast.Node) {
			_, attributes := jsx.ElementParts(node)
			if attributes == nil {
				return
			}
			properties := attributes.AsJsxAttributes().Properties
			if properties == nil {
				return
			}

			seen := make(map[string]*ast.Node, len(properties.Nodes))

			for _, property := range properties.Nodes {

				name, named := jsx.AttributeName(property)
				if !named {
					continue
				}
				if settings.IgnoreCase {
					name = strings.ToLower(name)
				}
				nameNode := property.AsJsxAttribute().Name()
				if earlier, duplicated := seen[name]; duplicated {
					ctx.ReportNode(earlier, messageJsxNoDuplicateProps)
				}
				seen[name] = nameNode
			}
		}

		return rule.Listeners{

			ast.KindJsxOpeningElement:     report,
			ast.KindJsxSelfClosingElement: report,
		}
	},
}

