var JsxNoUselessFragment = rule.Rule{
	Name: "react/jsx-no-useless-fragment",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[JsxNoUselessFragmentOptions](options)
		if !ok {
			settings = JsxNoUselessFragmentOptions{}
		}

		check := func(node *ast.Node) {
			if jsxNoUselessFragmentIsKeyed(node) {
				return
			}

			children := jsxNoUselessFragmentChildren(node)
			if jsxNoUselessFragmentHasLessThanTwoChildren(children) &&
				!jsxNoUselessFragmentIsOnlyTextAndNotChild(node, children) &&
				!(settings.AllowExpressions && jsxNoUselessFragmentIsSingleExpression(children)) {
				jsxNoUselessFragmentReport(ctx, node, messageJsxNoUselessFragmentNeedsMoreChildren(ctx, children))
			}

			if jsxNoUselessFragmentIsChildOfHtmlElement(node) {
				jsxNoUselessFragmentReport(ctx, node, messageJsxNoUselessFragmentChildOfHtmlElement)
			}
		}

		return rule.Listeners{
			ast.KindJsxFragment: check,

			ast.KindJsxElement: func(node *ast.Node) {
				opening := node.AsJsxElement().OpeningElement
				if opening == nil {
					return
				}

				if jsxNoUselessFragmentIsFragmentName(opening.AsJsxOpeningElement().TagName) {
					check(node)
				}
			},

			ast.KindJsxSelfClosingElement: func(node *ast.Node) {

				if jsxNoUselessFragmentIsFragmentName(node.AsJsxSelfClosingElement().TagName) {
					check(node)
				}
			},
		}
	},
}

var JsxPropsNoSpreadMulti = rule.Rule{

	Name: "react/jsx-props-no-spread-multi",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		report := func(node *ast.Node) {
			_, attributes := jsx.ElementParts(node)
			if attributes == nil {
				return
			}
			properties := attributes.AsJsxAttributes().Properties
			if properties == nil {
				return
			}

			firstIdentifierSpread := make(map[string]*ast.Node, len(properties.Nodes))
			reportedIdentifiers := make(map[string]bool, len(properties.Nodes))

			var memberExpressions []*ast.Node
			var memberSpreads []*ast.Node

			for _, jsxProperty := range properties.Nodes {

				if jsxProperty.Kind != ast.KindJsxSpreadAttribute {
					continue
				}

				argument := ast.SkipOuterExpressions(
					jsxProperty.AsJsxSpreadAttribute().Expression,
					ast.OEKParentheses|ast.OEKAssertions,
				)
				if argument == nil {
					continue
				}

				if argument.Kind == ast.KindIdentifier {
					name := argument.Text()
					if earlier, seen := firstIdentifierSpread[name]; seen {

						if !reportedIdentifiers[name] {
							reportedIdentifiers[name] = true
							ctx.ReportNode(earlier, messageJsxPropsNoSpreadMultiIdentifier)
						}
						continue
					}
					firstIdentifierSpread[name] = jsxProperty
					continue
				}

				if isSpreadableMemberExpression(argument) {
					memberExpressions = append(memberExpressions, argument)
					memberSpreads = append(memberSpreads, jsxProperty)
				}
			}

			for leftIndex := 0; leftIndex < len(memberExpressions); leftIndex++ {
				for rightIndex := leftIndex + 1; rightIndex < len(memberExpressions); rightIndex++ {
					if isSameMemberExpression(memberExpressions[leftIndex], memberExpressions[rightIndex]) {
						ctx.ReportNode(memberSpreads[leftIndex], messageJsxPropsNoSpreadMultiMemberExpression)
					}
				}
			}
		}

		return rule.Listeners{

			ast.KindJsxOpeningElement:     report,
			ast.KindJsxSelfClosingElement: report,
		}
	},
}

var NoAccessStateInSetstate = rule.Rule{
	Name: "react/no-access-state-in-setstate",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		methods := []noAccessStateMethod{}
		variables := []noAccessStateVariable{}

		return rule.Listeners{
			ast.KindSourceFile: func(sourceFile *ast.Node) {

				var visit func(*ast.Node)
				visit = func(node *ast.Node) {
					switch node.Kind {
					case ast.KindCallExpression:
						noAccessStateVisitCall(ctx, node, &methods)

					case ast.KindPropertyAccessExpression:
						noAccessStateVisitStateAccess(ctx, node, &methods, &variables)

					case ast.KindIdentifier:
						noAccessStateVisitIdentifier(ctx, node, variables)

					case ast.KindObjectBindingPattern:
						noAccessStateVisitObjectPattern(node, &variables)
					}

					node.ForEachChild(func(child *ast.Node) bool {
						visit(child)
						return false
					})
				}
				visit(sourceFile)
			},
		}
	},
}

var NoAdjacentInlineElements = rule.Rule{
	Name: "react/no-adjacent-inline-elements",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		isInlineJsxChild := func(child *ast.Node) bool {
			var opening *ast.Node
			switch child.Kind {
			case ast.KindJsxElement:
				opening = child.AsJsxElement().OpeningElement
			case ast.KindJsxSelfClosingElement:
				opening = child
			default:
				return false
			}
			if opening == nil {
				return false
			}
			tagName, _ := jsx.ElementParts(opening)

			if tagName == nil || tagName.Kind != ast.KindIdentifier {
				return false
			}
			return noAdjacentInlineElementsInlineNames[tagName.Text()]
		}

		isInlineCreateElementChild := func(child *ast.Node) bool {
			if noAdjacentInlineElementsIsUpstreamLiteral(child) {

				text := noAdjacentInlineElementsLiteralText(child)
				return !noAdjacentInlineElementsHasEdgeWhitespace(text)
			}
			if child.Kind == ast.KindCallExpression {

				arguments := child.AsCallExpression().Arguments
				if arguments == nil || len(arguments.Nodes) == 0 {
					return false
				}
				first := arguments.Nodes[0]
				if first.Kind != ast.KindStringLiteral {
					return false
				}
				return noAdjacentInlineElementsInlineNames[first.Text()]
			}
			return false
		}

		validate := func(reported *ast.Node, children []*ast.Node, isInline func(*ast.Node) bool) {
			previousIsInline := false
			for _, child := range children {
				currentIsInline := isInline(child)
				if previousIsInline && currentIsInline {
					ctx.ReportNode(reported, messageNoAdjacentInlineElements)
					return
				}
				previousIsInline = currentIsInline
			}
		}

		return rule.Listeners{
			ast.KindJsxElement: func(node *ast.Node) {
				children := node.AsJsxElement().Children
				if children == nil {
					return
				}
				validate(node, children.Nodes, isInlineJsxChild)
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if !isPragmaCreateElementCall(ctx, node) {
					return
				}
				arguments := node.AsCallExpression().Arguments

				if arguments == nil || len(arguments.Nodes) < 3 {
					return
				}
				third := arguments.Nodes[2]

				if third.Kind != ast.KindArrayLiteralExpression {
					return
				}
				elements := third.AsArrayLiteralExpression().Elements
				if elements == nil {
					return
				}
				validate(node, elements.Nodes, isInlineCreateElementChild)
			},
		}
	},
}

