var noArrowFunctionLifecycleStaticMethods = map[string]bool{
	"getDerivedStateFromProps": true,
}

var NoArrowFunctionLifecycle = rule.Rule{
	Name: "react/no-arrow-function-lifecycle",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		sourceText := ctx.SourceFile.Text()

		textOf := func(node *ast.Node) string {
			span := rule.TokenRange(ctx.SourceFile, node)
			if span.Pos() < 0 || span.End() > len(sourceText) || span.Pos() > span.End() {
				return ""
			}
			return sourceText[span.Pos():span.End()]
		}

		check := func(property *ast.Node, key *ast.Node, value *ast.Node, isStatic bool, isClassField bool) {
			if value == nil || value.Kind != ast.KindArrowFunction {
				return
			}
			propertyName, readable := noArrowFunctionLifecyclePropertyName(key)
			if !readable {
				return
			}

			lifecycle := noArrowFunctionLifecycleInstanceMethods
			if isStatic && isClassField {
				lifecycle = noArrowFunctionLifecycleStaticMethods
			}
			if !lifecycle[propertyName] {
				return
			}

			arrow := value.AsArrowFunction()
			body := arrow.Body
			if body == nil {
				ctx.ReportNode(property, noArrowFunctionLifecycleMessage(propertyName))
				return
			}

			parameters, renderable := noArrowFunctionLifecycleParameterNames(arrow.Parameters)
			if !renderable {

				ctx.ReportNode(property, noArrowFunctionLifecycleMessage(propertyName))
				return
			}

			if arrow.Type != nil {
				ctx.ReportNode(property, noArrowFunctionLifecycleMessage(propertyName))
				return
			}

			head := fmt.Sprintf("(%s) ", parameters)
			if !isClassField {
				head = fmt.Sprintf(": function(%s) ", parameters)
			}

			bodyStart := rule.TokenRange(ctx.SourceFile, body).Pos()
			if arrow.EqualsGreaterThanToken == nil {
				ctx.ReportNode(property, noArrowFunctionLifecycleMessage(propertyName))
				return
			}
			arrowEnd := rule.TokenRange(ctx.SourceFile, arrow.EqualsGreaterThanToken).End()
			if len(commentsBetween(sourceText, key.End(), arrowEnd)) > 0 {
				ctx.ReportNode(property, noArrowFunctionLifecycleMessage(propertyName))
				return
			}
			leading := commentsBetween(sourceText, arrowEnd, bodyStart)
			headEnd := bodyStart
			if len(leading) > 0 {
				headEnd = leading[0].start
			}
			headRange := core.NewTextRange(key.End(), headEnd)

			if body.Kind == ast.KindBlock {
				ctx.ReportNodeWithFixes(property, noArrowFunctionLifecycleMessage(propertyName),
					rule.ReplaceRange(headRange, head))
				return
			}

			bodyText := body
			bodyEnd := body.End()
			if body.Kind == ast.KindParenthesizedExpression {
				bodyText = stylePropObjectUnwrapParentheses(body)
				if bodyText == nil {
					bodyText = body
				}
			}

			trailing := commentsBetween(sourceText, bodyEnd, endOfLineAt(sourceText, bodyEnd))
			replacedEnd := bodyEnd
			if len(trailing) > 0 {
				replacedEnd = trailing[len(trailing)-1].end
			}

			for replacedEnd < len(sourceText) && sourceText[replacedEnd] == ';' {
				replacedEnd++
				break
			}

			leadingText := ""
			for _, comment := range leading {
				leadingText += sourceText[comment.start:comment.end]
			}
			trailingText := ""
			for _, comment := range trailing {
				trailingText += sourceText[comment.start:comment.end]
			}

			ctx.ReportNodeWithFixes(property, noArrowFunctionLifecycleMessage(propertyName),
				rule.ReplaceRange(headRange, head),
				rule.ReplaceRange(
					core.NewTextRange(leadingStart(leading, bodyStart), replacedEnd),
					fmt.Sprintf("{ return %s%s%s; }", leadingText, textOf(bodyText), trailingText),
				),
			)
		}

		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if !noArrowFunctionLifecycleIsEs5ComponentCall(node) {
					return
				}
				arguments := node.AsCallExpression().Arguments
				if arguments == nil || len(arguments.Nodes) == 0 {
					return
				}
				object := arguments.Nodes[0]
				if object.Kind != ast.KindObjectLiteralExpression {
					return
				}
				for _, property := range object.AsObjectLiteralExpression().Properties.Nodes {
					if property.Kind != ast.KindPropertyAssignment {
						continue
					}
					assignment := property.AsPropertyAssignment()
					name := assignment.Name()
					check(property, name, assignment.Initializer, false, false)
				}
			},

			ast.KindClassDeclaration: func(node *ast.Node) {
				noArrowFunctionLifecycleCheckClass(node, check)
			},
			ast.KindClassExpression: func(node *ast.Node) {
				noArrowFunctionLifecycleCheckClass(node, check)
			},
		}
	},
}

var messageNoChildrenPropPassFunctionAsArgs = rule.Message{
	Id: "passFunctionAsArgs",
	Description: "A function is passed to `createElement` as a child argument while the " +
		"configuration allows function children only as a prop. Pass it as `children` in the " +
		"props object instead, so a render function is named where it is passed.",
}

var NoChildrenProp = rule.Rule{

	Name: "react/no-children-prop",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		settings, _ := rule.OptionsAs[NoChildrenPropOptions](options)
		isFunction := func(node *ast.Node) bool {
			return settings.AllowFunctions && noChildrenPropIsFunction(node)
		}

		listeners := rule.Listeners{

			ast.KindJsxAttribute: func(node *ast.Node) {

				name, named := jsx.AttributeName(node)
				if !named || name != "children" {
					return
				}
				if initializer := node.AsJsxAttribute().Initializer; initializer != nil &&
					initializer.Kind == ast.KindJsxExpression && isFunction(initializer.AsJsxExpression().Expression) {
					return
				}
				ctx.ReportNode(node.AsJsxAttribute().Name(), messageNoChildrenProp)
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if !utilsreact.IsCreateElementCall(node) {
					return
				}
				properties := createElementPropertiesObject(node)
				if properties == nil {
					return
				}

				for _, property := range properties.Nodes {
					key := staticKeyNode(property)
					if key == nil {
						continue
					}
					if name, static := staticKeyName(key); static && name == "children" {
						if !isFunction(noChildrenPropPropertyValue(property)) {
							ctx.ReportNode(key, messageNoChildrenProp)
						}
						return
					}
				}

				if arguments := node.AsCallExpression().Arguments.Nodes; len(arguments) == 3 && isFunction(arguments[2]) {
					ctx.ReportNode(node, messageNoChildrenPropPassFunctionAsArgs)
				}
			},
		}
		if settings.AllowFunctions {

			listeners[ast.KindJsxElement] = func(node *ast.Node) {
				children := node.AsJsxElement().Children
				if children == nil || len(children.Nodes) != 1 {
					return
				}
				child := children.Nodes[0]
				if child.Kind == ast.KindJsxExpression && isFunction(child.AsJsxExpression().Expression) {
					ctx.ReportNode(node, messageNoChildrenPropNestFunction)
				}
			}
		}
		return listeners
	},
}

var NoDanger = rule.Rule{
	Name: "react/no-danger",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[NoDangerOptions](options)
		if !ok {

			settings = DefaultNoDangerOptions()
		}

		checkAttributes := func(node *ast.Node) {
			tagName, attributes := jsx.ElementParts(node)
			if tagName == nil || attributes == nil {
				return
			}
			properties := attributes.AsJsxAttributes().Properties
			if properties == nil {
				return
			}

			renderedName := renderJsxTagName(tagName)
			if !isDomElementName(renderedName) && !matchesAnyPattern(settings.CustomComponentNames, renderedName) {
				return
			}

			for _, property := range properties.Nodes {

				name, readable := jsx.AttributeName(property)
				if !readable || name != dangerousPropertyName {
					continue
				}
				ctx.ReportNode(property, rule.Message{
					Id: "dangerousProp",
					Description: fmt.Sprintf(
						"This element sets %s, which hands React a raw string and tells it to "+
							"skip escaping. React named the property this way on purpose: any "+
							"value reaching it that a user can influence is a cross-site "+
							"scripting hole, and the danger is invisible at the render site "+
							"because the markup arrives from somewhere else. Render the content "+
							"as children instead, or sanitize it and say at the call site who "+
							"did.",
						name,
					),
				})
			}
		}

		return rule.Listeners{

			ast.KindJsxOpeningElement:     checkAttributes,
			ast.KindJsxSelfClosingElement: checkAttributes,
		}
	},
}

var NoDangerWithChildren = rule.Rule{

	Name:             "react/no-danger-with-children",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{

			ast.KindJsxElement: func(node *ast.Node) {
				element := node.AsJsxElement()
				attributes := element.OpeningElement.AsJsxOpeningElement().Attributes
				if !hasElementChildren(ctx, attributes, element.Children) {
					return
				}
				if hasJsxProperty(ctx, attributes, dangerPropertyName) {
					ctx.ReportNode(node, messageNoDangerWithChildren)
				}
			},

			ast.KindJsxSelfClosingElement: func(node *ast.Node) {
				attributes := node.AsJsxSelfClosingElement().Attributes
				if !hasElementChildren(ctx, attributes, nil) {
					return
				}
				if hasJsxProperty(ctx, attributes, dangerPropertyName) {
					ctx.ReportNode(node, messageNoDangerWithChildren)
				}
			},

			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()
				arguments := call.Arguments

				if arguments == nil || len(arguments.Nodes) <= 1 {
					return
				}
				if !isStaticCreateElementCallee(call.Expression) {
					return
				}

				properties := arguments.Nodes[1]

				hasChildren := len(arguments.Nodes) > 2 ||
					objectExpressionHasProperty(ctx, properties, childrenPropertyName)
				if !hasChildren {
					return
				}

				if objectExpressionHasProperty(ctx, properties, dangerPropertyName) {
					ctx.ReportNode(node, messageNoDangerWithChildren)
				}
			},
		}
	},
}

var NoDeprecated = rule.Rule{

	Name: "react/no-deprecated",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		pragma := reactPragmaFor(ctx)
		deprecations := defaultPragmaDeprecations
		if pragma != defaultPragma {
			deprecations = deprecationsForPragma(pragma)
		}

		report := func(node *ast.Node, name string) {
			entry, deprecated := deprecations[name]
			if !deprecated {
				return
			}
			ctx.Report(rule.Diagnostic{
				Range:      rule.TokenRange(ctx.SourceFile, node),
				Message:    rule.Message{Id: noDeprecatedMessageId, Description: entry.describe(name)},
				SourceFile: ctx.SourceFile,
			})
		}

		return rule.Listeners{

			ast.KindPropertyAccessExpression: func(node *ast.Node) {
				report(node, sourceSliceOf(ctx, node))
			},

			ast.KindImportDeclaration: func(node *ast.Node) {
				moduleName, named := deprecatedModuleAlias(node)
				if !named {
					return
				}
				forEachNamedImportSpecifier(node, func(specifier *ast.Node, importedName string) {
					report(specifier, moduleName+"."+importedName)
				})
			},

			ast.KindVariableDeclaration: func(node *ast.Node) {
				moduleName, named := destructuredReactModuleName(node, pragma)
				if !named {
					return
				}
				forEachDestructuredProperty(node, func(property *ast.Node, key string) {
					report(property, moduleName+"."+key)
				})
			},

			ast.KindClassDeclaration:        reportLifeCycleMethods(report),
			ast.KindClassExpression:         reportLifeCycleMethods(report),
			ast.KindObjectLiteralExpression: reportLifeCycleMethods(report),
		}
	},
}

