var messageOnlyOneComponent = rule.Message{
	Id:          "onlyOneComponent",
	Description: "Declare only one React component per file",
}

var NoMultiComp = rule.Rule{
	Name: "react/no-multi-comp",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		settings := DefaultNoMultiCompOptions()
		if configured, isConfigured := rule.OptionsAs[NoMultiCompOptions](options); isConfigured {
			settings = configured
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}

				components := collectDetectedComponents(ctx, node)
				if len(components) <= 1 {
					return
				}

				kept := components[:0:0]
				for _, component := range components {
					if settings.IgnoreStateless && component.stateless {
						continue
					}
					kept = append(kept, component)
				}

				if len(kept) <= 1 {
					return
				}
				for _, component := range kept[1:] {
					ctx.ReportNode(component.node, messageOnlyOneComponent)
				}
			},
		}
	},
}

var NoNamespace = rule.Rule{
	Name: "react/no-namespace",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		reportElement := func(node *ast.Node) {

			tagName, _ := jsx.ElementParts(node)

			if tagName == nil || tagName.Kind != ast.KindJsxNamespacedName {
				return
			}
			ctx.ReportNode(node, messageNoNamespace)
		}

		return rule.Listeners{
			ast.KindJsxOpeningElement:     reportElement,
			ast.KindJsxSelfClosingElement: reportElement,
			ast.KindCallExpression: func(node *ast.Node) {

				if ctx.TypeChecker == nil {
					return
				}
				call := node.AsCallExpression()
				if !isPragmaCreateElementCall(ctx, node) {
					return
				}
				if call.Arguments == nil || len(call.Arguments.Nodes) == 0 {
					return
				}

				first := call.Arguments.Nodes[0]
				if first.Kind != ast.KindStringLiteral {
					return
				}
				if !strings.Contains(first.Text(), ":") {
					return
				}
				ctx.ReportNode(node, messageNoNamespace)
			},
		}
	},
}

