var NoUnknownProperty = rule.Rule{
	Name: "react/no-unknown-property",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[NoUnknownPropertyOptions](options)
		ignored := make(map[string]bool, len(settings.Ignore))
		for _, name := range settings.Ignore {
			ignored[name] = true
		}

		return rule.Listeners{
			ast.KindJsxAttribute: func(node *ast.Node) {
				actualName, readable := noUnknownPropertyAttributeNameText(ctx, node)
				if !readable {
					return
				}

				if ignored[actualName] {
					return
				}
				name := noUnknownPropertyNormalizeAttributeCase(actualName)

				tag := noUnknownPropertyTagOf(node)
				if tag.HasDot {
					return
				}

				if noUnknownPropertyIsValidDataAttribute(name) {

					if settings.RequireDataLowercase && strings.ToLower(name) != name {
						ctx.ReportNode(node, noUnknownPropertyDataLowercaseRequired(
							actualName, strings.ToLower(actualName)))
					}
					return
				}

				if noUnknownPropertyAriaProperties[name] {
					return
				}

				if tag.Name == "fbt" || tag.Name == "fbs" {
					return
				}

				if !tag.IsHtmlLike {
					return
				}

				if allowedTags, restricted := noUnknownPropertyAttributeTags[name]; restricted {
					if tag.Name != "" {
						allowed := false
						for _, candidate := range allowedTags {
							if candidate == tag.Name {
								allowed = true
								break
							}
						}
						if !allowed {
							ctx.ReportNode(node, noUnknownPropertyInvalidPropOnTag(
								actualName, tag.Name, allowedTags))
						}
						return
					}
				}

				standardName, found := noUnknownPropertyStandardName(name)
				if found && standardName == name {
					return
				}
				if found {

					nameNode := node.AsJsxAttribute().Name()
					ctx.ReportNodeWithFixes(node,
						noUnknownPropertyUnknownPropWithStandardName(actualName, standardName),
						rule.ReplaceRange(rule.TokenRange(ctx.SourceFile, nameNode), standardName))
					return
				}

				ctx.ReportNode(node, noUnknownPropertyUnknownProp(actualName))
			},
		}
	},
}

var (
	messageUnsafeComponentWillMount = rule.Message{
		Id: "unsafeComponentWillMount",
		Description: "`componentWillMount` runs before the first render and is not guaranteed to " +
			"run exactly once, so work started there can be discarded or repeated when React " +
			"interrupts the render. Move the work to `componentDidMount`, which runs after the " +
			"tree is committed and cannot be thrown away.",
	}
	messageUnsafeComponentWillReceiveProps = rule.Message{
		Id: "unsafeComponentWillReceiveProps",
		Description: "`componentWillReceiveProps` runs on every parent render rather than only when " +
			"the props changed, so state derived inside it drifts out of step with the props it " +
			"was derived from. Compute the value in `getDerivedStateFromProps`, which is handed " +
			"both the incoming props and the current state and cannot read `this`.",
	}
	messageUnsafeComponentWillUpdate = rule.Message{
		Id: "unsafeComponentWillUpdate",
		Description: "`componentWillUpdate` runs while React is partway through preparing an " +
			"update it may still abandon, so side effects there can fire for a render that never " +
			"commits. Move them to `componentDidUpdate`, which runs only after the update reached " +
			"the screen.",
	}
)

