var StaticPropertyPlacement = rule.Rule{
	Name:             "react/static-property-placement",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		settings := DefaultStaticPropertyPlacementOptions()
		if configured, isConfigured := rule.OptionsAs[StaticPropertyPlacementOptions](options); isConfigured &&
			configured.Positions != nil {
			settings = configured
		}

		judge := func(node *ast.Node, propertyName string, arm StaticPropertyPlacementPosition, isStatic bool) {
			expected, isJudged := settings.Positions[propertyName]
			if !isJudged {
				return
			}
			mismatched := expected != arm
			notStaticEnough := !isStatic &&
				(expected == StaticPublicField || expected == StaticGetter)
			if !mismatched && !notStaticEnough {
				return
			}
			ctx.ReportNode(node, messageStaticPropertyPlacement(expected, propertyName))
		}

		return rule.Listeners{
			ast.KindPropertyDeclaration: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if !staticPropertyPlacementInReactClass(node) {
					return
				}
				propertyName, named := staticPropertyPlacementNameOf(node)
				if !named {
					return
				}
				judge(node, propertyName, StaticPublicField, staticPropertyPlacementIsStatic(node))
			},

			ast.KindGetAccessor: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if !staticPropertyPlacementIsStatic(node) {
					return
				}
				if !staticPropertyPlacementInReactClass(node) {
					return
				}
				propertyName, named := staticPropertyPlacementNameOf(node)
				if !named {
					return
				}
				judge(node, propertyName, StaticGetter, true)
			},

			ast.KindBinaryExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				expression := node.AsBinaryExpression()
				if expression.OperatorToken == nil ||
					expression.OperatorToken.Kind != ast.KindEqualsToken {
					return
				}
				target := expression.Left
				if target == nil || target.Kind != ast.KindPropertyAccessExpression {
					return
				}

				if staticPropertyPlacementInsideAClass(node) {
					return
				}
				propertyName, named := staticPropertyPlacementNameOf(target)
				if !named {
					return
				}
				if !staticPropertyPlacementReceiverIsReactClass(ctx, target.AsPropertyAccessExpression().Expression) {
					return
				}

				judge(target, propertyName, PropertyAssignment, false)
			},
		}
	},
}

var stylePropObjectMessage = rule.Message{
	Id:          "stylePropNotObject",
	Description: "Style prop value must be an object",
}

var StylePropObject = rule.Rule{
	Name: "react/style-prop-object",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[StylePropObjectOptions](options)
		allowed := make(map[string]bool, len(settings.Allow))
		for _, name := range settings.Allow {
			allowed[name] = true
		}

		checkIdentifier := func(node *ast.Node, shorthand *ast.Node) {
			if ctx.TypeChecker == nil {
				return
			}
			var symbol *ast.Symbol
			if shorthand != nil {
				symbol = ctx.TypeChecker.GetShorthandAssignmentValueSymbol(shorthand)
			} else {
				symbol = ctx.TypeChecker.GetSymbolAtLocation(node)
			}
			if symbol == nil || len(symbol.Declarations) == 0 {
				return
			}

			declaration := symbol.Declarations[0]
			if declaration.Kind != ast.KindVariableDeclaration {
				return
			}
			initializer := stylePropObjectUnwrapParentheses(declaration.AsVariableDeclaration().Initializer)
			if stylePropObjectIsNonNullLiteral(initializer) {
				ctx.ReportNode(node, stylePropObjectMessage)
			}
		}

		return rule.Listeners{
			ast.KindJsxAttribute: func(node *ast.Node) {
				attributeName, named := jsx.AttributeName(node)
				if !named || attributeName != "style" {
					return
				}
				attribute := node.AsJsxAttribute()

				if attribute.Initializer == nil {
					return
				}

				attributes := node.Parent
				if attributes != nil && attributes.Kind == ast.KindJsxAttributes {

					if tagName, _ := jsx.ElementParts(attributes.Parent); tagName != nil &&
						tagName.Kind == ast.KindIdentifier && allowed[tagName.Text()] {
						return
					}
				}

				if attribute.Initializer.Kind != ast.KindJsxExpression {
					ctx.ReportNode(node, stylePropObjectMessage)
					return
				}

				expression := stylePropObjectUnwrapParentheses(attribute.Initializer.AsJsxExpression().Expression)

				if stylePropObjectIsNonNullLiteral(expression) || expression == nil {
					ctx.ReportNode(node, stylePropObjectMessage)
					return
				}
				if expression.Kind == ast.KindIdentifier {

					checkIdentifier(expression, nil)
				}
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if !isPragmaCreateElementCall(ctx, node) {
					return
				}
				arguments := node.AsCallExpression().Arguments

				if arguments == nil || len(arguments.Nodes) < 2 {
					return
				}

				first := arguments.Nodes[0]
				if first.Kind == ast.KindIdentifier && allowed[first.Text()] {
					return
				}

				properties := arguments.Nodes[1]
				if properties.Kind != ast.KindObjectLiteralExpression {
					return
				}
				for _, property := range properties.AsObjectLiteralExpression().Properties.Nodes {

					var value *ast.Node
					var shorthand *ast.Node
					switch property.Kind {
					case ast.KindPropertyAssignment:
						assignment := property.AsPropertyAssignment()
						name := assignment.Name()
						if name == nil || name.Kind != ast.KindIdentifier || name.Text() != "style" {
							continue
						}
						value = assignment.Initializer

					case ast.KindShorthandPropertyAssignment:

						name := property.AsShorthandPropertyAssignment().Name()
						if name == nil || name.Kind != ast.KindIdentifier || name.Text() != "style" {
							continue
						}
						value = name
						shorthand = property

					default:
						continue
					}

					value = stylePropObjectUnwrapParentheses(value)
					if value == nil {
						continue
					}
					if value.Kind == ast.KindIdentifier {
						checkIdentifier(value, shorthand)
						return
					}
					if stylePropObjectIsNonNullLiteral(value) {

						ctx.ReportNode(value, stylePropObjectMessage)
					}
					return
				}
			},
		}
	},
}

var UnsupportedSyntax = rule.Rule{

	Name: "react-hooks/unsupported-syntax",

	NeedsTypeChecker: true,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindIdentifier: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if node.Text() != "eval" {
					return
				}

				if !utilsreact.IsInsideComponentOrHook(node) {
					return
				}
				symbol := ctx.TypeChecker.GetSymbolAtLocation(node)
				if !type_checking.IsSymbolFromDefaultLibrary(ctx.Program, symbol) {
					return
				}
				ctx.ReportNode(node, messageUnsupportedEval)
			},
			ast.KindWithStatement: func(node *ast.Node) {
				if !utilsreact.IsInsideComponentOrHook(node) {
					return
				}
				ctx.ReportNode(node, messageUnsupportedWith)
			},
			ast.KindClassDeclaration: func(node *ast.Node) {

				if !utilsreact.IsInsideComponentOrHook(node) {
					return
				}
				ctx.ReportNode(node, messageUnsupportedInlineClass)
			},
		}
	},
}

var UseMemo = rule.Rule{

	Name: "react-hooks/use-memo",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				call := node.AsCallExpression()
				if call == nil {
					return
				}
				kind, isManualMemo := manualMemoKind(ctx, call.Expression)
				if !isManualMemo {
					return
				}
				if !utilsreact.IsInsideComponentOrHook(node) {
					return
				}

				arguments := callArguments(call)
				if len(arguments) == 0 {

					ctx.ReportNode(node, messageUseMemoMissingCallback)
					return
				}

				callback := arguments[0]
				inlineCallback := inlineFunctionArgument(callback)
				if inlineCallback == nil {

					if callback.Kind == ast.KindSpreadElement {
						return
					}
					ctx.ReportNode(callback, messageUseMemoCallbackNotInline)
				}

				if len(arguments) >= 2 {
					checkDependencyList(ctx, kind, arguments[1])
				}

				if inlineCallback == nil {
					return
				}
				checkInlineCallback(ctx, kind, inlineCallback)
			},
		}
	},
}

var voidDomElements = map[string]bool{
	"area": true, "base": true, "br": true, "col": true,
	"embed": true, "hr": true, "img": true, "input": true,
	"keygen": true, "link": true, "menuitem": true, "meta": true,
	"param": true, "source": true, "track": true, "wbr": true,
}

var VoidDomElementsNoChildren = rule.Rule{

	Name: "react/void-dom-elements-no-children",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		reportElement := func(node *ast.Node, children *ast.NodeList) {
			tagName, attributes := jsx.ElementParts(node)

			if tagName == nil || tagName.Kind != ast.KindIdentifier {
				return
			}
			elementName := tagName.Text()
			if !voidDomElements[elementName] {
				return
			}

			hasChildren := children != nil && len(children.Nodes) > 0
			if !hasChildren && !hasContentAttribute(attributes) {
				return
			}

			ctx.ReportNode(tagName, voidDomElementMessage(elementName))
		}

		return rule.Listeners{

			ast.KindJsxElement: func(node *ast.Node) {
				element := node.AsJsxElement()
				reportElement(element.OpeningElement, element.Children)
			},

			ast.KindJsxSelfClosingElement: func(node *ast.Node) {
				reportElement(node, nil)
			},

			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()

				callee := call.Expression
				if callee == nil {
					return
				}
				switch callee.Kind {
				case ast.KindIdentifier, ast.KindPropertyAccessExpression, ast.KindElementAccessExpression:
				default:
					return
				}
				if !utilsreact.IsCreateElementCall(node) {
					return
				}

				arguments := call.Arguments
				if arguments == nil || len(arguments.Nodes) == 0 {
					return
				}

				elementNameNode := arguments.Nodes[0]
				if elementNameNode.Kind != ast.KindStringLiteral {
					return
				}
				elementName := elementNameNode.Text()
				if !voidDomElements[elementName] {
					return
				}

				if len(arguments.Nodes) < 2 {
					return
				}

				properties := arguments.Nodes[1]
				if properties.Kind != ast.KindObjectLiteralExpression {
					return
				}

				hasChildren := len(arguments.Nodes) > 2 || objectLiteralHasContentProperty(properties)
				if !hasChildren {
					return
				}

				ctx.ReportNode(elementNameNode, voidDomElementMessage(elementName))
			},
		}
	},
}

var VoidUseMemo = rule.Rule{

	Name: "react-hooks/void-use-memo",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()

				enclosing := enclosingFunctionOf(node)
				if enclosing == nil || !isUseMemoCallee(call.Expression, enclosing) {
					return
				}
				if !isVoidUseMemoCompiledFunction(enclosing) {
					return
				}

				callback := inlineUseMemoCallback(call)
