var nextApiFunctionNames = map[string]bool{
	"generateMetadata":     true,
	"generateStaticParams": true,
	"generateViewport":     true,
}

var NextRequireApiParameterName = rule.Rule{
	Name: "structure/next-require-api-parameter-name",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		fileContext := FileContextFor(ctx.SourceFile.FileName().AsString())
		if !fileContext.IsPageFile && !fileContext.IsLayoutFile {

			return nil
		}

		return rule.Listeners{
			ast.KindFunctionDeclaration: func(node *ast.Node) {
				declaration := node.AsFunctionDeclaration()

				name := declaration.Name()
				if name == nil || !nextApiFunctionNames[name.Text()] {
					return
				}

				parameters := parameterNodes(declaration.Parameters)
				if len(parameters) == 0 {
					return
				}

				typeNode := parameterTypeNode(parameters[0])
				if typeNode == nil || typeNode.Kind != ast.KindTypeLiteral {

					return
				}

				for _, member := range typeNode.AsTypeLiteralNode().Members.Nodes {
					if member.Kind != ast.KindPropertySignature {
						continue
					}
					key := member.AsPropertySignatureDeclaration().Name()
					if key == nil || key.Kind != ast.KindIdentifier {
						continue
					}

					switch key.Text() {
					case "parameters":
						ctx.ReportNodeWithFixes(key, messageUseParamsNotParameters(),
							ctx.ReplaceNode(key, "params"))
					case "searchParameters":
						ctx.ReportNodeWithFixes(key, messageUseSearchParamsNotSearchParameters(),
							ctx.ReplaceNode(key, "searchParams"))
					}
				}
			},
		}
	},
}

var NextRequirePageDefaultExport = rule.Rule{
	Name:       "structure/next-require-page-default-export",
	NoListener: rule.NoListenerAnswersInRun,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		fileContext := FileContextFor(ctx.SourceFile.FileName().AsString())
		if !fileContext.IsReactFile || !fileContext.IsPageFile {
			return nil
		}

		sourceFile := ctx.SourceFile.AsNode()
		hasDefaultExport := false

		imported := importedLocalNames(sourceFile)

		sourceFile.ForEachChild(func(statement *ast.Node) bool {
			defaultExport, ok := pageDefaultExportOf(statement, imported)
			if !ok {
				return false
			}
			hasDefaultExport = true

			if defaultExport.separate {
				ctx.ReportNode(statement, messagePageDefaultExportInline())
			}
			if defaultExport.name != "" && !strings.HasSuffix(defaultExport.name, "PageRoute") {
				ctx.ReportNode(statement, messagePageDefaultExportNameSuffix())
			}
			return false
		})

		if !hasDefaultExport {
			ctx.ReportNode(sourceFile, messagePageRequireDefaultExport())
		}

		return nil
	},
}

var ReactComponentNoConstAssignment = rule.Rule{
	Name: "structure/react-component-no-const-assignment",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil || !FileContextFor(ctx.SourceFile.FileName().AsString()).IsReactFile {
			return nil
		}

		return rule.Listeners{
			ast.KindVariableStatement: func(node *ast.Node) {
				statement := node.AsVariableStatement()
				if statement.DeclarationList == nil {
					return
				}

				isExported := module.IsExportedByName(statement.Modifiers())

				for _, declarationNode := range statement.DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
					declaration := declarationNode.AsVariableDeclaration()
					name := declaration.Name()
					if name == nil || name.Kind != ast.KindIdentifier {
						continue
					}
					if !react.IsLikelyComponentName(name.Text()) {
						continue
					}
					initializer := declaration.Initializer
					if initializer == nil {
						continue
					}
					if isForwardRefCall(initializer) {
						continue
					}

					if initializer.Kind != ast.KindFunctionExpression && initializer.Kind != ast.KindArrowFunction {
						continue
					}
					ctx.ReportNode(name, messageNoConstAssignment(name.Text(), isExported))
				}
			},
		}
	},
}

