var ReactComponentNoDisplayName = rule.Rule{
	Name: "structure/react-component-no-display-name",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		wrappedAsAnonymous := map[string]bool{}

		var componentNames map[string]bool

		return rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()
				name := declaration.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}
				if isAnonymousWrapperCall(declaration.Initializer) {
					wrappedAsAnonymous[name.Text()] = true
				}
			},

			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()

				if binary.OperatorToken == nil || binary.OperatorToken.Kind != ast.KindEqualsToken {
					return
				}

				left := ast.SkipParentheses(binary.Left)
				if left == nil || left.Kind != ast.KindPropertyAccessExpression {

					return
				}

				access := left.AsPropertyAccessExpression()
				property := access.Name()
				if property == nil || property.Kind != ast.KindIdentifier || property.Text() != "displayName" {
					return
				}

				target := ast.SkipParentheses(access.Expression)
				if target == nil || target.Kind != ast.KindIdentifier || wrappedAsAnonymous[target.Text()] {
					return
				}
				if componentNames == nil {
					componentNames = componentsDeclaredAtTopLevel(ctx.SourceFile.AsNode())
				}
				if !componentNames[target.Text()] {
					return
				}

				ctx.ReportNode(node, messageNoDisplayNameAssignment())
			},
		}
	},
}

var forwardRefTypeNames = map[string]bool{
	"ForwardRefExoticComponent": true,
	"ForwardedRef":              true,
}

var ReactComponentNoForwardRef = rule.Rule{
	Name: "structure/react-component-no-forward-ref",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindImportDeclaration: func(node *ast.Node) {
				reportForwardRefImport(ctx, node)
			},

			ast.KindCallExpression: func(node *ast.Node) {
				callee := ast.SkipParentheses(node.AsCallExpression().Expression)
				if callee == nil {
					return
				}

				switch callee.Kind {
				case ast.KindIdentifier:
					if callee.Text() == "forwardRef" {
						ctx.ReportNode(callee, messageNoForwardRefCall())
					}
				case ast.KindPropertyAccessExpression:
					if react.IsNamespacedMember(callee, func(name string) bool { return name == "forwardRef" }) {
						ctx.ReportNode(callee, messageNoForwardRefCall())
					}
				}
			},

			ast.KindQualifiedName: func(node *ast.Node) {
				qualified := node.AsQualifiedName()
				left, right := qualified.Left, qualified.Right
				if left == nil || right == nil {
					return
				}
				if left.Kind == ast.KindIdentifier && left.Text() == "React" &&
					right.Kind == ast.KindIdentifier && forwardRefTypeNames[right.Text()] {
					ctx.ReportNode(node, messageNoForwardRefCall())
				}
			},
		}
	},
}

var ReactComponentNoSeparateNamedExport = rule.Rule{
	Name: "structure/react-component-no-separate-named-export",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if !FileContextFor(ctx.SourceFile.FileName().AsString()).IsReactFile {
			return nil
		}

		declaredComponents, declarationStatements := componentNamesDeclaredIn(ctx.SourceFile.AsNode())
		if len(declaredComponents) == 0 {
			return nil
		}

		return rule.Listeners{
			ast.KindExportDeclaration: func(node *ast.Node) {
				declaration := node.AsExportDeclaration()

				if declaration.ModuleSpecifier != nil {
					return
				}

				if declaration.ExportClause == nil || declaration.ExportClause.Kind != ast.KindNamedExports {
					return
				}

				for _, element := range declaration.ExportClause.AsNamedExports().Elements.Nodes {
					name := element.AsExportSpecifier().Name()
					if name == nil || name.Kind != ast.KindIdentifier {
						continue
					}
					if declaredComponents[name.Text()] {

						fix, repairable := separateNamedExportRepair(ctx, node, declaredComponents,
							declarationStatements)
						if !repairable {
							ctx.ReportNode(node, messageNoSeparateNamedExport())
							return
						}
						ctx.ReportNodeWithFixes(node, messageNoSeparateNamedExport(), fix)
						return
					}
				}
			},
		}
	},
}

