var ConsistentTypeImports = rule.Rule{
	Name: "@typescript-eslint/consistent-type-imports",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[ConsistentTypeImportsOptions](options)
		if !ok {

			settings = DefaultConsistentTypeImportsOptions()
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				sourceFile := node.AsSourceFile()
				if sourceFile == nil {
					return
				}

				declarations := imports.Declarations(sourceFile)
				judgesValueImports := settings.Prefer != ConsistentTypeImportsPreferNoTypeImports &&
					consistentTypeImportsHasValueImport(declarations)
				facts := consistentTypeImportsScan(ctx, sourceFile, settings.DisallowTypeAnnotations,
					judgesValueImports, declarations)

				switch settings.Prefer {
				case ConsistentTypeImportsPreferNoTypeImports:
					reportTypeKeywordsToRemove(ctx, declarations)
				default:
					if judgesValueImports {
						reportImportsUsedOnlyAsTypes(ctx, sourceFile, declarations, facts, settings.FixStyle)
					}
				}
			},
		}
	},
}

var messageDefaultParamLastShouldBeLast = rule.Message{
	Id: "shouldBeLast",
	Description: "A parameter with a default sits before a parameter without one, so the default " +
		"can never be taken without passing `undefined` explicitly at every call site. Move it " +
		"after the required parameters, where omitting it is what selects the default.",
}

var DefaultParamLast = rule.Rule{
	Name: "@typescript-eslint/default-param-last",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		check := func(node *ast.Node) {

			if node.Body() == nil {
				return
			}
			parameters := node.Parameters()

			lastPlainIndex := -1
			for index, parameter := range parameters {
				if isPlainParameter(parameter) {
					lastPlainIndex = index
				}
			}
			for index, parameter := range parameters {

				if index >= lastPlainIndex {
					break
				}
				declaration := parameter.AsParameterDeclaration()

				if declaration.Initializer == nil && declaration.QuestionToken == nil {
					continue
				}

				ctx.ReportNode(parameter, messageDefaultParamLastShouldBeLast)
			}
		}

		return rule.Listeners{
			ast.KindFunctionDeclaration: check,
			ast.KindFunctionExpression:  check,
			ast.KindArrowFunction:       check,

			ast.KindMethodDeclaration: check,
			ast.KindConstructor:       check,
			ast.KindGetAccessor:       check,
			ast.KindSetAccessor:       check,
		}
	},
}

var DotNotation = rule.Rule{
	Name: "@typescript-eslint/dot-notation",

	NeedsTypeChecker: true,

	ProgramReads: rule.ReadsCompilerOptions,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		resolved, isDotNotationOptions := rule.OptionsAs[DotNotationOptions](options)
		if !isDotNotationOptions {
			resolved = DefaultDotNotationOptions()
		}
		settings := dotnotation.Settings{AllowKeywords: true, AllowPattern: dotnotation.CompileAllowPattern(resolved.AllowPattern)}
		if resolved.AllowKeywords != nil {
			settings.AllowKeywords = *resolved.AllowKeywords
		}

		allowIndexSignature := resolved.AllowIndexSignaturePropertyAccess ||
			(ctx.Program != nil && ctx.Program.Options().NoPropertyAccessFromIndexSignature.IsTrue())
		if ctx.TypeChecker != nil &&
			(resolved.AllowPrivateClassPropertyAccess || resolved.AllowProtectedClassPropertyAccess || allowIndexSignature) {
			settings.DeclinesComputed = func(access *ast.Node, key *ast.Node) bool {
				object := access.AsElementAccessExpression().Expression
				property := ctx.TypeChecker.GetSymbolAtLocation(key)
				if property == nil && key.Kind == ast.KindStringLiteral {
					objectType := ctx.TypeChecker.GetNonNullableType(ctx.TypeChecker.GetTypeAtLocation(object))
					for _, candidate := range ctx.TypeChecker.GetPropertiesOfType(objectType) {
						if candidate.Name == key.Text() {
							property = candidate
							break
						}
					}
				}

				switch dotNotationFirstModifier(property) {
				case ast.KindPrivateKeyword:
					if resolved.AllowPrivateClassPropertyAccess {
						return true
					}
				case ast.KindProtectedKeyword:
					if resolved.AllowProtectedClassPropertyAccess {
						return true
					}
				}

				if property == nil && allowIndexSignature {
					objectType := ctx.TypeChecker.GetNonNullableType(ctx.TypeChecker.GetTypeAtLocation(object))
					for _, indexInfo := range ctx.TypeChecker.GetIndexInfosOfType(objectType) {
						if type_checking.IsTypeFlagSet(indexInfo.KeyType(), checker.TypeFlagsStringLike) {
							return true
						}
					}
				}
				return false
			}
		}
		return dotnotation.Listeners(ctx, settings)
	},
}

var InitDeclarations = rule.Rule{
	Name: "@typescript-eslint/init-declarations",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[InitDeclarationsOptions](options)
		if !isSettings {
			settings = DefaultInitDeclarationsSettings()
		}

		if settings.Mode != InitDeclarationsAlways && settings.Mode != InitDeclarationsNever {
			return nil
		}

		return rule.Listeners{
			ast.KindVariableDeclarationList: func(node *ast.Node) {
				list := node.AsVariableDeclarationList()

				if list.Flags&ast.NodeFlagsAmbient != 0 {
					return
				}
				if list.Declarations == nil {
					return
				}

				enclosingLoop := enclosingLoopOfDeclarationList(node)

				for _, declarator := range list.Declarations.Nodes {
					declaration := declarator.AsVariableDeclaration()

					name := declaration.Name()
					if name == nil || name.Kind != ast.KindIdentifier {
						continue
					}

					initialized := isDeclarationInitialized(declaration, node, enclosingLoop)

					if settings.Mode == InitDeclarationsAlways {
						if initialized {
							continue
						}

						ctx.ReportNode(name, buildInitDeclarationsMessage(
							"initialized", name.AsIdentifier().Text))
						continue
					}

					if !initialized {
						continue
					}

					if list.Flags&(ast.NodeFlagsConst|ast.NodeFlagsUsing|ast.NodeFlagsAwaitUsing) != 0 {
						continue
					}
					if settings.IgnoreForLoopInit && enclosingLoop != nil {
						continue
					}

					ctx.ReportNode(declarator, buildInitDeclarationsMessage(
						"notInitialized", name.AsIdentifier().Text))
				}
			},
		}
	},
}

