var NoArrayDelete = rule.Rule{
	Name: "@typescript-eslint/no-array-delete",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		isUnderlyingTypeArray := func(t *checker.Type) bool {
			if type_checking.IsTypeFlagSet(t, checker.TypeFlagsUnion) {
				for _, t := range t.Types() {
					if !checker.Checker_isArrayOrTupleType(ctx.TypeChecker, t) {
						return false
					}
				}
				return true
			}

			if type_checking.IsTypeFlagSet(t, checker.TypeFlagsIntersection) {
				for _, t := range t.Types() {
					if checker.Checker_isArrayOrTupleType(ctx.TypeChecker, t) {
						return true
					}
				}
				return false
			}

			return checker.Checker_isArrayOrTupleType(ctx.TypeChecker, t)
		}

		return rule.Listeners{
			ast.KindDeleteExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if node.Kind != ast.KindDeleteExpression {
					return
				}
				deleteExpression := ast.SkipParentheses(node.AsDeleteExpression().Expression)

				if !ast.IsElementAccessExpression(deleteExpression) {
					return
				}

				expression := deleteExpression.AsElementAccessExpression()

				argType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, expression.Expression)

				if !isUnderlyingTypeArray(argType) {
					return
				}

				expressionRange := type_checking.TrimNodeTextRange(ctx.SourceFile, expression.Expression)
				argumentRange := type_checking.TrimNodeTextRange(ctx.SourceFile, expression.ArgumentExpression)

				deleteTokenRange := scanner.GetRangeOfTokenAtPosition(ctx.SourceFile, node.Pos())
				leftBracketTokenRange := scanner.GetRangeOfTokenAtPosition(ctx.SourceFile, expressionRange.End())
				rightBracketTokenRange := scanner.GetRangeOfTokenAtPosition(ctx.SourceFile, argumentRange.End())

				ctx.ReportNodeWithSuggestions(node, buildNoArrayDeleteMessage(), rule.Suggestion{
					Message: buildUseSpliceMessage(),
					Fixes: []rule.Fix{
						rule.RemoveRange(deleteTokenRange),
						rule.ReplaceRange(leftBracketTokenRange, ".splice("),
						rule.ReplaceRange(rightBracketTokenRange, ", 1)"),
					},
				})
			},
		}
	},
}

var NoBaseToString = rule.Rule{
	Name: "@typescript-eslint/no-base-to-string",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[NoBaseToStringOptions](options)
		if !isSettings {
			settings = DefaultNoBaseToStringSettings()
		}
		state := &noBaseToStringState{ctx: ctx, settings: settings}

		return rule.Listeners{

			ast.KindBinaryExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil {
					return
				}
				if binary.OperatorToken.Kind != ast.KindPlusToken &&
					binary.OperatorToken.Kind != ast.KindPlusEqualsToken {
					return
				}

				leftType := ctx.TypeChecker.GetTypeAtLocation(binary.Left)
				rightType := ctx.TypeChecker.GetTypeAtLocation(binary.Right)
				if leftType == nil || rightType == nil {
					return
				}

				if type_checking.GetTypeName(ctx.TypeChecker, leftType) == "string" {
					state.checkExpression(binary.Right, rightType)
					return
				}
				if binary.Left.Kind == ast.KindPrivateIdentifier {
					return
				}
				if type_checking.GetTypeName(ctx.TypeChecker, rightType) == "string" {
					state.checkExpression(binary.Left, leftType)
				}
			},

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				call := node.AsCallExpression()

				if state.isBuiltinStringCall(call) {
					argument := call.Arguments.Nodes[0]
					if argument.Kind != ast.KindSpreadElement {
						state.checkExpression(argument, nil)
					}
					return
				}

				callee := call.Expression
				if callee == nil || callee.Kind != ast.KindPropertyAccessExpression {
					return
				}
				access := callee.AsPropertyAccessExpression()
				name := access.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}
				receiver := access.Expression
				if receiver == nil {
					return
				}

				switch name.AsIdentifier().Text {
				case "join":

					receiverType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, receiver)
					if receiverType == nil {
						return
					}
					state.checkExpressionForArrayJoin(receiver, receiverType)
				case "toString", "toLocaleString":
					state.checkExpression(receiver, nil)
				}
			},

			ast.KindTemplateExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if node.Parent != nil && node.Parent.Kind == ast.KindTaggedTemplateExpression {
					return
				}
				for _, span := range node.AsTemplateExpression().TemplateSpans.Nodes {
					expression := span.AsTemplateSpan().Expression
					if expression != nil {
						state.checkExpression(expression, nil)
					}
				}
			},
		}
	},
}

var NoConfusingNonNullAssertion = rule.Rule{
	Name: "@typescript-eslint/no-confusing-non-null-assertion",

	NeedsTypeChecker: false,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				binaryExpression := node.AsBinaryExpression()
				if binaryExpression.OperatorToken == nil || binaryExpression.Left == nil {
					return
				}

				operatorText, isConfusing := confusingOperatorText(binaryExpression.OperatorToken.Kind)
				if !isConfusing {
					return
				}

				leftRange := rule.TokenRange(ctx.SourceFile, binaryExpression.Left)
				sourceText := ctx.SourceFile.Text()
				if leftRange.Pos() < 0 || leftRange.End() > len(sourceText) ||
					leftRange.End() <= leftRange.Pos() {
					return
				}
				leftText := sourceText[leftRange.Pos():leftRange.End()]
				if leftText[len(leftText)-1] != '!' {
					return
				}

				wrapSuggestion := rule.Suggestion{
					Message: rule.Message{
						Id: "wrapUpLeft",
						Description: "Wrap the left-hand side in parentheses to avoid confusion " +
							"with \"" + operatorText + "\" operator.",
					},
					Fixes: []rule.Fix{
						rule.ReplaceRange(core.NewTextRange(leftRange.Pos(), leftRange.Pos()), "("),
						rule.ReplaceRange(core.NewTextRange(leftRange.End(), leftRange.End()), ")"),
					},
				}

				if binaryExpression.Left.Kind != ast.KindNonNullExpression {
					ctx.ReportNodeWithSuggestions(node, buildConfusingMessage(operatorText),
						wrapSuggestion)
					return
				}

				bangRange := core.NewTextRange(leftRange.End()-1, leftRange.End())

				switch operatorText {
				case "=":
					ctx.ReportNodeWithSuggestions(node, buildConfusingMessage(operatorText),
						rule.Suggestion{
							Message: rule.Message{
								Id: "notNeedInAssign",
								Description: "Remove unnecessary non-null assertion (!) in " +
									"assignment left-hand side.",
							},
							Fixes: []rule.Fix{rule.RemoveRange(bangRange)},
						})
				case "==", "===":
					ctx.ReportNodeWithSuggestions(node, buildConfusingMessage(operatorText),
						rule.Suggestion{
							Message: rule.Message{
								Id: "notNeedInEqualTest",
								Description: "Remove unnecessary non-null assertion (!) in " +
									"equality test.",
							},
							Fixes: []rule.Fix{rule.RemoveRange(bangRange)},
						})
				default:

					ctx.ReportNodeWithSuggestions(node, buildConfusingMessage(operatorText),
						rule.Suggestion{
							Message: rule.Message{
								Id: "notNeedInOperator",
								Description: "Remove possibly unnecessary non-null assertion (!) " +
									"in the left operand of the `" + operatorText + "` operator.",
							},
							Fixes: []rule.Fix{rule.RemoveRange(bangRange)},
						}, wrapSuggestion)
				}
			},
		}
	},
}

var messageInvalidVoidExpr = rule.Message{
	Id: "invalidVoidExpr",
	Description: "Placing a void expression inside another expression is forbidden. Move it to " +
