var NoDeprecated = rule.Rule{
	Name: "@typescript-eslint/no-deprecated",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		if ctx.TypeChecker == nil {
			return nil
		}

		settings, _ := rule.OptionsAs[NoDeprecatedOptions](options)

		report := func(node *ast.Node, name string, reason string) {
			if reason != "" {
				ctx.ReportNode(node, rule.Message{
					Id:          "deprecatedWithReason",
					Description: "`" + name + "` is deprecated. " + reason,
				})
				return
			}
			ctx.ReportNode(node, rule.Message{
				Id:          "deprecated",
				Description: "`" + name + "` is deprecated.",
			})
		}

		checkIdentifier := func(node *ast.Node) {
			if isDeprecationDeclarationSite(node) || isInsideImportForDeprecation(node) {
				return
			}
			reason, found := deprecationReasonFor(ctx, node)
			if !found {
				return
			}
			if deprecationIsAllowed(ctx, node, settings) {
				return
			}
			report(node, reportedDeprecationName(node), reason)
		}

		return rule.Listeners{
			ast.KindIdentifier: func(node *ast.Node) {
				parent := node.Parent
				if parent == nil {
					return
				}
				switch parent.Kind {
				case ast.KindExportDeclaration, ast.KindNamespaceExport:
					return
				case ast.KindJsxClosingElement:

					return
				}

				if parent.Kind == ast.KindElementAccessExpression &&
					parent.AsElementAccessExpression().ArgumentExpression == node {
					return
				}
				if parent.Kind == ast.KindExportSpecifier {

					if parent.AsExportSpecifier().Name() != node {
						return
					}
					if _, tagged := deprecationOnSymbol(ctx, ctx.TypeChecker.GetSymbolAtLocation(node)); tagged {
						return
					}
				}
				checkIdentifier(node)
			},
			ast.KindPrivateIdentifier: checkIdentifier,
			ast.KindSuperKeyword:      checkIdentifier,
			ast.KindElementAccessExpression: func(node *ast.Node) {
				checkDeprecatedElementAccess(ctx, node, settings, report)
			},
		}
	},
}

var NoDupeClassMembers = rule.Rule{
	Name: "@typescript-eslint/no-dupe-class-members",

	Run: func(ctx rule.Context, options any) rule.Listeners {

		coreCheck := func(members *ast.NodeList) {
			classmembers.ForEachDuplicate(members, func(name *ast.Node, key classmembers.Key) {
				ctx.ReportNode(name, rule.Message{
					Id: "noDupeClassMembers",
					Description: fmt.Sprintf(
						"This class already declares a member named %s. The later declaration wins "+
							"silently, so the earlier one is dead code that reads as live, and "+
							"nothing in the language or at runtime tells the two apart.", key.Name),
				})
			})
		}
		coreListeners := rule.Listeners{
			ast.KindClassDeclaration: func(node *ast.Node) {
				coreCheck(node.AsClassDeclaration().Members)
			},
			ast.KindClassExpression: func(node *ast.Node) {
				coreCheck(node.AsClassExpression().Members)
			},
		}

		filtered := func(coreListener func(*ast.Node), setMembers func(*ast.Node, *ast.NodeList) func()) func(*ast.Node) {
			return func(node *ast.Node) {
				restore := setMembers(node, nil)
				if restore == nil {

					coreListener(node)
					return
				}
				coreListener(node)
				restore()
			}
		}

		return rule.Listeners{
			ast.KindClassDeclaration: filtered(
				coreListeners[ast.KindClassDeclaration],
				func(node *ast.Node, _ *ast.NodeList) func() {
					declaration := node.AsClassDeclaration()
					return swapOutComputedClassMembers(&declaration.Members)
				},
			),
			ast.KindClassExpression: filtered(
				coreListeners[ast.KindClassExpression],
				func(node *ast.Node, _ *ast.NodeList) func() {
					expression := node.AsClassExpression()
					return swapOutComputedClassMembers(&expression.Members)
				},
			),
		}
	},
}

var NoDuplicateEnumValues = rule.Rule{

	Name: "@typescript-eslint/no-duplicate-enum-values",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindEnumDeclaration: func(node *ast.Node) {
				declaration := node.AsEnumDeclaration()
				if declaration == nil || declaration.Members == nil {
					return
				}

				seenNumbers := make(map[string]*ast.Node)
				seenStrings := make(map[string]*ast.Node)

				for _, member := range declaration.Members.Nodes {
					enumMember := member.AsEnumMember()
					if enumMember == nil {
						return
					}
					initializer := enumMember.Initializer
					if initializer == nil {
						continue
					}

					switch initializer.Kind {
					case ast.KindNumericLiteral:
						text := initializer.AsNumericLiteral().Text
						if earlier, duplicated := seenNumbers[text]; duplicated {
							ctx.ReportNode(earlier, messageNoDuplicateEnumValues)

							continue
						}
						seenNumbers[text] = initializer

					case ast.KindStringLiteral:
						text := initializer.AsStringLiteral().Text
						if earlier, duplicated := seenStrings[text]; duplicated {
							ctx.ReportNode(earlier, messageNoDuplicateEnumValues)
						}

						seenStrings[text] = initializer
					}
				}
			},
		}
	},
}

var NoDuplicateTypeConstituents = rule.Rule{
	Name: "@typescript-eslint/no-duplicate-type-constituents",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[NoDuplicateTypeConstituentsOptions](options)
		if !isSettings {
			settings = DefaultNoDuplicateTypeConstituentsSettings()
		}

		textOf := func(node *ast.Node) string {
			inner := node
			for inner.Kind == ast.KindParenthesizedType {
				next := inner.AsParenthesizedTypeNode().Type
				if next == nil {
					break
				}
				inner = next
			}
			nodeRange := rule.TokenRange(ctx.SourceFile, inner)
			return ctx.SourceFile.Text()[nodeRange.Pos():nodeRange.End()]
		}

		report := func(message rule.Message, constituent *ast.Node, parent *ast.Node) {
			constituentRange := rule.TokenRange(ctx.SourceFile, constituent)

			spanStart := constituentRange.Pos()
			for inner := constituent; inner.Kind == ast.KindParenthesizedType; {
				next := inner.AsParenthesizedTypeNode().Type
				if next == nil {
					break
				}
				spanStart = rule.TokenRange(ctx.SourceFile, next).Pos()
				inner = next
			}
			parentRange := rule.TokenRange(ctx.SourceFile, parent)
			text := ctx.SourceFile.Text()

			separatorBefore, hasSeparatorBefore := lastSeparatorBefore(text, parentRange.Pos(), constituentRange.Pos())

			closeEnd := constituentRange.End()

			fixes := []rule.Fix{}
			if hasSeparatorBefore {

				fixes = append(fixes,
					rule.RemoveRange(core.NewTextRange(separatorBefore, separatorBefore+1)),
					rule.RemoveRange(core.NewTextRange(constituentRange.Pos(), closeEnd)))
			} else {

				fixes = append(fixes,
					rule.RemoveRange(core.NewTextRange(constituentRange.Pos(), closeEnd)))
				if separatorAfter, hasSeparatorAfter := firstSeparatorAfter(text, closeEnd, parentRange.End()); hasSeparatorAfter {
					fixes = append(fixes,
						rule.RemoveRange(core.NewTextRange(separatorAfter, separatorAfter+1)))
				}
			}

			ctx.ReportRangeWithFixes(
				core.NewTextRange(spanStart, closeEnd),
				message,
				fixes...,
			)
		}

		var checkOne func(node *ast.Node, parent *ast.Node, wantKind ast.Kind,
			seenText map[string]*ast.Node, seenType map[*checker.Type]*ast.Node,
			onNewConstituent func(*checker.Type, *ast.Node, *ast.Node))

		checkOne = func(constituent *ast.Node, parent *ast.Node, wantKind ast.Kind,
			seenText map[string]*ast.Node, seenType map[*checker.Type]*ast.Node,
			onNewConstituent func(*checker.Type, *ast.Node, *ast.Node)) {

			text := textOf(constituent)
			if previous, isDuplicate := seenText[text]; isDuplicate {
				report(buildDuplicateConstituentMessage(kindWord(wantKind), textOf(previous)), constituent, parent)
				return
			}

			constituentType := ctx.TypeChecker.GetTypeAtLocation(constituent)
			if constituentType == nil {
				return
			}

			if type_checking.IsIntrinsicErrorType(constituentType) {
				return
			}

			if previous, isDuplicate := seenType[constituentType]; isDuplicate {
				report(buildDuplicateConstituentMessage(kindWord(wantKind), textOf(previous)), constituent, parent)
				return
			}

			if onNewConstituent != nil {
				onNewConstituent(constituentType, constituent, parent)
			}
			seenType[constituentType] = constituent
			seenText[text] = constituent

			inner := constituent
			for inner.Kind == ast.KindParenthesizedType {
				next := inner.AsParenthesizedTypeNode().Type
				if next == nil {
					return
				}
				inner = next
			}
			if inner.Kind != wantKind {
				return
			}
			for _, nested := range constituentsOf(inner) {
				checkOne(nested, inner, wantKind, seenText, seenType, onNewConstituent)
			}
		}

		check := func(node *ast.Node, wantKind ast.Kind,
			onNewConstituent func(*checker.Type, *ast.Node, *ast.Node)) {
			seenText := map[string]*ast.Node{}
			seenType := map[*checker.Type]*ast.Node{}
			for _, constituent := range constituentsOf(node) {
				checkOne(constituent, node, wantKind, seenText, seenType, onNewConstituent)
			}
		}

		return rule.Listeners{
			ast.KindIntersectionType: func(node *ast.Node) {
				if ctx.TypeChecker == nil || settings.IgnoreIntersections {
					return
				}

				if isNestedInSameKind(node, ast.KindIntersectionType) {
					return
				}
				check(node, ast.KindIntersectionType, nil)
			},

			ast.KindUnionType: func(node *ast.Node) {
				if ctx.TypeChecker == nil || settings.IgnoreUnions {
					return
				}
				if isNestedInSameKind(node, ast.KindUnionType) {
					return
				}

				check(node, ast.KindUnionType, func(constituentType *checker.Type, constituent *ast.Node, parent *ast.Node) {

					if !type_checking.IsTypeFlagSet(constituentType, checker.TypeFlagsUndefined) {
						return
					}
					if !isOptionalParameterType(node) {
						return
					}
					report(buildUnnecessaryUndefinedMessage(), constituent, parent)
				})
			},
		}
	},
}

var NoDynamicDelete = rule.Rule{
	Name: "@typescript-eslint/no-dynamic-delete",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindDeleteExpression: func(node *ast.Node) {

				operand := ast.SkipParentheses(node.AsDeleteExpression().Expression)

				if !ast.IsElementAccessExpression(operand) {
					return
				}
				elementAccess := operand.AsElementAccessExpression()

				if elementAccess.QuestionDotToken != nil {
					return
				}

				key := ast.SkipParentheses(elementAccess.ArgumentExpression)
				if isAcceptableDeleteIndexExpression(key) {
					return
				}

				ctx.ReportNode(key, buildDynamicDeleteMessage())
			},
		}
	},
}

var NoEmptyObjectType = rule.Rule{
	Name: "@typescript-eslint/no-empty-object-type",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[NoEmptyObjectTypeOptions](options)
		if !ok {
			settings = DefaultNoEmptyObjectTypeOptions()
		}

		listeners := rule.Listeners{}
		if settings.AllowInterfaces != "always" {
			listeners[ast.KindInterfaceDeclaration] = func(node *ast.Node) {
				checkEmptyInterface(ctx, settings, node)
			}
		}
		if settings.AllowObjectTypes != "always" {
			listeners[ast.KindTypeLiteral] = func(node *ast.Node) {
				checkEmptyTypeLiteral(ctx, settings, node)
			}
		}
		return listeners
	},
}

var NoExplicitAny = rule.Rule{
	Name: "@typescript-eslint/no-explicit-any",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		if !isTypeScriptSourceFile(ctx.SourceFile.FileName().AsString()) {
			return nil
		}

		parsed, _ := rule.OptionsAs[NoExplicitAnyOptions](options)

		return rule.Listeners{
			ast.KindAnyKeyword: func(node *ast.Node) {
				if parsed.IgnoreRestArgs && isInsideRestParameter(node) {
					return
				}

				if parsed.FixToUnknown {
					ctx.ReportNodeWithFixes(node, messageNoExplicitAny,
						rule.ReplaceRange(rule.TokenRange(ctx.SourceFile, node), "unknown"))
					return
				}

				ctx.ReportNode(node, messageNoExplicitAny)
			},
		}
	},
}

var NoExtraNonNullAssertion = rule.Rule{
	Name: "@typescript-eslint/no-extra-non-null-assertion",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindNonNullExpression: func(node *ast.Node) {

				outermost := outermostParenthesizedExpression(node)
				if outermost == nil {
					return
				}
				parent := outermost.Parent
				if parent == nil {
					return
				}

				if parent.Kind == ast.KindNonNullExpression {
					reportRedundantAssertion(ctx, node)
					return
				}

				switch parent.Kind {
				case ast.KindPropertyAccessExpression,
					ast.KindElementAccessExpression,
					ast.KindCallExpression:
					if ast.IsOptionalChainRoot(parent) && parent.Expression() == outermost {
						reportRedundantAssertion(ctx, node)
					}
				}
			},
		}
	},
}

var NoExtraneousClass = rule.Rule{
	Name: "@typescript-eslint/no-extraneous-class",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[NoExtraneousClassOptions](options)
		if !isSettings {
			settings = DefaultNoExtraneousClassSettings()
		}

		judge := func(node *ast.Node, name *ast.Node, members *ast.NodeList, heritageClauses *ast.NodeList) {
			if members == nil {
				return
			}

			if hasSuperclass(heritageClauses) {
				return
			}
			if settings.AllowWithDecorator && hasDecorator(node) {
				return
			}

			reportRange := classAnchorRange(ctx, node)
			if node.Kind == ast.KindClassDeclaration && name != nil {
				reportRange = rule.TokenRange(ctx.SourceFile, name)
			}

			if len(members.Nodes) == 0 {
				if settings.AllowEmpty {
					return
				}
				if noExtraneousClassEmptyClassIsLoadBearing(ctx, node, name) {
					return
				}
				ctx.ReportRange(reportRange, noExtraneousClassEmptyMessage)
				return
			}

			onlyStatic := true
			onlyConstructor := true
			for _, member := range members.Nodes {
				if member.Kind == ast.KindConstructor {

					if constructorDeclaresParameterProperty(member) {
						onlyConstructor = false
						onlyStatic = false
					}
				} else {
					onlyConstructor = false
					if isInstanceLevelClassMember(member) {
						onlyStatic = false
					}
				}

				if !onlyStatic && !onlyConstructor {
					break
				}
			}

			if onlyConstructor {
				if !settings.AllowConstructorOnly {
					ctx.ReportRange(reportRange, noExtraneousClassOnlyConstructorMessage)
				}
				return
			}
			if onlyStatic && !settings.AllowStaticOnly {
				ctx.ReportRange(reportRange, noExtraneousClassOnlyStaticMessage)
			}
		}

		return rule.Listeners{
			ast.KindClassDeclaration: func(node *ast.Node) {
				declaration := node.AsClassDeclaration()
				judge(node, declaration.Name(), declaration.Members, declaration.HeritageClauses)
			},
			ast.KindClassExpression: func(node *ast.Node) {
				expression := node.AsClassExpression()
				judge(node, expression.Name(), expression.Members, expression.HeritageClauses)
			},
		}
	},
}

var noExtraneousClassEmptyMessage = rule.Message{
	Id:          "empty",
	Description: "Unexpected empty class.",
}

var noExtraneousClassOnlyConstructorMessage = rule.Message{
	Id:          "onlyConstructor",
	Description: "Unexpected class with only a constructor.",
}

var noExtraneousClassOnlyStaticMessage = rule.Message{
	Id:          "onlyStatic",
	Description: "Unexpected class with only static properties.",
}

var NoFloatingPromises = rule.Rule{
	Name: "@typescript-eslint/no-floating-promises",

	NeedsTypeChecker: true,

	TypeReach: rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		opts, ok := rule.OptionsAs[NoFloatingPromisesOptions](options)
		if !ok {
			opts = NoFloatingPromisesOptions{
				AllowForKnownSafeCalls:          []type_checking.TypeOrValueSpecifier{},
				AllowForKnownSafeCallsInline:    []string{},
				AllowForKnownSafePromises:       []type_checking.TypeOrValueSpecifier{},
				AllowForKnownSafePromisesInline: []string{},
			}
		}
		if opts.CheckThenables == nil {
			opts.CheckThenables = type_checking.Ref(false)
		}
		if opts.IgnoreIIFE == nil {
			opts.IgnoreIIFE = type_checking.Ref(false)
		}
		if opts.IgnoreVoid == nil {
			opts.IgnoreVoid = type_checking.Ref(true)
		}

		isHigherPrecedenceThanUnary := func(node *ast.Node) bool {
			operator := ast.KindUnknown
			if ast.IsBinaryExpression(node) {
				operator = node.AsBinaryExpression().OperatorToken.Kind
			}
			nodePrecedence := ast.GetOperatorPrecedence(node.Kind, operator, ast.OperatorPrecedenceFlagsNone)
			return nodePrecedence > ast.OperatorPrecedenceUnary
		}

		addAwait := func(
			expression *ast.Expression,
			node *ast.ExpressionStatement,
		) []rule.Fix {
			if ast.IsVoidExpression(expression) {
				voidTokenRange := scanner.GetRangeOfTokenAtPosition(ctx.SourceFile, expression.Pos())
				return []rule.Fix{rule.ReplaceRange(voidTokenRange, "await")}
			}
			if isHigherPrecedenceThanUnary(node.Expression) {
				return []rule.Fix{ctx.InsertBefore(&node.Node, "await ")}
			}
			return []rule.Fix{
				ctx.InsertBefore(&node.Node, "await ("),
				ctx.InsertAfter(expression, ")"),
			}
		}

		hasMatchingSignature := func(
			t *checker.Type,
			matcher func(signature *checker.Signature) bool,
		) bool {
			for part := range type_checking.UnionTypePartsSeq(t) {
				if type_checking.Some(type_checking.GetCallSignatures(ctx.TypeChecker, part), matcher) {
					return true
				}
			}

			return false
		}

		isFunctionParam := func(
			param *ast.Symbol,
			node *ast.Node,
		) bool {
			t := checker.Checker_getApparentType(ctx.TypeChecker, ctx.TypeChecker.GetTypeOfSymbolAtLocation(param, node))

			for part := range type_checking.UnionTypePartsSeq(t) {
				if len(type_checking.GetCallSignatures(ctx.TypeChecker, part)) != 0 {
					return true
				}
			}
			return false
		}

		isPromiseLike := func(node *ast.Node, t *checker.Type) bool {
			if t == nil {
				t = ctx.TypeChecker.GetTypeAtLocation(node)
			}

			if type_checking.TypeMatchesSomeSpecifier(
				t,
				opts.AllowForKnownSafePromises,
				opts.AllowForKnownSafePromisesInline,
				ctx.Program,
			) {
				return false
			}

			typeParts := type_checking.UnionTypeParts(checker.Checker_getApparentType(ctx.TypeChecker, t))
			if type_checking.Some(typeParts, func(typePart *checker.Type) bool {
				return type_checking.IsPromiseLike(ctx.Program, ctx.TypeChecker, typePart)
			}) {
				return true
			}

			if !*opts.CheckThenables {
				return false
			}

			for _, typePart := range typeParts {
				then := checker.Checker_getPropertyOfType(ctx.TypeChecker, typePart, "then")
				if then == nil {
					continue
				}

				thenType := ctx.TypeChecker.GetTypeOfSymbolAtLocation(then, node)
				if hasMatchingSignature(
					thenType,
					func(signature *checker.Signature) bool {
						params := checker.Signature_parameters(signature)
						return len(params) >= 2 && isFunctionParam(params[0], node) && isFunctionParam(params[1], node)
					}) {
					return true
				}
			}
			return false
		}

		isPromiseArray := func(node *ast.Node) bool {
			t := ctx.TypeChecker.GetTypeAtLocation(node)
			for typePart := range type_checking.UnionTypePartsSeq(t) {
				apparent := checker.Checker_getApparentType(ctx.TypeChecker, typePart)

				if checker.Checker_isArrayType(ctx.TypeChecker, apparent) {
					arrayType := checker.Checker_getTypeArguments(ctx.TypeChecker, apparent)[0]
					if isPromiseLike(node, arrayType) {
						return true
					}
				}

				if checker.IsTupleType(apparent) {
					for _, tupleElementType := range checker.Checker_getTypeArguments(ctx.TypeChecker, apparent) {
						if isPromiseLike(node, tupleElementType) {
							return true
						}
					}
				}
			}
			return false
		}

		isKnownSafePromiseReturn := func(node *ast.Node) bool {
			if !ast.IsCallExpression(node) {
				return false
			}

			t := ctx.TypeChecker.GetTypeAtLocation(node.AsCallExpression().Expression)

			return type_checking.TypeMatchesSomeSpecifier(
				t,
				opts.AllowForKnownSafeCalls,
				opts.AllowForKnownSafeCallsInline,
				ctx.Program,
			)
		}

		isAsyncIife := func(node *ast.ExpressionStatement) bool {
			if !ast.IsCallExpression(node.Expression) {
				return false
			}

			callee := ast.SkipParentheses(node.Expression.AsCallExpression().Expression)

			return ast.IsArrowFunction(callee) || ast.IsFunctionExpression(callee)
		}

		isValidRejectionHandler := func(rejectionHandler *ast.Node) bool {
			return len(type_checking.GetCallSignatures(ctx.TypeChecker, ctx.TypeChecker.GetTypeAtLocation(rejectionHandler))) > 0
		}

		var isUnhandledPromise func(
			node *ast.Node,
		) (
			bool,
			bool,
			bool,
		)
		isUnhandledPromise = func(
			node *ast.Node,
		) (
			bool,
			bool,
			bool,
		) {
			if ast.IsAssignmentExpression(node, false) {
				return false, false, false
			}

			if ast.IsCommaExpression(node) {
				expr := node.AsBinaryExpression()

				isUnhandled, nonFunctionHandler, promiseArray := isUnhandledPromise(expr.Left)
				if isUnhandled {
					return isUnhandled, nonFunctionHandler, promiseArray
				}
				return isUnhandledPromise(expr.Right)
			}

			if !*opts.IgnoreVoid && ast.IsVoidExpression(node) {

				return isUnhandledPromise(node.Expression())
			}

			if isPromiseArray(node) {
				return true, false, true
			}

			if ast.IsAwaitExpression(node) {

				return false, false, false
			}

			if !isPromiseLike(node, nil) {
				return false, false, false
			}

			if ast.IsCallExpression(node) {

				callExpr := node.AsCallExpression()
				callee := callExpr.Expression
				if ast.IsAccessExpression(callee) {

					methodName, _ := checker.Checker_getAccessedPropertyName(ctx.TypeChecker, callee)

					if methodName == "catch" && len(callExpr.Arguments.Nodes) >= 1 {
						if isValidRejectionHandler(callExpr.Arguments.Nodes[0]) {
							return false, false, false
						}
						return true, true, false
					}
					if methodName == "then" && len(callExpr.Arguments.Nodes) >= 2 {
						if isValidRejectionHandler(callExpr.Arguments.Nodes[1]) {
							return false, false, false
						}
						return true, true, false
					}

					if methodName == "finally" {
						return isUnhandledPromise(callee.Expression())
					}
				}

				return true, false, false
			}

			if node.Kind == ast.KindConditionalExpression {
				expr := node.AsConditionalExpression()

				isUnhandled, nonFunctionHandler, promiseArray := isUnhandledPromise(expr.WhenFalse)
				if isUnhandled {
					return isUnhandled, nonFunctionHandler, promiseArray
				}
				return isUnhandledPromise(expr.WhenTrue)
			}

			if ast.IsLogicalOrCoalescingBinaryExpression(node) {
				expr := node.AsBinaryExpression()
				isUnhandled, nonFunctionHandler, promiseArray := isUnhandledPromise(expr.Left)
				if isUnhandled {
					return isUnhandled, nonFunctionHandler, promiseArray
				}
				return isUnhandledPromise(expr.Right)
			}

			return true, false, false
		}

		return rule.Listeners{
			ast.KindExpressionStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				exprStatement := node.AsExpressionStatement()

				if *opts.IgnoreIIFE && isAsyncIife(exprStatement) {
					return
				}

				expression := ast.SkipParentheses(exprStatement.Expression)

				if isKnownSafePromiseReturn(expression) {
					return
				}

				isUnhandled, nonFunctionHandler, promiseArray := isUnhandledPromise(expression)

				if !isUnhandled {
					return
				}
				if promiseArray {
					var msg rule.Message
					if *opts.IgnoreVoid {
						msg = buildFloatingPromiseArrayVoidMessage()
					} else {
						msg = buildFloatingPromiseArrayMessage()
					}
					ctx.ReportNode(node, msg)
				} else if *opts.IgnoreVoid {
					var msg rule.Message
					if nonFunctionHandler {
						msg = buildFloatingUselessRejectionHandlerVoidMessage()
					} else {
						msg = buildFloatingVoidMessage()
					}

					ctx.ReportNodeWithSuggestions(node, msg, rule.Suggestion{
						Message: buildFloatingFixVoidMessage(),
						Fixes: (func() []rule.Fix {
							if isHigherPrecedenceThanUnary(exprStatement.Expression) {
								return []rule.Fix{ctx.InsertBefore(node, "void ")}
							}
							return []rule.Fix{
								ctx.InsertBefore(node, "void ("),
								ctx.InsertAfter(expression, ")"),
							}
						})(),
					}, rule.Suggestion{
						Message: buildFloatingFixAwaitMessage(),
						Fixes:   addAwait(expression, exprStatement),
					})
				} else {
					var msg rule.Message
					if nonFunctionHandler {
						msg = buildFloatingUselessRejectionHandlerMessage()
					} else {
						msg = buildFloatingMessage()
					}
					ctx.ReportNodeWithSuggestions(node, msg, rule.Suggestion{
						Message: buildFloatingFixAwaitMessage(),
						Fixes:   addAwait(expression, exprStatement),
					})
				}
			},
		}
	},
}

var NoForInArray = rule.Rule{

	Name: "@typescript-eslint/no-for-in-array",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		hasArrayishLength := func(t *checker.Type) bool {
			lengthProperty := checker.Checker_getPropertyOfType(ctx.TypeChecker, t, "length")
			if lengthProperty == nil {
				return false
			}

			return type_checking.IsTypeFlagSet(checker.Checker_getTypeOfSymbol(ctx.TypeChecker, lengthProperty), checker.TypeFlagsNumberLike)
		}
		isArrayLike := func(t *checker.Type) bool {
			return type_checking.TypeRecurser(t, func(t *checker.Type) bool {
				return type_checking.GetNumberIndexType(ctx.TypeChecker, t) != nil && hasArrayishLength(t)
			})
		}

		return rule.Listeners{
			ast.KindForInStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				t := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, node.AsForInOrOfStatement().Expression)

				if isArrayLike(t) {
					ctx.ReportRange(
						type_checking.GetForStatementHeadLoc(ctx.SourceFile, node),
						buildForInViolationMessage(),
					)
				}
			},
		}
	},
}

var NoImpliedEval = rule.Rule{
	Name: "@typescript-eslint/no-implied-eval",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		getCalleeName := func(node *ast.Expression) string {
			if ast.IsIdentifier(node) {
				return node.AsIdentifier().Text
			}

			if ast.IsAccessExpression(node) && ast.IsIdentifier(node.Expression()) && slices.Contains(globalCandidates, node.Expression().AsIdentifier().Text) {
				if ast.IsPropertyAccessExpression(node) {
					if ast.IsIdentifier(node.Name()) {
						return node.Name().AsIdentifier().Text
					}
				} else if ast.IsElementAccessExpression(node) {
					expr := node.AsElementAccessExpression()
					if ast.IsStringLiteral(expr.ArgumentExpression) {
						return expr.ArgumentExpression.AsStringLiteral().Text
					}
				}
			}

			return ""
		}

		isFunctionType := func(node *ast.Node) bool {
			t := ctx.TypeChecker.GetTypeAtLocation(node)
			symbol := checker.Type_symbol(t)

			if symbol != nil && type_checking.IsSymbolFlagSet(symbol, ast.SymbolFlagsFunction|ast.SymbolFlagsMethod) {
				return true
			}

			if type_checking.IsBuiltinSymbolLike(ctx.Program, ctx.TypeChecker, t, "Function") {
				return true
			}

			return len(type_checking.GetCallSignatures(ctx.TypeChecker, t)) > 0
		}

		isBind := func(node *ast.Node) bool {
			if ast.IsPropertyAccessExpression(node) {
				node = node.AsPropertyAccessExpression().Name()
			}
			return ast.IsIdentifier(node) && node.AsIdentifier().Text == "bind"
		}

		isFunction := func(node *ast.Node) bool {
			if ast.IsFunctionLike(node) {
				return true
			}
			if ast.IsLiteralExpression(node) {
				return false
			}
			if ast.IsCallExpression(node) {
				return isBind(node.AsCallExpression().Expression) || isFunctionType(node)
			}
			return isFunctionType(node)
		}

		checkImpliedEval := func(
			node *ast.Node,
		) {
			if ctx.TypeChecker == nil {
				return
			}

			calleeName := getCalleeName(node.Expression())
			if calleeName == "" {
				return
			}

			if calleeName == "Function" {
				t := ctx.TypeChecker.GetTypeAtLocation(node.Expression())
				symbol := checker.Type_symbol(t)

				if symbol != nil {
					if type_checking.IsBuiltinSymbolLike(ctx.Program, ctx.TypeChecker, t, "FunctionConstructor") {
						ctx.ReportNode(node, buildNoFunctionConstructorMessage())
						return
					}
				} else {
					ctx.ReportNode(node, buildNoFunctionConstructorMessage())
				}
			}

			if len(node.Arguments()) == 0 {
				return
			}

			handler := node.Arguments()[0]

			if slices.Contains(evalLikeFunctions, calleeName) && !isFunction(handler) {
				symbol := ctx.TypeChecker.GetSymbolAtLocation(node.Expression())
				if symbol == nil || !type_checking.Some(symbol.Declarations, func(d *ast.Node) bool {
					return ast.GetSourceFileOfNode(d) == ctx.SourceFile
				}) {
					ctx.ReportNode(handler, buildNoImpliedEvalErrorMessage())
				}
			}
		}

		return rule.Listeners{
			ast.KindCallExpression: checkImpliedEval,
			ast.KindNewExpression:  checkImpliedEval,
		}
	},
}

var NoImportTypeSideEffects = rule.Rule{
	Name: "@typescript-eslint/no-import-type-side-effects",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindImportDeclaration: func(node *ast.Node) {
				declaration := node.AsImportDeclaration()
				if declaration.ImportClause == nil {
					return
				}
				clause := declaration.ImportClause.AsImportClause()
				if clause.IsTypeOnly() {
					return
				}

				bindings := imports.BindingsOf(node)
				if bindings.Default != nil || bindings.Namespace != nil {
					return
				}
				if len(bindings.Named) == 0 {
					return
				}
				for _, element := range bindings.Named {
					if element.Kind != ast.KindImportSpecifier || !element.AsImportSpecifier().IsTypeOnly {
						return
					}
				}

				fixes := make([]rule.Fix, 0, len(bindings.Named)+1)
				for _, element := range bindings.Named {

					fixes = append(fixes, rule.RemoveRange(
						rule.TokenRange(ctx.SourceFile, element).
							WithEnd(rule.TokenRange(ctx.SourceFile, importedNameOf(element)).Pos()),
					))
				}

				importKeyword := rule.TokenRange(ctx.SourceFile, node)
				fixes = append(fixes, rule.ReplaceRange(
					importKeyword.WithEnd(importKeyword.Pos()+len("import")).
						WithPos(importKeyword.Pos()+len("import")),
					" type",
				))

				ctx.ReportNodeWithFixes(node, messageUseTopLevelQualifier, fixes...)
			},
		}
	},
}

var NoInferrableTypes = rule.Rule{
	Name: "@typescript-eslint/no-inferrable-types",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, configured := rule.OptionsAs[NoInferrableTypesOptions](options)
		if !configured {
			settings = NoInferrableTypesOptions{}
		}

		listeners := rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()
				if declaration == nil {
					return
				}
				reportNoInferrableType(ctx, node, declaration.Type, declaration.Initializer, nil)
			},
		}

		if !settings.IgnoreParameters {
			parameterVisitor := func(node *ast.Node) {
				for _, parameter := range node.Parameters() {
					checkNoInferrableTypesParameter(ctx, parameter)
				}
			}

			for _, kind := range []ast.Kind{
				ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction,
				ast.KindMethodDeclaration, ast.KindConstructor,
				ast.KindGetAccessor, ast.KindSetAccessor,
			} {
				listeners[kind] = parameterVisitor
			}
		}

		if !settings.IgnoreProperties {
			listeners[ast.KindPropertyDeclaration] = func(node *ast.Node) {
				checkNoInferrableTypesProperty(ctx, node)
			}
		}

		return listeners
	},
}

var NoInvalidThis = rule.Rule{
	Name: "@typescript-eslint/no-invalid-this",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings := noInvalidThisSettingsFrom(options)

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {

				walker := &noInvalidThisWalker{ctx: ctx, settings: settings}
				walker.walk(node)
			},
		}
	},
}

var thisArgMethodNames = map[string]struct{}{
	"every": {}, "filter": {}, "find": {}, "findIndex": {}, "findLast": {},
	"findLastIndex": {}, "flatMap": {}, "forEach": {}, "map": {}, "some": {},
