var NoUnsafeArgument = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-argument",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()
				if call.Expression == nil || call.Arguments == nil {
					return
				}
				checkUnsafeArguments(ctx, call.Arguments.Nodes, call.Expression, node, false)
			},
			ast.KindNewExpression: func(node *ast.Node) {
				newExpression := node.AsNewExpression()
				if newExpression.Expression == nil || newExpression.Arguments == nil {
					return
				}
				checkUnsafeArguments(ctx, newExpression.Arguments.Nodes, newExpression.Expression,
					node, false)
			},
			ast.KindTaggedTemplateExpression: func(node *ast.Node) {
				tagged := node.AsTaggedTemplateExpression()
				if tagged.Tag == nil || tagged.Template == nil {
					return
				}

				if tagged.Template.Kind != ast.KindTemplateExpression {
					return
				}
				spans := tagged.Template.AsTemplateExpression().TemplateSpans
				if spans == nil {
					return
				}
				expressions := make([]*ast.Node, 0, len(spans.Nodes))
				for _, span := range spans.Nodes {
					expression := span.AsTemplateSpan().Expression
					if expression != nil {
						expressions = append(expressions, expression)
					}
				}
				checkUnsafeArguments(ctx, expressions, tagged.Tag, node, true)
			},
		}
	},
}

var NoUnsafeAssignment = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-assignment",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{

			ast.KindVariableDeclaration: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				declaration := node.AsVariableDeclaration()
				initializer := declaration.Initializer
				if initializer == nil {
					return
				}
				name := declaration.Name()
				if name == nil {
					return
				}
				noUnsafeAssignmentCheckWithDestructuring(ctx, name, initializer, node,
					noUnsafeAssignmentComparisonFor(declaration.Type))
			},

			ast.KindBinaryExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil || binary.OperatorToken.Kind != ast.KindEqualsToken {
					return
				}
				if binary.Left == nil || binary.Right == nil {
					return
				}

				noUnsafeAssignmentCheckWithDestructuring(ctx, binary.Left, binary.Right, node,
					noUnsafeAssignmentComparisonBasic)
			},

			ast.KindPropertyDeclaration: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				property := node.AsPropertyDeclaration()
				if property.Initializer == nil {
					return
				}
				name := property.Name()
				if name == nil {
					return
				}
				noUnsafeAssignmentCheck(ctx, name, property.Initializer, node,
					noUnsafeAssignmentComparisonFor(property.Type))
			},

			ast.KindPropertyAssignment: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if noUnsafeAssignmentIsDestructuringTarget(node.Parent) {
					return
				}
				assignment := node.AsPropertyAssignment()
				name := assignment.Name()
				value := assignment.Initializer
				if name == nil || value == nil {
					return
				}

				if value.Kind == ast.KindFunctionExpression &&
					value.AsFunctionExpression().Body == nil {
					return
				}
				noUnsafeAssignmentCheck(ctx, name, value, node,
					noUnsafeAssignmentComparisonContextual)
			},

			ast.KindShorthandPropertyAssignment: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if noUnsafeAssignmentIsDestructuringTarget(node.Parent) {
					return
				}
				shorthand := node.AsShorthandPropertyAssignment()

				if shorthand.ObjectAssignmentInitializer != nil {
					return
				}
				name := shorthand.Name()
				if name == nil {
					return
				}
				noUnsafeAssignmentCheck(ctx, name, name, node,
					noUnsafeAssignmentComparisonContextual)
			},

			ast.KindSpreadElement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				if node.Parent == nil || node.Parent.Kind != ast.KindArrayLiteralExpression {
					return
				}
				argument := node.AsSpreadElement().Expression
				if argument == nil {
					return
				}
				restType := ctx.TypeChecker.GetTypeAtLocation(argument)
				if restType == nil {
					return
				}
				if type_checking.IsTypeAnyType(restType) ||
					noUnsafeAssignmentIsAnyArray(ctx, restType) {
					ctx.ReportNode(node, messageNoUnsafeAssignmentArraySpread(
						noUnsafeAssignmentSenderText(ctx, restType)))
				}
			},

			ast.KindJsxAttribute: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				attribute := node.AsJsxAttribute()
				value := attribute.Initializer
				if value == nil || value.Kind != ast.KindJsxExpression {
					return
				}
				expression := value.AsJsxExpression().Expression
				if expression == nil {

					return
				}
				name := attribute.Name()
				if name == nil {
					return
				}
				noUnsafeAssignmentCheck(ctx, name, expression, expression,
					noUnsafeAssignmentComparisonContextual)
			},

			ast.KindParameter: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				parameter := node.AsParameterDeclaration()
				if parameter.Initializer == nil {
					return
				}
				name := parameter.Name()
				if name == nil {
					return
				}

				reportRange := rule.TokenRange(ctx.SourceFile, node)
				if modifiers := node.Modifiers(); modifiers != nil && len(modifiers.Nodes) > 0 {
					reportRange = rule.TokenRange(ctx.SourceFile, name).
						WithEnd(parameter.Initializer.End())
				}
				noUnsafeAssignmentCheckWithDestructuringAtRange(ctx, name, parameter.Initializer,
					reportRange, noUnsafeAssignmentComparisonBasic)
			},

			ast.KindBindingElement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				element := node.AsBindingElement()
				if element.Initializer == nil {
					return
				}
				name := element.Name()
				if name == nil {
					return
				}
				noUnsafeAssignmentCheckWithDestructuring(ctx, name, element.Initializer, node,
					noUnsafeAssignmentComparisonBasic)
			},
		}
	},
}

var NoUnsafeCall = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-call",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		checkCall := func(subject *ast.Node, reportOn *ast.Node, unsafeId string, errorId string) {
			if ctx.TypeChecker == nil {
				return
			}

			subjectType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, subject)
			if subjectType == nil {
				return
			}

			if type_checking.IsTypeAnyType(subjectType) {

				if !type_checking.IsStrictCompilerOptionEnabled(
					ctx.Program.Options(), ctx.Program.Options().NoImplicitThis) {

					thisExpression := type_checking.GetThisExpression(subject)
					if thisExpression != nil {
						thisType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, thisExpression)
						if thisType != nil && type_checking.IsTypeAnyType(thisType) {
							unsafeId = "unsafeCallThis"
							errorId = "errorCallThis"
						}
					}
				}

				if type_checking.IsIntrinsicErrorType(subjectType) {
					ctx.ReportNode(reportOn, unsafeCallMessageFor(errorId, ""))
					return
				}
				ctx.ReportNode(reportOn, unsafeCallMessageFor(unsafeId, "an `any`"))
				return
			}

			if !type_checking.IsBuiltinSymbolLike(ctx.Program, ctx.TypeChecker, subjectType, "Function") {
				return
			}

			if len(type_checking.GetConstructSignatures(ctx.TypeChecker, subjectType)) > 0 {
				return
			}

			callSignatures := type_checking.GetCallSignatures(ctx.TypeChecker, subjectType)
			if unsafeId == "unsafeNew" {
				for _, signature := range callSignatures {
					returnType := checker.Checker_getReturnTypeOfSignature(ctx.TypeChecker, signature)
					if returnType != nil && !type_checking.IsIntrinsicVoidType(returnType) {
						return
					}
				}
			} else if len(callSignatures) > 0 {
				return
			}

			ctx.ReportNode(reportOn, unsafeCallMessageFor(unsafeId, "a `Function`"))
		}

		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				call := node.AsCallExpression()
				if call.Expression == nil {
					return
				}

				if call.Expression.Kind == ast.KindImportKeyword {
					return
				}

				checkCall(skipCalleeParentheses(call.Expression), skipCalleeParentheses(call.Expression),
					"unsafeCall", "errorCall")
			},
			ast.KindNewExpression: func(node *ast.Node) {
				newExpression := node.AsNewExpression()
				if newExpression.Expression == nil {
					return
				}

				checkCall(skipCalleeParentheses(newExpression.Expression), node, "unsafeNew", "errorNew")
			},
			ast.KindTaggedTemplateExpression: func(node *ast.Node) {
				tagged := node.AsTaggedTemplateExpression()
				if tagged.Tag == nil {
					return
				}
				checkCall(skipCalleeParentheses(tagged.Tag), skipCalleeParentheses(tagged.Tag),
					"unsafeTemplateTag", "errorTemplateTag")
			},
		}
	},
}

var NoUnsafeDeclarationMerging = rule.Rule{
	Name:             "@typescript-eslint/no-unsafe-declaration-merging",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		report := func(node *ast.Node, opposite ast.Kind) {

			if ctx.TypeChecker == nil {
				return
			}
			name := node.Name()

			if name == nil {
				return
			}
			symbol := ctx.TypeChecker.GetSymbolAtLocation(name)
			if symbol == nil {
				return
			}

			declarations := symbol.Declarations
			if local := node.LocalSymbol(); local != nil && len(local.Declarations) > len(declarations) {
				declarations = local.Declarations
			}

			earliest := earliestDeclaration(declarations)
			if earliest == nil || earliest.Kind != opposite {
				return
			}

			ctx.ReportNode(earliest.Name(), messageUnsafeDeclarationMerging)
		}

		return rule.Listeners{
			ast.KindClassDeclaration: func(node *ast.Node) {
				report(node, ast.KindInterfaceDeclaration)
			},
			ast.KindInterfaceDeclaration: func(node *ast.Node) {
				report(node, ast.KindClassDeclaration)
			},
		}
	},
}

