			"matching the moment the enum's value changes, and nothing reports it: the switch simply " +
			"falls through. Compare against the enum member instead, which also lets exhaustiveness " +
			"checking see the case.",
	}
)

var NoUnsafeEnumComparison = rule.Rule{
	Name:             "@typescript-eslint/no-unsafe-enum-comparison",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {

		if ctx.TypeChecker == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindBinaryExpression: func(node *ast.Node) {
				expression := node.AsBinaryExpression()
				if expression == nil || expression.OperatorToken == nil {
					return
				}

				if !noUnsafeEnumComparisonIsComparisonOperator(expression.OperatorToken.Kind) {
					return
				}
				leftType := ctx.TypeChecker.GetTypeAtLocation(expression.Left)
				rightType := ctx.TypeChecker.GetTypeAtLocation(expression.Right)
				if noUnsafeEnumComparisonIsMismatched(ctx.TypeChecker, leftType, rightType) {
					ctx.ReportNode(node, messageNoUnsafeEnumComparisonMismatchedCondition)
				}
			},

			ast.KindCaseClause: func(node *ast.Node) {
				clause := node.AsCaseOrDefaultClause()

				if clause == nil || clause.Expression == nil {
					return
				}
				switchStatement := noUnsafeEnumComparisonEnclosingSwitch(node)
				if switchStatement == nil {
					return
				}
				leftType := ctx.TypeChecker.GetTypeAtLocation(switchStatement.Expression)
				rightType := ctx.TypeChecker.GetTypeAtLocation(clause.Expression)
				if noUnsafeEnumComparisonIsMismatched(ctx.TypeChecker, leftType, rightType) {
					ctx.ReportNode(node, messageNoUnsafeEnumComparisonMismatchedCase)
				}
			},
		}
	},
}

var NoUnsafeFunctionType = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-function-type",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		if module.DeclaresTypeNamed(ctx.SourceFile, "Function") {
			return nil
		}

		report := func(node *ast.Node) {
			if node == nil || node.Kind != ast.KindIdentifier || node.Text() != "Function" {
				return
			}
			ctx.ReportNode(node, messageBannedFunctionType)
		}

		return rule.Listeners{
			ast.KindTypeReference: func(node *ast.Node) {
				typeReference := node.AsTypeReferenceNode()
				if typeReference == nil {
					return
				}
				report(typeReference.TypeName)
			},
		}
	},
}

var NoUnsafeMemberAccess = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-member-access",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[NoUnsafeMemberAccessOptions](options)
		if !ok {

			settings = DefaultNoUnsafeMemberAccessOptions()
		}

		stateCache := map[*ast.Node]noUnsafeMemberAccessState{}

		var checkMemberAccess func(node *ast.Node) noUnsafeMemberAccessState

		checkMemberAccessInside := func(expression *ast.Node) {
			switch expression.Kind {
			case ast.KindPropertyAccessExpression, ast.KindElementAccessExpression:
				checkMemberAccess(expression)
			case ast.KindCallExpression:
				callee := expression.AsCallExpression().Expression
				if callee != nil {
					switch callee.Kind {
					case ast.KindPropertyAccessExpression, ast.KindElementAccessExpression:
						checkMemberAccess(callee)
					}
				}
			}
		}

		checkMemberAccess = func(node *ast.Node) noUnsafeMemberAccessState {
			objectExpression, propertyNode, isComputed, hasQuestionDot :=
				noUnsafeMemberAccessParts(node)
			if objectExpression == nil || propertyNode == nil {
				return noUnsafeMemberAccessSafe
			}

			if cached, seen := stateCache[node]; seen {
				return cached
			}

			if settings.AllowOptionalChaining && hasQuestionDot {
				checkMemberAccessInside(objectExpression)
				stateCache[node] = noUnsafeMemberAccessChained
				return noUnsafeMemberAccessChained
			}

			if objectExpression.Kind == ast.KindCallExpression {
				checkMemberAccessInside(objectExpression)
			}

			if objectExpression.Kind == ast.KindPropertyAccessExpression ||
				objectExpression.Kind == ast.KindElementAccessExpression {

				if checkMemberAccess(objectExpression) == noUnsafeMemberAccessUnsafe {

					stateCache[node] = noUnsafeMemberAccessUnsafe
					return noUnsafeMemberAccessUnsafe
				}
			}

			objectType := ctx.TypeChecker.GetTypeAtLocation(objectExpression)
			state := noUnsafeMemberAccessSafe
			if objectType != nil && type_checking.IsTypeAnyType(objectType) {
				state = noUnsafeMemberAccessUnsafe
			}
			stateCache[node] = state
			if state != noUnsafeMemberAccessUnsafe {
				return state
			}

			propertyText := noUnsafeMemberAccessText(ctx, propertyNode)
			rendered := "." + propertyText
			if isComputed {
				rendered = "[" + propertyText + "]"
			}

			messageId := ""
			if !type_checking.IsStrictCompilerOptionEnabled(
				ctx.Program.Options(), ctx.Program.Options().NoImplicitThis) {

				thisExpression := type_checking.GetThisExpression(node)
				if thisExpression != nil {
					thisType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, thisExpression)
					if thisType != nil && type_checking.IsTypeAnyType(thisType) {
						messageId = "unsafeThisMemberExpression"
						if type_checking.IsIntrinsicErrorType(thisType) {
							messageId = "errorThisMemberExpression"
						}
					}
				}
			}
			if messageId == "" {
				messageId = "unsafeMemberExpression"
				if type_checking.IsIntrinsicErrorType(objectType) {

					messageId = "errorMemberExpression"
				}
			}

			ctx.ReportNode(propertyNode, noUnsafeMemberAccessMessageFor(messageId, rendered))
			return state
		}

		checkComputedKey := func(node *ast.Node) {
			access := node.AsElementAccessExpression()
			key := access.ArgumentExpression
			if key == nil {
				return
			}
			if settings.AllowOptionalChaining && access.QuestionDotToken != nil {
				return
			}

			switch noUnsafeMemberAccessUnwrapParentheses(key).Kind {
			case ast.KindNumericLiteral, ast.KindStringLiteral, ast.KindBigIntLiteral,
				ast.KindNoSubstitutionTemplateLiteral, ast.KindRegularExpressionLiteral,
				ast.KindTrueKeyword, ast.KindFalseKeyword, ast.KindNullKeyword,
				ast.KindPrefixUnaryExpression, ast.KindPostfixUnaryExpression:

				return
			}

			key = noUnsafeMemberAccessUnwrapParentheses(key)
			if key == nil {
				return
			}

			keyType := ctx.TypeChecker.GetTypeAtLocation(key)
			if keyType == nil || !type_checking.IsTypeAnyType(keyType) {
				return
			}
			messageId := "unsafeComputedMemberAccess"
			if type_checking.IsIntrinsicErrorType(keyType) {
				messageId = "errorComputedMemberAccess"
			}
			ctx.ReportNode(key, noUnsafeMemberAccessMessageFor(messageId,
				"["+noUnsafeMemberAccessText(ctx, key)+"]"))
		}

		if ctx.TypeChecker == nil {
			return rule.Listeners{}
		}

		return rule.Listeners{
			ast.KindPropertyAccessExpression: func(node *ast.Node) {
				checkMemberAccess(node)
			},
			ast.KindElementAccessExpression: func(node *ast.Node) {
				checkMemberAccess(node)
				checkComputedKey(node)
			},
		}
	},
}

var NoUnsafeReturn = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-return",

	NeedsTypeChecker: true,

	ProgramReads: rule.ReadsCompilerOptions,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindReturnStatement: func(node *ast.Node) {
				argument := node.AsReturnStatement().Expression
				if argument == nil {
					return
				}

				checkUnsafeReturn(ctx, argument, node)
			},
			ast.KindArrowFunction: func(node *ast.Node) {
				body := node.AsArrowFunction().Body
				if body == nil || body.Kind == ast.KindBlock {

					return
				}
				checkUnsafeReturn(ctx, body, body)
			},
		}
	},
}

var NoUnsafeTypeAssertion = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-type-assertion",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		checkAssertion := func(node *ast.Node, expression *ast.Node, assertedTypeNode *ast.Node) {
			if ctx.TypeChecker == nil {
				return
			}
			if expression == nil || assertedTypeNode == nil {
				return
			}

			expressionType := ctx.TypeChecker.GetTypeAtLocation(expression)
			assertedType := ctx.TypeChecker.GetTypeAtLocation(assertedTypeNode)
			if expressionType == nil || assertedType == nil {
				return
			}

			if expressionType == assertedType {
				return
			}

			if type_checking.IsTypeAnyType(assertedType) &&
				type_checking.IsTypeUnknownType(expressionType) {
				ctx.ReportNode(node, buildUnsafeToAnyMessage("`any`"))
				return
			}

			if _, sender, isUnsafe := type_checking.IsUnsafeAssignment(expressionType, assertedType,
				ctx.TypeChecker, expression); isUnsafe {
				ctx.ReportNode(node, buildUnsafeOfAnyMessage(anyTypeName(sender)))
				return
			}

			if _, sender, isUnsafe := type_checking.IsUnsafeAssignment(assertedType, expressionType,
				ctx.TypeChecker, assertedTypeNode); isUnsafe {
				ctx.ReportNode(node, buildUnsafeToAnyMessage(anyTypeName(sender)))
				return
			}

			expressionWidenedType := expressionType
			if isObjectLiteralType(expressionType) {
				expressionWidenedType = checker.Checker_getWidenedType(ctx.TypeChecker, expressionType)
			}

			if checker.Checker_isTypeAssignableTo(ctx.TypeChecker, expressionWidenedType, assertedType) {
				return
			}

			if type_checking.IsTypeParameter(assertedType) {
				constraint := checker.Checker_getBaseConstraintOfType(ctx.TypeChecker, assertedType)
				if constraint == nil {
					ctx.ReportNode(node, buildUnsafeToUnconstrainedMessage(
						ctx.TypeChecker.TypeToString(assertedType)))
					return
				}

				if checker.Checker_isTypeAssignableTo(ctx.TypeChecker, expressionWidenedType, constraint) {
					ctx.ReportNode(node, buildUnsafeAssignableToConstraintMessage(
						ctx.TypeChecker.TypeToString(assertedType)))
					return
				}
			}

			ctx.ReportNode(node, buildUnsafeTypeAssertionMessage(
				ctx.TypeChecker.TypeToString(assertedType)))
		}

		return rule.Listeners{
			ast.KindAsExpression: func(node *ast.Node) {
				expression := node.AsAsExpression()
				checkAssertion(node, expression.Expression, expression.Type)
			},
			ast.KindTypeAssertionExpression: func(node *ast.Node) {
				expression := node.AsTypeAssertion()
				checkAssertion(node, expression.Expression, expression.Type)
			},
		}
	},
}

var NoUnsafeUnaryMinus = rule.Rule{
	Name: "@typescript-eslint/no-unsafe-unary-minus",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindPrefixUnaryExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				expr := node.AsPrefixUnaryExpression()

				if expr.Operator != ast.KindMinusToken {
					return
				}

				argType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, expr.Operand)

				for t := range type_checking.UnionTypePartsSeq(argType) {
					if !type_checking.IsTypeFlagSet(t, checker.TypeFlagsAny|checker.TypeFlagsNever|checker.TypeFlagsBigIntLike|checker.TypeFlagsNumberLike) {
						ctx.ReportNode(node, buildUnaryMinusMessage(ctx.TypeChecker.TypeToString(t)))
						break
					}
				}
			},
		}
	},
}

var NoUnusedPrivateClassMembers = rule.Rule{
	Name: "@typescript-eslint/no-unused-private-class-members",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.TypeChecker == nil {
			return rule.Listeners{}
		}

		check := func(classNode *ast.Node, members *ast.NodeList) {
			if members == nil {
				return
			}
			declared := collectPrivateKeywordMembers(members)
			if len(declared) == 0 {
				return
			}
			markPrivateKeywordUses(ctx, classNode, declared)

			for _, member := range declared {
				if member.used {
					continue
				}
				message := rule.Message{
					Id: "unusedPrivateClassMember",
					Description: "Private class member '" + member.name +
						"' is defined but never used.",
				}
				if member.spanEnd == 0 {
					ctx.ReportNode(member.nameNode, message)
					continue
				}
				ctx.ReportRange(core.NewTextRange(
					rule.TokenRange(ctx.SourceFile, member.nameNode).Pos(), member.spanEnd), message)
			}
		}

		return rule.Listeners{
			ast.KindClassDeclaration: func(node *ast.Node) {
				check(node, node.AsClassDeclaration().Members)
			},
			ast.KindClassExpression: func(node *ast.Node) {
				check(node, node.AsClassExpression().Members)
			},
		}
	},
}

var NoUselessDefaultAssignment = rule.Rule{
	Name: "@typescript-eslint/no-useless-default-assignment",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[NoUselessDefaultAssignmentOptions](options)
		if !isSettings {
			settings = DefaultNoUselessDefaultAssignmentSettings()
		}

		canBeUndefined := func(subject *checker.Type) bool {
			if subject == nil {
				return false
			}
			if type_checking.IsTypeAnyType(subject) || type_checking.IsTypeUnknownType(subject) {
				return true
			}
			for part := range type_checking.UnionTypePartsSeq(subject) {
				if type_checking.IsTypeFlagSet(part, checker.TypeFlagsUndefined) {
					return true
				}
			}
			return false
		}

		if ctx.Program != nil &&
			!type_checking.IsStrictCompilerOptionEnabled(ctx.Program.Options(), ctx.Program.Options().StrictNullChecks) &&
			!settings.AllowRuleToRunWithoutStrictNullChecks {
			ctx.Skip("strictNullChecks is off")
			return nil
		}

		return rule.Listeners{
			ast.KindParameter: func(node *ast.Node) {
				if ctx.TypeChecker == nil || ctx.Program == nil {
					return
				}
				parameter := node.AsParameterDeclaration()
				if parameter.Initializer == nil {
					return
				}
				checkUselessDefault(ctx, canBeUndefined, node, parameter.Initializer,
					parameter.Name(), parameter.Type, "parameter")
			},
			ast.KindBindingElement: func(node *ast.Node) {
				if ctx.TypeChecker == nil || ctx.Program == nil {
					return
				}
				element := node.AsBindingElement()
				if element.Initializer == nil {
					return
				}

				checkUselessDefault(ctx, canBeUndefined, node, element.Initializer,
					element.Name(), nil, "property")
			},
		}
	},
}

var NoUselessEmptyExport = rule.Rule{
	Name: "@typescript-eslint/no-useless-empty-export",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindSourceFile: func(node *ast.Node) {
				sourceFile := node.AsSourceFile()
				if isDeclarationFileName(sourceFile.FileName().AsString()) {
					return
				}

				emptyExports := []*ast.Node{}
				makesFileAModule := false
				for _, statement := range sourceFile.Statements.Nodes {
					if isEmptyExportStatement(statement) {
						emptyExports = append(emptyExports, statement)
						continue
					}
					if statementMakesFileAModule(statement) {
						makesFileAModule = true
					}
				}
				if !makesFileAModule {
					return
				}
				for _, emptyExport := range emptyExports {
					ctx.ReportNodeWithFixes(emptyExport, messageUselessEmptyExport,
						ctx.RemoveNode(emptyExport))
				}
			},
		}
	},
}

var NoWrapperObjectTypes = rule.Rule{
	Name: "@typescript-eslint/no-wrapper-object-types",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		wrapperNames := make(map[string]bool, len(wrapperObjectTypes))
		for name := range wrapperObjectTypes {
			wrapperNames[name] = true
		}
		shadowed := module.DeclaredTypeNames(ctx.SourceFile, wrapperNames)

		return rule.Listeners{
			ast.KindTypeReference: func(node *ast.Node) {
				typeReference := node.AsTypeReferenceNode()
				if typeReference == nil {
					return
				}

				name := typeReference.TypeName
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}

				primitive, isWrapper := wrapperObjectTypes[name.Text()]
				if !isWrapper || shadowed[name.Text()] {
					return
				}

				if isImplementsHeritage(node) {

					ctx.ReportNode(name, messageBannedWrapperObjectType)
					return
				}

				ctx.ReportNodeWithFixes(name, messageBannedWrapperObjectType, ctx.ReplaceNode(name, primitive))
			},
		}
	},
}

var NonNullableTypeAssertionStyle = rule.Rule{
	Name: "@typescript-eslint/non-nullable-type-assertion-style",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		report := func(node *ast.Node, expression *ast.Node, typeNode *ast.Node) {

			if ctx.TypeChecker == nil {
				return
			}
			if expression == nil || typeNode == nil {
				return
			}

			if isConstTypeAssertion(typeNode) {
				return
			}

			originalTypes, isUsable := unionConstituentsIfNotLoose(ctx.TypeChecker, expression)
			if !isUsable {
				return
			}
			assertedTypes, isUsable := unionConstituentsIfNotLoose(ctx.TypeChecker, typeNode)
			if !isUsable {
				return
			}

			if !isSameTypeWithoutNullish(ctx.TypeChecker, assertedTypes, originalTypes) {
				return
			}

			assertedExpression := expression
			for assertedExpression.Kind == ast.KindParenthesizedExpression {
				inner := assertedExpression.AsParenthesizedExpression().Expression
				if inner == nil {
					break
				}
				assertedExpression = inner
			}

			expressionRange := rule.TokenRange(ctx.SourceFile, assertedExpression)
			expressionText := ctx.SourceFile.Text()[expressionRange.Pos():expressionRange.End()]

			precedence := ast.GetOperatorPrecedence(assertedExpression.Kind, ast.KindUnknown,
				ast.OperatorPrecedenceFlagsNone)
			replacement := expressionText + "!"
			if precedence <= ast.OperatorPrecedenceUnary {
				replacement = "(" + expressionText + ")!"
			}

			ctx.ReportNodeWithFixes(node, preferNonNullAssertionMessage,
				rule.ReplaceRange(rule.TokenRange(ctx.SourceFile, node), replacement))
		}

		return rule.Listeners{
			ast.KindAsExpression: func(node *ast.Node) {
				assertion := node.AsAsExpression()
				report(node, assertion.Expression, assertion.Type)
			},
			ast.KindTypeAssertionExpression: func(node *ast.Node) {
				assertion := node.AsTypeAssertion()
				report(node, assertion.Expression, assertion.Type)
			},
		}
	},
}

var preferNonNullAssertionMessage = rule.Message{
	Id:          "preferNonNullAssertion",
	Description: "Use a ! assertion to more succinctly remove null and undefined from the type.",
}

var OnlyThrowError = rule.Rule{
	Name: "@typescript-eslint/only-throw-error",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[OnlyThrowErrorOptions](options)

		allowRethrowing := settings.AllowRethrowing == nil || *settings.AllowRethrowing
		allowThrowingAny := settings.AllowThrowingAny == nil || *settings.AllowThrowingAny
		allowThrowingUnknown := settings.AllowThrowingUnknown == nil || *settings.AllowThrowingUnknown

		return rule.Listeners{
			ast.KindThrowStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				argument := node.AsThrowStatement().Expression
				if argument == nil {
					return
				}

				subject := ast.SkipParentheses(argument)
				if subject == nil {
					return
				}

				if ast.NodeIsMissing(subject) {
					return
				}

				if allowRethrowing && onlyThrowErrorIsRethrown(ctx, subject) {
					return
				}

				argumentType := ctx.TypeChecker.GetTypeAtLocation(subject)
				if argumentType == nil {
					return
				}

				if type_checking.TypeMatchesSomeSpecifier(argumentType, settings.Allow, settings.AllowInline, ctx.Program) {
					return
				}

				if type_checking.IsTypeFlagSet(argumentType, checker.TypeFlagsUndefined) {
					ctx.ReportNode(subject, buildOnlyThrowErrorUndefMessage())
					return
				}

				if allowThrowingAny && type_checking.IsTypeFlagSet(argumentType, checker.TypeFlagsAny) {
					return
				}

				if allowThrowingUnknown && type_checking.IsTypeFlagSet(argumentType, checker.TypeFlagsUnknown) {
					return
				}

				if type_checking.IsErrorLike(ctx.Program, ctx.TypeChecker, argumentType) {
					return
				}

				ctx.ReportNode(subject, buildOnlyThrowErrorObjectMessage())
			},
		}
	},
}

var PreferAsConst = rule.Rule{
	Name: "@typescript-eslint/prefer-as-const",
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindVariableDeclaration: func(node *ast.Node) {
				declaration := node.AsVariableDeclaration()

				if declaration.ExclamationToken != nil {
					return
				}

				reportAnnotation(ctx, declaration.Name(), declaration.Type, declaration.Initializer,
					declaration.Name() != nil && declaration.Name().Kind == ast.KindIdentifier)
			},
			ast.KindPropertyDeclaration: func(node *ast.Node) {
				property := node.AsPropertyDeclaration()
				if property.PostfixToken != nil {
					return
				}

				reportAnnotation(ctx, property.Name(), property.Type, property.Initializer, true)
			},
			ast.KindAsExpression: func(node *ast.Node) {
				expression := node.AsAsExpression()
				literalType := literalTypeRestatingValue(expression.Type, expression.Expression)
				if literalType == nil {
					return
				}

				ctx.ReportNodeWithFixes(literalType, messagePreferAsConst,
					ctx.ReplaceNode(literalType, "const"))
			},
		}
	},
}

var PreferEnumInitializers = rule.Rule{
	Name: "@typescript-eslint/prefer-enum-initializers",

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindEnumDeclaration: func(node *ast.Node) {

				for index, member := range node.AsEnumDeclaration().Members.Nodes {
					if member.AsEnumMember().Initializer != nil {
						continue
					}

					memberRange := rule.TokenRange(ctx.SourceFile, member)
					name := ctx.SourceFile.Text()[memberRange.Pos():memberRange.End()]

					ctx.ReportNodeWithSuggestions(member, buildDefineInitializerMessage(name),
						buildEnumInitializerSuggestion(memberRange, name, strconv.Itoa(index)),
						buildEnumInitializerSuggestion(memberRange, name, strconv.Itoa(index+1)),
						buildEnumInitializerSuggestion(memberRange, name, "'"+name+"'"),
					)
				}
			},
		}
	},
}

var PreferFind = rule.Rule{
	Name: "@typescript-eslint/prefer-find",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		var isArrayish func(subject *checker.Type) bool
		isArrayish = func(subject *checker.Type) bool {
			foundArray := false
			for unionPart := range type_checking.UnionTypePartsSeq(subject) {
				if type_checking.IsTypeFlagSet(unionPart, checker.TypeFlagsNull) ||
					type_checking.IsTypeFlagSet(unionPart, checker.TypeFlagsUndefined) {
					continue
				}

				everyPartIsArray := true
				for _, intersectionPart := range type_checking.IntersectionTypeParts(unionPart) {
					if !checker.Checker_isArrayType(ctx.TypeChecker, intersectionPart) &&
						!checker.IsTupleType(intersectionPart) {
						everyPartIsArray = false
						break
					}
				}
				if !everyPartIsArray {
					return false
				}
				foundArray = true
			}
			return foundArray
		}

		staticStringOf := func(expression *ast.Node) (string, bool) {
			if expression == nil {
				return "", false
			}
			switch expression.Kind {
			case ast.KindStringLiteral, ast.KindNumericLiteral,
				ast.KindNoSubstitutionTemplateLiteral:
				return expression.Text(), true
			case ast.KindIdentifier:

				if expression.Text() == "NaN" || expression.Text() == "Infinity" {
					return expression.Text(), true
				}
			case ast.KindPrefixUnaryExpression:

				unary := expression.AsPrefixUnaryExpression()
				if unary.Operator == ast.KindMinusToken && unary.Operand != nil &&
					unary.Operand.Kind == ast.KindIdentifier && unary.Operand.Text() == "Infinity" {
					return "-Infinity", true
				}
			}

			if ctx.TypeChecker == nil {
				return "", false
			}
			expressionType := ctx.TypeChecker.GetTypeAtLocation(expression)
			if expressionType == nil {
				return "", false
			}

			if !type_checking.IsTypeFlagSet(expressionType, checker.TypeFlagsStringLiteral) &&
				!type_checking.IsTypeFlagSet(expressionType, checker.TypeFlagsNumberLiteral) &&
				!type_checking.IsTypeFlagSet(expressionType, checker.TypeFlagsBigIntLiteral) {
				return "", false
			}
			rendered := ctx.TypeChecker.TypeToString(expressionType)

			if len(rendered) >= 2 && (rendered[0] == '"' || rendered[0] == '\'') &&
				rendered[len(rendered)-1] == rendered[0] {
				rendered = rendered[1 : len(rendered)-1]
			}

			if len(rendered) >= 2 && rendered[len(rendered)-1] == 'n' &&
				type_checking.IsTypeFlagSet(expressionType, checker.TypeFlagsBigIntLiteral) {
				rendered = rendered[:len(rendered)-1]
			}
			return rendered, true
		}

		memberNameOf := func(callee *ast.Node) (name string, isComputed bool, nameNode *ast.Node, ok bool) {
			if ast.IsPropertyAccessExpression(callee) {
				access := callee.AsPropertyAccessExpression()
				if access.Name() == nil || !ast.IsIdentifier(access.Name()) {
					return "", false, nil, false
				}
				return access.Name().Text(), false, access.Name(), true
			}
			if ast.IsElementAccessExpression(callee) {
				access := callee.AsElementAccessExpression()
				value, hasValue := staticStringOf(access.ArgumentExpression)
				if !hasValue {
					return "", false, nil, false
				}
				return value, true, access.ArgumentExpression, true
			}
			return "", false, nil, false
		}

		type filterCall struct {
			nameNode   *ast.Node
			isComputed bool
		}

		var collectFilters func(expression *ast.Node) []filterCall
		collectFilters = func(expression *ast.Node) []filterCall {
			if expression == nil {
				return nil
			}

			node := expression
			for node.Kind == ast.KindParenthesizedExpression {
				inner := node.AsParenthesizedExpression().Expression
				if inner == nil {
					return nil
				}
				node = inner
			}

			if node.Kind == ast.KindBinaryExpression &&
				node.AsBinaryExpression().OperatorToken != nil &&
				node.AsBinaryExpression().OperatorToken.Kind == ast.KindCommaToken {
				return collectFilters(node.AsBinaryExpression().Right)
			}

			if node.Kind == ast.KindConditionalExpression {
				conditional := node.AsConditionalExpression()
				whenTrue := collectFilters(conditional.WhenTrue)
				if len(whenTrue) == 0 {
					return nil
				}
				whenFalse := collectFilters(conditional.WhenFalse)
				if len(whenFalse) == 0 {
					return nil
				}
				return append(whenTrue, whenFalse...)
			}

			if !ast.IsCallExpression(node) {
				return nil
			}
			call := node.AsCallExpression()

			if call.QuestionDotToken != nil {
				return nil
			}
			callee := call.Expression
			if callee == nil {
				return nil
			}

			name, isComputed, nameNode, ok := memberNameOf(callee)
			if !ok || name != "filter" {
				return nil
			}

			receiver := receiverOfMemberAccess(callee)
			if receiver == nil || ctx.TypeChecker == nil {
				return nil
			}
			if !isArrayish(type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, receiver)) {
				return nil
			}
			return []filterCall{{nameNode: nameNode, isComputed: isComputed}}
		}

		buildSuggestion := func(filters []filterCall, arrayExpression *ast.Node, wholeExpression *ast.Node) (rule.Suggestion, bool) {
			fixes := make([]rule.Fix, 0, len(filters)+1)
			for _, filter := range filters {
				replacement := "find"
				if filter.isComputed {

					replacement = `"find"`
				}
				fixes = append(fixes, rule.ReplaceRange(
					rule.TokenRange(ctx.SourceFile, filter.nameNode), replacement))
			}

			accessStart, hasAccessStart := memberAccessTokenAfter(
				ctx.SourceFile.Text(),
				rule.TokenRange(ctx.SourceFile, arrayExpression).End(),
				rule.TokenRange(ctx.SourceFile, wholeExpression).End())
			if !hasAccessStart {

				return rule.Suggestion{}, false
			}
			fixes = append(fixes, rule.RemoveRange(core.NewTextRange(
				accessStart, rule.TokenRange(ctx.SourceFile, wholeExpression).End())))

			return rule.Suggestion{Message: buildPreferFindSuggestionMessage(), Fixes: fixes}, true
		}

		report := func(wholeExpression *ast.Node, arrayExpression *ast.Node, filters []filterCall) {
			if suggestion, hasSuggestion := buildSuggestion(filters, arrayExpression, wholeExpression); hasSuggestion {
				ctx.ReportNodeWithSuggestions(wholeExpression, buildPreferFindMessage(), suggestion)
				return
			}
			ctx.ReportNode(wholeExpression, buildPreferFindMessage())
		}

		return rule.Listeners{

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				call := node.AsCallExpression()
				if call.Arguments == nil || len(call.Arguments.Nodes) != 1 {
					return
				}
				callee := call.Expression
				if callee == nil {
					return
				}

				if optionalMemberAccess(callee) {
					return
				}
				name, _, _, ok := memberNameOf(callee)
				if !ok || name != "at" {
					return
				}
				value, hasValue := staticStringOf(call.Arguments.Nodes[0])
				if !hasValue || !isTreatedAsZeroByArrayAt(value) {
					return
				}
				receiver := receiverOfMemberAccess(callee)
				if filters := collectFilters(receiver); len(filters) != 0 {
					report(node, receiver, filters)
				}
			},

			ast.KindElementAccessExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}
				access := node.AsElementAccessExpression()

				if access.QuestionDotToken != nil {
					return
				}
				value, hasValue := staticStringOf(access.ArgumentExpression)
				if !hasValue || value != "0" {

					return
				}
				if filters := collectFilters(access.Expression); len(filters) != 0 {
					report(node, access.Expression, filters)
				}
			},
		}
	},
}

var PreferForOf = rule.Rule{
	Name: "@typescript-eslint/prefer-for-of",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		return rule.Listeners{
			ast.KindForStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				statement := node.AsForStatement()

				declarator := singleNonConstDeclarator(statement.Initializer)
				if declarator == nil {
					return
				}
				declaration := declarator.AsVariableDeclaration()
				if !isZeroInitialized(declaration) {
					return
				}
				indexName := declaration.Name()
				if indexName == nil || indexName.Kind != ast.KindIdentifier {
					return
				}

				arrayExpression := arrayOfLessThanLengthTest(statement.Condition,
					indexName.AsIdentifier().Text)
				if arrayExpression == nil {
					return
				}

				if !isIncrementOfIndex(statement.Incrementor, indexName.AsIdentifier().Text) {
					return
				}

				if !isIndexOnlyUsedToSubscript(ctx, statement.Statement, declarator, arrayExpression) {
					return
				}

				ctx.ReportNode(node, preferForOfMessage)
			},
		}
	},
}

var preferForOfMessage = rule.Message{
	Id:          "preferForOf",
	Description: "Expected a `for-of` loop instead of a `for` loop with this simple iteration.",
}

var PreferFunctionType = rule.Rule{
	Name: "@typescript-eslint/prefer-function-type",

	Run: func(ctx rule.Context, options any) rule.Listeners {
