	Id:          "notLiteral",
	Description: "Explicit enum value must only be a literal value (string or number).",
}

var preferLiteralEnumMemberNotLiteralOrBitwiseMessage = rule.Message{
	Id: "notLiteralOrBitwiseExpression",
	Description: "Explicit enum value must only be a literal value (string or number) " +
		"or a bitwise expression.",
}

var messagePreferNamespaceKeyword = rule.Message{
	Id: "preferNamespaceKeyword",
	Description: "This declares a namespace with the `module` keyword, which TypeScript has " +
		"deprecated and plans to make a parse error. It means the same thing as `namespace` and " +
		"reads as an ECMAScript module, which it is not. Write `namespace` instead.",
}

var PreferNamespaceKeyword = rule.Rule{
	Name: "@typescript-eslint/prefer-namespace-keyword",
	Run: func(ctx rule.Context, options any) rule.Listeners {

		if ctx.SourceFile == nil {
			return nil
		}

		return rule.Listeners{
			ast.KindModuleDeclaration: func(node *ast.Node) {

				name := node.Name()
				if name == nil || name.Kind != ast.KindIdentifier {
					return
				}

				if node.Parent != nil && node.Parent.Kind == ast.KindModuleDeclaration {
					return
				}

				keyword := moduleDeclarationKeywordRange(ctx.SourceFile, node)
				sourceText := ctx.SourceFile.Text()
				if keyword.End() > len(sourceText) {
					return
				}

				if sourceText[keyword.Pos():keyword.End()] != "module" {
					return
				}

				ctx.ReportRangeWithFixes(
					moduleDeclarationReportRange(ctx.SourceFile, node),
					messagePreferNamespaceKeyword,
					rule.ReplaceRange(keyword, "namespace"),
				)
			},
		}
	},
}

var errPreferNullishCoalescingPrimitivesFalse = errors.New(
	"prefer-nullish-coalescing: ignorePrimitives accepts an object or the literal true; " +
		"false is not a legal value, and upstream refuses it at config load")

var PreferNullishCoalescing = rule.Rule{
	Name:             "@typescript-eslint/prefer-nullish-coalescing",
	NeedsTypeChecker: true,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, ok := rule.OptionsAs[PreferNullishCoalescingOptions](options)
		if !ok {
			settings = DefaultPreferNullishCoalescingOptions()
		}

		return rule.Listeners{
			ast.KindSourceFile: func(file *ast.Node) {
				var pending []preferNullishCoalescingFinding

				var visit func(*ast.Node) bool
				visit = func(current *ast.Node) bool {
					var finding preferNullishCoalescingFinding
					reports := false
					switch current.Kind {
					case ast.KindBinaryExpression:
						finding, reports = preferNullishCoalescingJudge(ctx, current, settings)
					case ast.KindConditionalExpression:
						finding, reports = preferNullishCoalescingJudgeTernary(ctx, current, settings)
					case ast.KindIfStatement:
						finding, reports = preferNullishCoalescingJudgeIf(ctx, current, settings)
					}
					if reports {
						pending = append(pending, finding)
					}
					current.ForEachChild(visit)
					return false
				}
				file.ForEachChild(visit)

				sort.SliceStable(pending, func(left, right int) bool {
					return pending[left].reportRange.Pos() < pending[right].reportRange.Pos()
				})
				for _, finding := range pending {
					ctx.ReportRangeWithSuggestions(finding.reportRange, finding.message,
						rule.Suggestion{Message: finding.suggestion, Fixes: finding.fixes})
				}
			},
		}
	},
}

var messagePreferNullishOverAssignment = rule.Message{
	Id: "preferNullishOverAssignment",
	Description: "Prefer using nullish coalescing operator (`??=`) instead of an assignment " +
		"expression, as it is simpler to read. The `if` assigns only when the target is null or " +
		"undefined, which is exactly what `??=` does, in one statement that names the target once.",
}

var PreferPromiseRejectErrors = rule.Rule{
	Name: "@typescript-eslint/prefer-promise-reject-errors",

	NeedsTypeChecker: true,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, _ := rule.OptionsAs[PreferPromiseRejectErrorsOptions](options)

		checkRejectCall := func(call *ast.Node) {
			arguments := call.Arguments()

			if len(arguments) == 0 {
				if settings.AllowEmptyReject {
					return
				}
				ctx.ReportNode(call, buildPreferPromiseRejectErrorsMessage())
				return
			}

			argument := arguments[0]
			argumentType := ctx.TypeChecker.GetTypeAtLocation(argument)
			if argumentType == nil {
				return
			}

			if type_checking.TypeMatchesSomeSpecifier(argumentType, settings.Allow, settings.AllowInline, ctx.Program) {
				return
			}
			if settings.AllowThrowingAny && type_checking.IsTypeAnyType(argumentType) {
				return
			}
			if settings.AllowThrowingUnknown && type_checking.IsTypeUnknownType(argumentType) {
				return
			}
			if type_checking.IsErrorLike(ctx.Program, ctx.TypeChecker, argumentType) {
				return
			}

			if type_checking.IsReadonlyErrorLike(ctx.Program, ctx.TypeChecker, argumentType) {
				return
			}

			ctx.ReportNode(call, buildPreferPromiseRejectErrorsMessage())
		}

		return rule.Listeners{

			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				callee := ast.SkipParentheses(node.Expression())
				if callee == nil {
					return
				}

				receiver, propertyName := preferPromiseRejectErrorsStaticMemberAccess(callee)
				if receiver == nil || propertyName != "reject" {
					return
				}

				receiverType := ctx.TypeChecker.GetTypeAtLocation(receiver)
				if receiverType == nil {
					return
				}
				if !type_checking.IsPromiseConstructorLike(ctx.Program, ctx.TypeChecker, receiverType) &&
					!type_checking.IsPromiseLike(ctx.Program, ctx.TypeChecker, receiverType) {
					return
				}

				checkRejectCall(node)
			},

			ast.KindNewExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				callee := ast.SkipParentheses(node.Expression())
				if callee == nil {
					return
				}
				calleeType := ctx.TypeChecker.GetTypeAtLocation(callee)
				if calleeType == nil || !type_checking.IsPromiseConstructorLike(ctx.Program, ctx.TypeChecker, calleeType) {
					return
				}

				arguments := node.Arguments()
				if len(arguments) == 0 {
					return
				}
				executor := ast.SkipParentheses(arguments[0])
				if executor == nil || !preferPromiseRejectErrorsIsFunction(executor) {
					return
				}

				parameters := executor.Parameters()
				if len(parameters) < 2 {
					return
				}
				rejectParameter := parameters[1]
				if rejectParameter.AsParameterDeclaration().DotDotDotToken != nil {
					return
				}

				rejectName := rejectParameter.Name()
				if rejectName == nil || !ast.IsIdentifier(rejectName) {
					return
				}

				rejectSymbol := ctx.TypeChecker.GetSymbolAtLocation(rejectName)
				if rejectSymbol == nil {
					return
				}

				preferPromiseRejectErrorsForEachCallOfSymbol(ctx, executor, rejectSymbol, checkRejectCall)
			},
		}
	},
}

var PreferReduceTypeParameter = rule.Rule{
	Name: "@typescript-eslint/prefer-reduce-type-parameter",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		isArrayOrTupleThroughout := func(receiverType *checker.Type) bool {
			for unionPart := range type_checking.UnionTypePartsSeq(receiverType) {
				for _, part := range type_checking.IntersectionTypeParts(unionPart) {
					if !checker.Checker_isArrayType(ctx.TypeChecker, part) &&
						!checker.IsTupleType(part) {
						return false
					}
				}
			}
			return true
		}

		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				call := node.AsCallExpression()
				if call.Expression == nil {
					return
				}

				callee := ast.SkipParentheses(call.Expression)

				receiver, memberName, isMemberAccess := reduceMemberAccessOf(callee)
				if !isMemberAccess || memberName != "reduce" {
					return
				}

				if call.Arguments == nil || len(call.Arguments.Nodes) < 2 {
					return
				}

				secondArgument := ast.SkipParentheses(call.Arguments.Nodes[1])

				assertedValue, assertedType, isAssertion := typeAssertionParts(secondArgument)
				if !isAssertion {
					return
				}

				if isConstAssertionType(assertedType) {
					return
				}

				initializerType := ctx.TypeChecker.GetTypeAtLocation(assertedValue)
				assertedTypeValue := ctx.TypeChecker.GetTypeAtLocation(assertedType)
				if initializerType == nil || assertedTypeValue == nil {
					return
				}
				if !checker.Checker_isTypeAssignableTo(ctx.TypeChecker, initializerType, assertedTypeValue) {
					return
				}

				receiverType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, receiver)
				if receiverType == nil || !isArrayOrTupleThroughout(receiverType) {
					return
				}

				assertionRange := rule.TokenRange(ctx.SourceFile, secondArgument)
				valueRange := rule.TokenRange(ctx.SourceFile, assertedValue)

				fixes := []rule.Fix{
					rule.RemoveRange(core.NewTextRange(assertionRange.Pos(), valueRange.Pos())),
					rule.RemoveRange(core.NewTextRange(valueRange.End(), assertionRange.End())),
				}

				if call.TypeArguments == nil {

					typeText := ctx.SourceFile.Text()[rule.TokenRange(ctx.SourceFile, assertedType).Pos():assertedType.End()]
					fixes = append(fixes, ctx.InsertAfter(callee, "<"+typeText+">"))
				}

				ctx.ReportNodeWithFixes(secondArgument, buildPreferTypeParameterMessage(), fixes...)
			},
		}
	},
}

var PreferRegexpExec = rule.Rule{
	Name:             "@typescript-eslint/prefer-regexp-exec",
	NeedsTypeChecker: true,
	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.TypeChecker == nil {
			return rule.Listeners{}
		}
		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				checkPreferRegexpExec(ctx, node)
			},
		}
	},
}

var PreferReturnThisType = rule.Rule{
	Name: "@typescript-eslint/prefer-return-this-type",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		checkFunction := func(function *ast.Node, class *ast.Node) {
			className := classNameTextOf(class)
			if className == "" {
				return
			}

			returnType := function.Type()
			if returnType == nil {
				return
			}

			matched := typeReferenceNamed(className, returnType)
			if matched == nil {
				return
			}

			if !functionReturnsOnlyThis(ctx, function, class) {
				return
			}

			ctx.ReportNodeWithFixes(matched, buildUseThisTypeMessage(),
				rule.ReplaceRange(rule.TokenRange(ctx.SourceFile, matched), "this"))
		}

		checkProperty := func(node *ast.Node, class *ast.Node) {
			initializer := node.Initializer()
			if initializer == nil {
				return
			}

			if initializer.Kind != ast.KindFunctionExpression &&
				initializer.Kind != ast.KindArrowFunction {
				return
			}
			checkFunction(initializer, class)
		}

		visitClass := func(node *ast.Node) {
			if ctx.TypeChecker == nil {
				return
			}

			for _, member := range node.Members() {
				switch member.Kind {

				case ast.KindMethodDeclaration, ast.KindGetAccessor, ast.KindSetAccessor,
					ast.KindConstructor:
					checkFunction(member, node)
				case ast.KindPropertyDeclaration:
					checkProperty(member, node)
				}
			}
		}

		return rule.Listeners{
			ast.KindClassDeclaration: visitClass,
			ast.KindClassExpression:  visitClass,
		}
	},
}

var RelatedGetterSetterPairs = rule.Rule{
	Name:             "@typescript-eslint/related-getter-setter-pairs",
	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,
	Run: func(ctx rule.Context, options any) rule.Listeners {

		if ctx.TypeChecker == nil {
			return rule.Listeners{}
		}

		checkContainer := func(members []*ast.Node) {

			type pair struct {
				getter *ast.Node
				setter *ast.Node
			}
			pairs := map[string]*pair{}
			var order []string
			record := func(name string, member *ast.Node, isGetter bool) {
				existing, seen := pairs[name]
				if !seen {
					existing = &pair{}
					pairs[name] = existing
					order = append(order, name)
				}

				if isGetter {
					existing.getter = member
				} else {
					existing.setter = member
				}
			}

			for _, member := range members {
				switch member.Kind {
				case ast.KindGetAccessor:

					if isAbstractAccessor(member) {
						continue
					}

					if member.Type() == nil {
						continue
					}
					name, ok := relatedAccessorName(ctx, member)
					if !ok {
						continue
					}
					record(name, member, true)

				case ast.KindSetAccessor:
					if isAbstractAccessor(member) {
						continue
					}

					parameters := member.Parameters()
					if len(parameters) != 1 {
						continue
					}
					name, ok := relatedAccessorName(ctx, member)
					if !ok {
						continue
					}
					record(name, member, false)
				}
			}

			for _, name := range order {
				candidate := pairs[name]
				if candidate.getter == nil || candidate.setter == nil {
					continue
				}

				getterType := ctx.TypeChecker.GetTypeAtLocation(candidate.getter)
				setterType := ctx.TypeChecker.GetTypeAtLocation(candidate.setter.Parameters()[0])

				if shimchecker.Checker_isTypeAssignableTo(ctx.TypeChecker, getterType, setterType) {
					continue
				}

				ctx.ReportNode(ast.SkipTypeParentheses(candidate.getter.Type()), messageRelatedGetterSetterPairs)
			}
		}

		return rule.Listeners{
			ast.KindClassDeclaration: func(node *ast.Node) {
				checkContainer(node.Members())
			},

			ast.KindClassExpression: func(node *ast.Node) {
				checkContainer(node.Members())
			},
			ast.KindInterfaceDeclaration: func(node *ast.Node) {
				checkContainer(node.Members())
			},
			ast.KindTypeLiteral: func(node *ast.Node) {
				checkContainer(node.Members())
			},
		}
	},
}

var RequireArraySortCompare = rule.Rule{
	Name: "@typescript-eslint/require-array-sort-compare",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[RequireArraySortCompareOptions](options)
		if !isSettings {

			settings = DefaultRequireArraySortCompareSettings()
		}

		isStringArrayNode := func(receiver *ast.Node) bool {
			receiverType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, receiver)
			if !checker.Checker_isArrayType(ctx.TypeChecker, receiverType) &&
				!checker.IsTupleType(receiverType) {
				return false
			}

			typeArguments := checker.Checker_getTypeArguments(ctx.TypeChecker, receiverType)
			for _, argument := range typeArguments {
				if type_checking.GetTypeName(ctx.TypeChecker, argument) != "string" {
					return false
				}
			}

			return true
		}

		isArrayOrUnionOfArrays := func(receiverType *checker.Type) bool {
			for constituent := range type_checking.UnionTypePartsSeq(receiverType) {
				if !checker.Checker_isArrayType(ctx.TypeChecker, constituent) {
					return false
				}
			}
			return true
		}

		return rule.Listeners{
			ast.KindCallExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				call := node.AsCallExpression()

				if call.Arguments != nil && len(call.Arguments.Nodes) != 0 {
					return
				}

				if call.Expression == nil {
					return
				}
				callee := ast.SkipParentheses(call.Expression)

				receiver, memberName, isMemberAccess := sortMemberAccessOf(callee)
				if !isMemberAccess || (memberName != "sort" && memberName != "toSorted") {
					return
				}

				if settings.IgnoreStringArrays && isStringArrayNode(receiver) {
					return
				}

				if !isArrayOrUnionOfArrays(type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, receiver)) {
					return
				}

				ctx.ReportNode(node, buildRequireCompareMessage())
			},
		}
	},
}

var RestrictPlusOperands = rule.Rule{
	Name: "@typescript-eslint/restrict-plus-operands",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		if ctx.TypeChecker == nil {
			return nil
		}

		settings := restrictPlusOperandsSettingsFrom(options)
		stringLike := restrictPlusOperandsStringLike(settings)

		typeOf := func(node *ast.Node) *checker.Type {
			return checker.Checker_getBaseTypeOfLiteralType(
				ctx.TypeChecker,
				type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, node),
			)
		}

		checkPlusOperands := func(node *ast.Node, left *ast.Node, right *ast.Node) {
			leftType := typeOf(left)
			rightType := typeOf(right)
			if leftType == nil || rightType == nil {
				return
			}

			if leftType == rightType && type_checking.IsTypeFlagSet(leftType,
				checker.TypeFlagsBigIntLike|checker.TypeFlagsNumberLike|checker.TypeFlagsStringLike) {
				return
			}

			hadIndividualComplaint := false

			for _, side := range []struct {
				node      *ast.Node
				baseType  *checker.Type
				otherType *checker.Type
			}{
				{left, leftType, rightType},
				{right, rightType, leftType},
			} {

				if restrictPlusOperandsIsTypeFlagSetInUnion(side.baseType,
					checker.TypeFlagsESSymbolLike|checker.TypeFlagsNever|checker.TypeFlagsUnknown) ||
					(!settings.allowAny && restrictPlusOperandsIsTypeFlagSetInUnion(side.baseType, checker.TypeFlagsAny)) ||
					(!settings.allowBoolean && restrictPlusOperandsIsTypeFlagSetInUnion(side.baseType, checker.TypeFlagsBooleanLike)) ||
					(!settings.allowNullish && restrictPlusOperandsIsTypeFlagSetInUnion(side.baseType,
						checker.TypeFlagsNull|checker.TypeFlagsUndefined)) {
					ctx.ReportNode(side.node, buildRestrictPlusOperandsInvalidMessage(
						ctx.TypeChecker.TypeToString(side.baseType), stringLike))
					hadIndividualComplaint = true
					continue
				}

				for subBaseType := range type_checking.UnionTypePartsSeq(side.baseType) {
					var reportThisPart bool
					if ctx.TypeChecker.TypeToString(subBaseType) == "RegExp" {

						reportThisPart = !settings.allowRegExp ||
							restrictPlusOperandsIsTypeFlagSetInUnion(side.otherType, checker.TypeFlagsNumberLike)
					} else {
						reportThisPart = (!settings.allowAny && type_checking.IsTypeAnyType(subBaseType)) ||
							restrictPlusOperandsIsDeeplyObjectType(subBaseType)
					}

					if reportThisPart {
						ctx.ReportNode(side.node, buildRestrictPlusOperandsInvalidMessage(
							ctx.TypeChecker.TypeToString(subBaseType), stringLike))
						hadIndividualComplaint = true
						continue
					}
				}
			}

			if hadIndividualComplaint {
				return
			}

			for _, pair := range [][2]*checker.Type{
				{leftType, rightType},
				{rightType, leftType},
			} {
				baseType, otherType := pair[0], pair[1]

				if !settings.allowNumberAndString &&
					restrictPlusOperandsIsTypeFlagSetInUnion(baseType, checker.TypeFlagsStringLike) &&
					restrictPlusOperandsIsTypeFlagSetInUnion(otherType,
						checker.TypeFlagsNumberLike|checker.TypeFlagsBigIntLike) {
					ctx.ReportNode(node, buildRestrictPlusOperandsMismatchedMessage(
						ctx.TypeChecker.TypeToString(leftType),
						ctx.TypeChecker.TypeToString(rightType),
						stringLike))
					return
				}

				if restrictPlusOperandsIsTypeFlagSetInUnion(baseType, checker.TypeFlagsNumberLike) &&
					restrictPlusOperandsIsTypeFlagSetInUnion(otherType, checker.TypeFlagsBigIntLike) {
					ctx.ReportNode(node, buildRestrictPlusOperandsBigintAndNumberMessage(
						ctx.TypeChecker.TypeToString(leftType),
						ctx.TypeChecker.TypeToString(rightType)))
					return
				}
			}
		}

		return rule.Listeners{

			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				switch binary.OperatorToken.Kind {
				case ast.KindPlusToken:
				case ast.KindPlusEqualsToken:
					if settings.skipCompoundAssignments {
						return
					}
				default:
					return
				}

				checkPlusOperands(node, binary.Left, binary.Right)
			},
		}
	},
}

var RestrictTemplateExpressions = rule.Rule{
	Name: "@typescript-eslint/restrict-template-expressions",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	ProgramReads: rule.ReadsCompilerOptions | rule.ReadsDefaultLibrary,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[RestrictTemplateExpressionsOptions](options)
		if !isSettings {

			decoded, _ := DecodeRestrictTemplateExpressionsOptions(nil)
			settings, _ = decoded.(RestrictTemplateExpressionsOptions)
		}

		allowAny := restrictTemplateExpressionsEnabled(settings.AllowAny, true)
		allowArray := restrictTemplateExpressionsEnabled(settings.AllowArray, false)
		allowBoolean := restrictTemplateExpressionsEnabled(settings.AllowBoolean, true)
		allowNever := restrictTemplateExpressionsEnabled(settings.AllowNever, false)
		allowNullish := restrictTemplateExpressionsEnabled(settings.AllowNullish, true)
		allowNumber := restrictTemplateExpressionsEnabled(settings.AllowNumber, true)
		allowRegExp := restrictTemplateExpressionsEnabled(settings.AllowRegExp, true)

		var isAllowedType func(candidate *checker.Type) bool
		isAllowedType = func(candidate *checker.Type) bool {
			if candidate == nil {
				return true
			}

			if candidate.IsUnion() {
				for _, part := range candidate.AsUnionType().Types() {
					if !isAllowedType(part) {
						return false
					}
				}
				return true
			}

			if candidate.IsIntersection() {
				for _, part := range candidate.AsIntersectionType().Types() {
					if isAllowedType(part) {
						return true
					}
				}
				return false
			}

			if type_checking.IsTypeFlagSet(candidate, checker.TypeFlagsStringLike) {
				return true
			}

			if matchesAllowedTypeOrBaseType(ctx, candidate, settings,
				map[*checker.Type]struct{}{}) {
				return true
			}

			if allowAny && type_checking.IsTypeAnyType(candidate) {
				return true
			}
			if allowBoolean && type_checking.IsTypeFlagSet(candidate, checker.TypeFlagsBooleanLike) {
				return true
			}
			if allowNullish && type_checking.IsTypeFlagSet(candidate,
				checker.TypeFlagsNull|checker.TypeFlagsUndefined) {
				return true
			}
			if allowNumber && type_checking.IsTypeFlagSet(candidate,
				checker.TypeFlagsNumberLike|checker.TypeFlagsBigIntLike) {
				return true
			}
			if allowRegExp && type_checking.GetTypeName(ctx.TypeChecker, candidate) == "RegExp" {
				return true
			}
			if allowNever && type_checking.IsTypeFlagSet(candidate, checker.TypeFlagsNever) {
				return true
			}

			if allowArray && (checker.Checker_isArrayType(ctx.TypeChecker, candidate) ||
				checker.IsTupleType(candidate)) {
				return isAllowedType(type_checking.GetNumberIndexType(ctx.TypeChecker, candidate))
			}

			return false
		}

		return rule.Listeners{
			ast.KindTemplateExpression: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				if node.Parent != nil && node.Parent.Kind == ast.KindTaggedTemplateExpression {
					return
				}

				templateExpression := node.AsTemplateExpression()
				if templateExpression.TemplateSpans == nil {
					return
				}

				for _, span := range templateExpression.TemplateSpans.Nodes {
					expression := span.AsTemplateSpan().Expression
					if expression == nil {
						continue
					}

					expressionType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker,
						expression)
					if expressionType == nil || isAllowedType(expressionType) {
						continue
					}

					ctx.ReportNode(expression, buildInvalidTypeMessage(
						ctx.TypeChecker.TypeToString(expressionType)))
				}
			},
		}
	},
}

var ReturnAwait = rule.Rule{
	Name: "@typescript-eslint/return-await",

	NeedsTypeChecker: true,

	Run: func(ctx rule.Context, options any) rule.Listeners {

		if ctx.TypeChecker == nil {
			return nil
		}

		settings, isSettings := rule.OptionsAs[ReturnAwaitOptions](options)
		if !isSettings {
			settings = DefaultReturnAwaitSettings()
		}
		errorHandlingDisposition, ordinaryDisposition := dispositionsFor(settings.Mode)

		var test func(node *ast.Node)
		test = func(node *ast.Node) {
			isAwait := node.Kind == ast.KindAwaitExpression

			subject := node
			if isAwait {
				subject = node.AsAwaitExpression().Expression
				if subject == nil {
					return
				}
			}

			subjectType := ctx.TypeChecker.GetTypeAtLocation(subject)
			if subjectType == nil {
				return
			}
			certainty := type_checking.NeedsToBeAwaited(ctx.TypeChecker, node, subjectType)

			if certainty != type_checking.TypeAwaitableAlways {
				if !isAwait {
					return
				}

				if certainty == type_checking.TypeAwaitableMay {
					return
				}

				if fixes, canFix := removeAwaitFixes(ctx, node); canFix {
					ctx.ReportNodeWithFixes(node, returnAwaitMessage("nonPromiseAwait"), fixes...)
				} else {
					ctx.ReportNode(node, returnAwaitMessage("nonPromiseAwait"))
				}
				return
			}

			affectsErrorHandling := affectsExplicitErrorHandling(node) ||
				usingDeclarationInScope(ctx, node)

			disposition := ordinaryDisposition
			if affectsErrorHandling {
				disposition = errorHandlingDisposition
			}

			switch disposition {
			case returnAwaitDoNotCare:
				return
			case returnAwaitWant:
				if isAwait {
					return
				}
				insertion := insertAwaitFixes(ctx, node)
				if affectsErrorHandling {

					ctx.ReportNodeWithSuggestions(node, returnAwaitMessage("requiredPromiseAwait"),
						rule.Suggestion{
							Message: returnAwaitMessage("requiredPromiseAwaitSuggestion"),
							Fixes:   insertion,
						})
					return
				}
				ctx.ReportNodeWithFixes(node, returnAwaitMessage("requiredPromiseAwait"), insertion...)
			case returnAwaitForbid:
				if !isAwait {
					return
				}
				fixes, canFix := removeAwaitFixes(ctx, node)
				if !canFix {
					ctx.ReportNode(node, returnAwaitMessage("disallowedPromiseAwait"))
					return
				}
				if affectsErrorHandling {
					ctx.ReportNodeWithSuggestions(node, returnAwaitMessage("disallowedPromiseAwait"),
						rule.Suggestion{
							Message: returnAwaitMessage("disallowedPromiseAwaitSuggestion"),
							Fixes:   fixes,
						})
					return
				}
				ctx.ReportNodeWithFixes(node, returnAwaitMessage("disallowedPromiseAwait"), fixes...)
			}
		}

		var testPossiblyReturned func(node *ast.Node)
		testPossiblyReturned = func(node *ast.Node) {
			if node == nil {
				return
			}

			for node.Kind == ast.KindParenthesizedExpression {
				inner := node.AsParenthesizedExpression().Expression
				if inner == nil {
					return
				}
				node = inner
			}

			if node.Kind == ast.KindConditionalExpression {
				conditional := node.AsConditionalExpression()

				testPossiblyReturned(conditional.WhenTrue)
				testPossiblyReturned(conditional.WhenFalse)
				return
			}
			test(node)
		}

		return rule.Listeners{
			ast.KindReturnStatement: func(node *ast.Node) {
				enclosing := enclosingFunctionOfReturn(node)
				if enclosing == nil || !isAsyncFunction(enclosing) {
					return
				}
				testPossiblyReturned(node.AsReturnStatement().Expression)
			},
			ast.KindArrowFunction: func(node *ast.Node) {

				arrow := node.AsArrowFunction()
				if !isAsyncFunction(node) || arrow.Body == nil || arrow.Body.Kind == ast.KindBlock {
					return
				}
				testPossiblyReturned(arrow.Body)
			},
		}
	},
}

var StrictVoidReturn = rule.Rule{
	Name: "@typescript-eslint/strict-void-return",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		settings, isSettings := rule.OptionsAs[StrictVoidReturnOptions](options)
		if !isSettings {
			settings = DefaultStrictVoidReturnSettings()
		}

		state := &strictVoidReturnState{ctx: ctx, settings: settings}

		return rule.Listeners{
			ast.KindCallExpression: state.checkCall,
			ast.KindNewExpression:  state.checkCall,

			ast.KindArrayLiteralExpression: func(node *ast.Node) {
				for _, element := range node.AsArrayLiteralExpression().Elements.Nodes {
					if element.Kind != ast.KindSpreadElement {
						state.checkExpression(element)
					}
				}
			},

			ast.KindArrowFunction: func(node *ast.Node) {

				body := node.AsArrowFunction().Body
				if body != nil && body.Kind != ast.KindBlock {
					state.checkExpression(body)
				}
			},

			ast.KindBinaryExpression: func(node *ast.Node) {
				binary := node.AsBinaryExpression()
				if binary.OperatorToken == nil {
					return
				}

				switch binary.OperatorToken.Kind {
				case ast.KindEqualsToken,
					ast.KindQuestionQuestionEqualsToken,
					ast.KindBarBarEqualsToken,
					ast.KindAmpersandAmpersandEqualsToken:
					state.checkExpression(binary.Right)
				}
			},

			ast.KindObjectLiteralExpression: func(node *ast.Node) {
				for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
					switch property.Kind {
					case ast.KindPropertyAssignment:
						state.checkExpression(property.AsPropertyAssignment().Initializer)
					case ast.KindMethodDeclaration:

						state.reportIfNonVoidFunctionAtProperty(property)
					}
				}
			},

			ast.KindReturnStatement: func(node *ast.Node) {
				if argument := node.AsReturnStatement().Expression; argument != nil {
					state.checkExpression(argument)
				}
			},

			ast.KindVariableDeclaration: func(node *ast.Node) {
				if initializer := node.AsVariableDeclaration().Initializer; initializer != nil {
					state.checkExpression(initializer)
				}
			},

			ast.KindPropertyDeclaration: func(node *ast.Node) {

				if state.checkAgainstBaseTypes(node) {
					return
				}
				if initializer := node.AsPropertyDeclaration().Initializer; initializer != nil {
					state.checkExpression(initializer)
				}
			},

			ast.KindMethodDeclaration: func(node *ast.Node) {

				if node.AsMethodDeclaration().Body == nil {
					return
				}
				state.checkAgainstBaseTypes(node)
			},

			ast.KindGetAccessor: func(node *ast.Node) {
				if node.AsGetAccessorDeclaration().Body == nil {
					return
				}
				state.checkAgainstBaseTypes(node)
			},

			ast.KindJsxAttribute: func(node *ast.Node) {
				initializer := node.AsJsxAttribute().Initializer
				if initializer == nil || initializer.Kind != ast.KindJsxExpression {
					return
				}

				if inner := initializer.AsJsxExpression().Expression; inner != nil && state.isNonVoidFunctionValue(inner) {
					state.checkExpression(inner)
				}
			},
		}
	},
}

var SwitchExhaustivenessCheck = rule.Rule{
	Name: "@typescript-eslint/switch-exhaustiveness-check",

	NeedsTypeChecker: true,
	TypeReach:        rule.TypeReachShapes,

	Run: func(ctx rule.Context, options any) rule.Listeners {
		opts, ok := rule.OptionsAs[SwitchExhaustivenessCheckOptions](options)
		if !ok {
			opts = SwitchExhaustivenessCheckOptions{}
		}
		if opts.AllowDefaultCaseForExhaustiveSwitch == nil {
			opts.AllowDefaultCaseForExhaustiveSwitch = type_checking.Ref(true)
		}
		if opts.ConsiderDefaultExhaustiveForUnions == nil {
			opts.ConsiderDefaultExhaustiveForUnions = type_checking.Ref(false)
		}
		if opts.RequireDefaultForNonUnion == nil {
			opts.RequireDefaultForNonUnion = type_checking.Ref(false)
		}

		commentPattern := defaultCaseCommentPattern
		if opts.DefaultCaseCommentPattern != nil {
			commentPattern, _ = regexp.Compile(*opts.DefaultCaseCommentPattern)
		}

		isLiteralLikeType := func(t *checker.Type) bool {
			return type_checking.IsTypeFlagSet(
				t,
				checker.TypeFlagsLiteral|checker.TypeFlagsUndefined|checker.TypeFlagsNull|checker.TypeFlagsUniqueESSymbol,
			)
		}

		doesTypeContainNonLiteralType := func(t *checker.Type) bool {
			return type_checking.Some(
				type_checking.UnionTypeParts(t),
				func(t *checker.Type) bool {
					return type_checking.Every(
						type_checking.IntersectionTypeParts(t),
						func(t *checker.Type) bool {
							return !isLiteralLikeType(t)
						},
					)
				},
			)
		}

		getSwitchMetadata := func(node *ast.SwitchStatement) *switchMetadata {
			cases := node.CaseBlock.AsCaseBlock().Clauses.Nodes
			defaultCaseIndex := slices.IndexFunc(cases, func(clause *ast.Node) bool {
				return clause.Kind == ast.KindDefaultClause
			})
			var defaultCase *ast.CaseOrDefaultClause
			if defaultCaseIndex > -1 {
				defaultCase = cases[defaultCaseIndex].AsCaseOrDefaultClause()
			}

			discriminantType := type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, node.Expression)

			caseTypes := make([]*checker.Type, 0, len(cases))
			for _, c := range cases {
				if c.Kind == ast.KindDefaultClause {
					continue
				}

				caseTypes = append(caseTypes, type_checking.GetConstrainedTypeAtLocation(ctx.TypeChecker, c.AsCaseOrDefaultClause().Expression))
			}

			containsNonLiteralType := doesTypeContainNonLiteralType(discriminantType)

			missingLiteralBranchTypes := make([]*checker.Type, 0, 10)
			type_checking.TypeRecurser(discriminantType, func(t *checker.Type) bool {
				if slices.Contains(caseTypes, t) || !isLiteralLikeType(t) {
					return false
				}

				if slices.ContainsFunc(caseTypes, func(t *checker.Type) bool {
					return type_checking.IsTypeFlagSet(t, checker.TypeFlagsUndefined)
				}) && type_checking.IsTypeFlagSet(t, checker.TypeFlagsUndefined) {
					return false
				}

				missingLiteralBranchTypes = append(missingLiteralBranchTypes, t)

				return false
			})

			metadata := &switchMetadata{
				ContainsNonLiteralType:    containsNonLiteralType,
				DefaultCase:               defaultCase,
				MissingLiteralBranchTypes: missingLiteralBranchTypes,
			}
			if defaultCase == nil {
				metadata.DefaultCaseComment = defaultCaseComment(ctx, node, commentPattern)
			}
			return metadata
		}

		checkSwitchExhaustive := func(node *ast.SwitchStatement, metadata *switchMetadata) {

			if *opts.ConsiderDefaultExhaustiveForUnions && metadata.hasDefaultCase() {
				return
			}

			if len(metadata.MissingLiteralBranchTypes) > 0 {
				ctx.ReportNode(node.Expression, buildSwitchIsNotExhaustiveMessage(
					renderMissingBranches(ctx.TypeChecker, metadata.MissingLiteralBranchTypes)))
			}
		}

		checkSwitchUnnecessaryDefaultCase := func(metadata *switchMetadata) {
			if *opts.AllowDefaultCaseForExhaustiveSwitch {
				return
			}

			if len(metadata.MissingLiteralBranchTypes) == 0 &&
				metadata.hasDefaultCase() &&
				!metadata.ContainsNonLiteralType {
				if metadata.DefaultCase != nil {
					ctx.ReportNode(&metadata.DefaultCase.Node, buildDangerousDefaultCaseMessage())
				} else {
					ctx.ReportRange(metadata.DefaultCaseComment.Range, buildDangerousDefaultCaseMessage())
				}
			}
		}
		checkSwitchNoUnionDefaultCase := func(node *ast.SwitchStatement, metadata *switchMetadata) {
			if !*opts.RequireDefaultForNonUnion {
				return
			}

			if metadata.ContainsNonLiteralType && !metadata.hasDefaultCase() {
				ctx.ReportNode(node.Expression, buildSwitchIsNotExhaustiveMessage("default"))

			}
		}

		return rule.Listeners{
			ast.KindSwitchStatement: func(node *ast.Node) {
				if ctx.TypeChecker == nil {
					return
				}

				stmt := node.AsSwitchStatement()

				metadata := getSwitchMetadata(stmt)
				checkSwitchExhaustive(stmt, metadata)
				checkSwitchUnnecessaryDefaultCase(metadata)
				checkSwitchNoUnionDefaultCase(stmt, metadata)
			},
		}
	},
}

