func All(sourceFile *ast.SourceFile) []Comment {
	if sourceFile == nil {
		return nil
	}
	text := sourceFile.Text()

	var factory ast.NodeFactory
	seenRanges := make(map[core.TextRange]bool)
	var comments []Comment

	record := func(commentRange ast.CommentRange) {
		if seenRanges[commentRange.TextRange] {
			return
		}
		seenRanges[commentRange.TextRange] = true

		start, end := commentRange.Pos(), commentRange.End()
		if start < 0 || end > len(text) || start >= end {
			return
		}
		startLine, startColumn := scanner.GetECMALineAndByteOffsetOfPosition(sourceFile, start)
		endLine, _ := scanner.GetECMALineAndByteOffsetOfPosition(sourceFile, end)

		comments = append(comments, Comment{
			Range:       commentRange.TextRange,
			IsBlock:     commentRange.Kind == ast.KindMultiLineCommentTrivia,
			Text:        text[start:end],
			StartLine:   startLine,
			StartColumn: startColumn,
			EndLine:     endLine,
		})
	}

	scannedPositions := make(map[int]bool)

	collectAt := func(position int) {
		if position < 0 || position > len(text) {
			return
		}

		if !canBeginAt(text, position) {
			return
		}
		if scannedPositions[position] {
			return
		}
		scannedPositions[position] = true
		for commentRange := range scanner.GetLeadingCommentRanges(&factory, text, position) {
			record(commentRange)
		}
		for commentRange := range scanner.GetTrailingCommentRanges(&factory, text, position) {
			record(commentRange)
		}
	}

	collectAt(0)

	var visit func(node *ast.Node)
	visit = func(node *ast.Node) {
		if node == nil {
			return
		}

		collectAt(node.Pos())
		collectAt(node.End())

		collectListInteriors(node, collectAt)
		node.ForEachChild(func(child *ast.Node) bool {
			visit(child)
			return false
		})
	}
	visit(sourceFile.AsNode())

	collectAt(sourceFile.EndOfFileToken.Pos())

	sortByPosition(comments)
	return comments
}

func All() []rule.Rule {
	registrations := rule.Registered()
	rules := make([]rule.Rule, 0, len(registrations))
	for _, registration := range registrations {
		rules = append(rules, registration.Rule)
	}
	return rules
}

Build.Declaration:
func Build[E any](root *ast.Node, hooks Hooks[E]) *Graph[E] {
	b := &Builder[E]{hooks: hooks, blocks: make([]*Block[E], 0, blockChunkSize)}
	b.cur = b.newBlock()
	b.cur.hasIncoming = true
	b.cur.Reachable = true

	switch root.Kind {
	case ast.KindSourceFile:
		b.statements(root.AsSourceFile().Statements)

	case ast.KindClassStaticBlockDeclaration:
		b.statement(root.AsClassStaticBlockDeclaration().Body)

	case ast.KindPropertyDeclaration:
		b.expr(root.AsPropertyDeclaration().Initializer)

	default:
		for _, parameter := range root.Parameters() {
			b.parameter(parameter)
		}

		b.expr(root.Type())
		if body := root.Body(); body != nil {
			if body.Kind == ast.KindBlock {
				b.statement(body)
			} else {
				b.expr(body)
			}
		}
	}

	endReachable := b.cur.Reachable
	if endReachable {
		b.markFinal(b.cur)
	}
	return &Graph[E]{
		Blocks:       b.blocks,
		FinalBlocks:  b.finals,
		ThrownBlocks: b.thrown,
		EndReachable: endReachable,
	}
}

func Build(files []*ast.SourceFile) *Set {
	roots := &Set{}

	seen := map[string]bool{}
	for _, file := range files {
		for _, directory := range computedImportDirectories(file) {
			if !seen[directory] {
				seen[directory] = true
				roots.dynamicImportDirectories = append(roots.dynamicImportDirectories, directory)
			}
		}
	}
	return roots
}

func Build(sourceText string) *Index {
	lineOf := buildLineIndex(sourceText)
	found := []*Directive{}
	references := []RuleReference{}

	for _, comment := range scanComments(sourceText) {
		commentText := sourceText[comment.pos:comment.end]
		parsed := parseDirective(commentText)
		if parsed == nil {
			if names, isEnable := directives.ParseEnable(commentText); isEnable {
				for _, name := range names {
					references = append(references, RuleReference{Name: name, Pos: comment.pos, End: comment.end})
				}
			}
			continue
		}
		for _, name := range parsed.Rules {
			references = append(references, RuleReference{Name: name, Pos: comment.pos, End: comment.end})
		}

		parsed.Pos = comment.pos
		parsed.End = comment.end
		parsed.Line = lineOf(comment.pos)

		switch parsed.Kind {
		case KindNextLine:
			parsed.StartLine = parsed.Line + 1
			parsed.EndLine = parsed.Line + 1
		case KindSameLine:
			parsed.StartLine = parsed.Line
			parsed.EndLine = parsed.Line
		case KindFile:

			parsed.StartLine = parsed.Line
			parsed.EndLine = lineOf(len(sourceText))
		}

		found = append(found, parsed)
	}

	resolveFileScopeEnds(found, sourceText, lineOf)

	return &Index{directives: found, ruleReferences: references, lineOf: lineOf}
}

