func Compare(root string, files []string, newOracle NewFormatter, newCandidate NewFormatter, workers int, cache *OracleCache) (Report, error) {
	if workers < 1 {
		workers = 1
	}

	results := make([]FileResult, len(files))
	indexes := make(chan int)
	errs := make(chan error, workers)
	var group sync.WaitGroup

	for worker := 0; worker < workers; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			oracle, err := newOracle()
			if err != nil {
				errs <- fmt.Errorf("building the oracle: %w", err)
				return
			}
			candidate, err := newCandidate()
			if err != nil {
				errs <- fmt.Errorf("building the candidate: %w", err)
				return
			}
			for index := range indexes {
				results[index] = compareOne(files[index], oracle, candidate, cache)
			}
		}()
	}

	for index := range files {
		select {
		case err := <-errs:
			close(indexes)
			group.Wait()
			return Report{}, err
		case indexes <- index:
		}
	}
	close(indexes)
	group.Wait()
	select {
	case err := <-errs:
		return Report{}, err
	default:
	}

	report := Report{Root: root, ByLanguage: map[string]*Tally{}, Files: results}
	for _, result := range results {
		tally := report.ByLanguage[result.Language]
		if tally == nil {
			tally = &Tally{}
			report.ByLanguage[result.Language] = tally
		}
		switch result.Outcome {
		case Identical:
			tally.Identical++
		case Different:
			tally.Different++
		case CandidateRefused:
			tally.CandidateRefused++
		case OracleFailed:
			tally.OracleFailed++
			continue
		}
		if result.OracleRewrites {
			tally.RewriteTotal++
			if result.Outcome == Identical {
				tally.RewriteIdentical++
			}
		}
	}
	return report, nil
}

func Compare(expected Expectation, result Result) FixtureScore {
	type pair struct {
		Heading string
		Message string
		Line    int
	}

	want := map[pair]int{}
	for _, expectedError := range expected.Errors {
		want[pair{expectedError.Heading, expectedError.Message, expectedError.Line}]++
	}
	got := map[pair]int{}
	for _, reportedError := range result.Errors {
		got[pair{reportedError.Heading, reportedError.Message, reportedError.Line}]++
	}

	var missing, unexpected []string
	for key, count := range want {
		if got[key] < count {
			missing = append(missing, fmt.Sprintf("%s: %s (line %d) x%d", key.Heading, key.Message, key.Line, count-got[key]))
		}
	}
	for key, count := range got {
		if want[key] < count {
			unexpected = append(unexpected, fmt.Sprintf("%s: %s (line %d) x%d", key.Heading, key.Message, key.Line, count-want[key]))
		}
	}
	sort.Strings(missing)
	sort.Strings(unexpected)

	verdict := FixtureScore{
		ExpectedErrors: expected.Errors,
		ReportedErrors: result.Errors,
	}
	if len(missing) == 0 && len(unexpected) == 0 {
		verdict.Outcome = OutcomePassed
		return verdict
	}

	verdict.Outcome = OutcomeFailed
	var detail []string
	if len(missing) > 0 {
		detail = append(detail, "missing: "+strings.Join(missing, "; "))
	}
	if len(unexpected) > 0 {
		detail = append(detail, "unexpected: "+strings.Join(unexpected, "; "))
	}
	verdict.Detail = strings.Join(detail, " | ")
	return verdict
}

func Compare(tailwindVersion string, systems []SystemCases, divergence SystemDivergence, goSide ReadingSource, controls []Control) Report {
	report := Report{
		TailwindVersion:  tailwindVersion,
		GoSideName:       goSide.Name(),
		SystemDivergence: divergence,
	}

	for _, system := range systems {
		population := Population{SystemName: system.SystemName, ByOutcome: map[Outcome]int{}}

		for _, aCase := range system.Cases {

			switch aCase.Population {
			case PopulationCorpus:
				population.CorpusClasses++
			case PopulationRegistry:
				population.RegistryClasses++
			default:
				population.UnknownPopulationClasses++
			}
			if !aCase.EngineAnswered {
				population.EngineNullReadings++
			}

			goReading, goAnswered := goSide.Reading(aCase.ClassName)
			outcome := classify(aCase, goReading, goAnswered)
			population.ByOutcome[outcome]++
			if outcome == OutcomeAgreed {
				continue
			}
			report.Divergences = append(report.Divergences, Divergence{
				ClassName:      aCase.ClassName,
				Population:     aCase.Population,
				Outcome:        outcome,
				EngineReading:  aCase.EngineReading,
				EngineAnswered: aCase.EngineAnswered,
				GoReading:      goReading,
				GoAnswered:     goAnswered,
			})
		}

		report.Populations = append(report.Populations, population)
	}

	for _, control := range controls {
		report.Controls = append(report.Controls, runControl(systems, goSide, control, &report))
	}

	return report
}

