func Register(extension string, print Print) {
	mutex.Lock()
	defer mutex.Unlock()
	extension = strings.ToLower(extension)
	if _, taken := printers[extension]; taken {
		panic(fmt.Sprintf("native: %s is registered twice", extension))
	}
	printers[extension] = print
}

func Register(registrations ...Registration) {
	registeredMutex.Lock()
	defer registeredMutex.Unlock()

	for _, registration := range registrations {
		name := registration.Rule.Name
		if name == "" {
			panic("rule.Register: a rule was registered with an empty name, so the config could never address it")
		}
		decoders := 0
		for _, set := range []bool{registration.Decode != nil, registration.DecodeOptionList != nil, registration.DecodeAt != nil} {
			if set {
				decoders++
			}
		}
		if decoders > 1 {
			panic(fmt.Sprintf(
				"rule.Register: %q sets more than one of Decode, DecodeOptionList and DecodeAt; the "+
					"config layer reads which one is set as the rule's option arity, so two is a contradiction",
				name,
			))
		}
		if existing, taken := registered[name]; taken {
			panic(fmt.Sprintf(
				"rule.Register: two rules answer to %q (%T and %T); the config addresses rules by "+
					"name, so one of them would be permanently unreachable while its tests passed",
				name, existing.Rule.Run, registration.Rule.Run,
			))
		}
		registered[name] = registration
	}
}

Run.Declaration:
func Run(fixtures []Fixture, implementation Implementation, options Options) (Score, error) {
	score := Score{Considered: len(fixtures)}

	for _, fixture := range fixtures {
		if err := CheckPragmas(fixture.Name, fixture.Pragmas); err != nil {
			return Score{}, err
		}
	}

	for _, fixture := range fixtures {
		if options.SkipFlowFixtures && fixture.RequiresFlow() {
			score.Excluded++
			score.Fixtures = append(score.Fixtures, FixtureScore{
				Name:    fixture.Name,
				Outcome: OutcomeExcluded,
				Detail:  "requires a Flow parser (`@flow` in source, upstream's own test)",
			})
			continue
		}

		result, err := implementation.Analyze(fixture)
		if err != nil {
			var unsupported *ErrUnsupported
			if asUnsupported(err, &unsupported) {
				score.Declined++
				score.Fixtures = append(score.Fixtures, FixtureScore{
					Name:           fixture.Name,
					Outcome:        OutcomeDeclined,
					Detail:         unsupported.Reason,
					ExpectedErrors: fixture.Expected.Errors,
				})
				continue
			}
			return Score{}, fmt.Errorf("%s: %w", fixture.Name, err)
		}

		verdict := Compare(fixture.Expected, result)
		verdict.Name = fixture.Name
		switch verdict.Outcome {
		case OutcomePassed:
			score.Passed++
		default:
			score.Failed++
		}
		score.Fixtures = append(score.Fixtures, verdict)
	}

	if err := score.Check(); err != nil {
		return Score{}, err
	}
	return score, nil
}

