	status := memoryStatus{length: uint32(unsafe.Sizeof(memoryStatus{}))}
	if succeeded, _, err := globalMemoryStatus.Call(uintptr(unsafe.Pointer(&status))); succeeded == 0 {
		return 0, err
	}
	return status.availablePhysical, nil
}

