func calleeName(callee *ast.Node) string {
	callee = ast.SkipParentheses(callee)
	switch callee.Kind {
	case ast.KindIdentifier:
		return callee.Text()
	case ast.KindPropertyAccessExpression:
		name, _ := property.Name(callee.AsPropertyAccessExpression().Name(), property.Named|property.Private)
		return name
	case ast.KindElementAccessExpression:
		name, _ := property.Name(callee.AsElementAccessExpression().ArgumentExpression, property.Quoted|property.Templated|property.Numeric)
		return name
	}
	return ""
}

func calleeName(callee *ast.Node) string {
	callee = unwrapAssertions(callee)
	if callee == nil {
		return ""
	}
	if callee.Kind == ast.KindIdentifier {
		return callee.Text()
	}
	if callee.Kind == ast.KindPropertyAccessExpression {
		if name := callee.AsPropertyAccessExpression().Name(); name != nil {
			return name.Text()
		}
	}
	return ""
}

func calleeName(callee *ast.Expression) string {
	if callee == nil {
		return ""
	}
	switch callee.Kind {
	case ast.KindIdentifier:
		return callee.Text()
	case ast.KindPropertyAccessExpression:

		name, ok := ast.TryGetTextOfPropertyName(callee.AsPropertyAccessExpression().Name())
		if !ok {
			return ""
		}
		return name
	case ast.KindElementAccessExpression:

		argument := callee.AsElementAccessExpression().ArgumentExpression
		if argument == nil {
			return ""
		}
		if argument.Kind != ast.KindStringLiteral &&
			argument.Kind != ast.KindNoSubstitutionTemplateLiteral {
			return ""
		}
		return argument.Text()
	}
	return ""
}

func calleeName(callee *ast.Node) string {
	switch callee.Kind {
	case ast.KindIdentifier:
		return callee.Text()
	case ast.KindPropertyAccessExpression:
		access := callee.AsPropertyAccessExpression()
		if access.Expression == nil || access.Expression.Kind == ast.KindSuperKeyword {
			return ""
		}
		if access.Name() != nil && access.Name().Kind == ast.KindIdentifier {
			return access.Name().Text()
		}
	case ast.KindElementAccessExpression:
		access := callee.AsElementAccessExpression()
		if access.Expression == nil || access.Expression.Kind == ast.KindSuperKeyword {
			return ""
		}
		if access.ArgumentExpression != nil && access.ArgumentExpression.Kind == ast.KindStringLiteral {
			return access.ArgumentExpression.Text()
		}
	}
	return ""
}

