func embed(path *astPath, _ *printerOptions) func(printing.TextToDoc, printing.PrintFunc, *astPath, *printerOptions) (doc.Doc, error) {
	node := currentNode(path)
	if !isFrontMatter(node) || !supportedEmbedFrontMatterLanguages[node.String("language")] {
		return nil
	}

	return func(textToDoc printing.TextToDoc, _ printing.PrintFunc, _ *astPath, _ *printerOptions) (doc.Doc, error) {
		language := node.String("language")
		value := trim(node.String("value"))

		var embedded doc.Doc = doc.Text("")
		if value != "" {
			if language != "yaml" {
				return nil, nil
			}
			formatted, err := textToDoc(value, language)
			if err != nil {
				return nil, err
			}
			embedded = formatted
		}

		return doc.MarkAsRoot(doc.Concat{
			doc.Text(node.String("startDelimiter")),
			doc.Text(node.String("explicitLanguage")),
			doc.Hardline,
			embedded,
			choose(value != "", func() doc.Doc { return doc.Hardline }),
			doc.Text(node.String("endDelimiter")),
		}), nil
	}
}

func embed(path *Path, options *Options) embedPrint {
	current := node(path)
	if !current.Is("TemplateLiteral") ||

		hasInvalidCookedValue(current) {
		return nil
	}

	var printer *embedPrinter
	for index := range embedPrinters {
		if embedPrinters[index].test(path) {
			printer = &embedPrinters[index]
			break
		}
	}
	if printer == nil {
		return nil
	}

	if quasis := current.List("quasis"); len(quasis) == 1 && estree.TrimJavaScript(templateElementRaw(quasis[0])) == "" {
		return func(printing.TextToDoc, PrintFunc, *Path, *Options) (Doc, error) { return doc.Text("``"), nil }
	}

	return createTemplateLiteralPrint(printer.print)
}

func embed(path *astPath, _ *options) embedPrint {
	node := currentNode(path)

	if node.NodeType == "frontMatter" {
		return embedFrontMatter(node)
	}

	if node.NodeType != "code" {
		return nil
	}
	if node.Lang == nil || *node.Lang == "" {
		return nil
	}
	language := *node.Lang

	var parser string

	switch language {
	case "angular-ts":
		parser = inferParserForLanguage("typescript")
	case "angular-html":
		parser = "angular"
	default:
		parser = inferParserForLanguage(language)
	}

	if parser == "" {
		return nil
	}

	return func(textToDoc printing.TextToDoc, _ printing.PrintFunc, _ *astPath, _ *options) (doc.Doc, error) {

		parserOrFile := parser
		switch language {
		case "ts", "typescript":
			parserOrFile = "dummy.ts"
		case "tsx":
			parserOrFile = "dummy.tsx"
		}

		embedded, err := textToDoc(node.Value, parserOrFile)
		if err != nil {
			return nil, err
		}

		style := fenceStyle(node.Value)
		meta := ""
		if node.Meta != nil && *node.Meta != "" {
			meta = " " + *node.Meta
		}

		return doc.MarkAsRoot(doc.Concat{
			doc.Text(style),
			doc.Text(language),
			doc.Text(meta),
			doc.Hardline,
			doc.ReplaceEndOfLine(embedded, doc.Literalline),
			doc.Hardline,
			doc.Text(style),
		}), nil
	}
}

func embed(path *astPath, options *options) embedPrint {
	node := currentNode(path)
	settings := settingsOf(options)

	if node.NodeType == "root" && settings.filePath != "" && prettierRcPattern.MatchString(settings.filePath) {
		return func(textToDoc printing.TextToDoc, _ printing.PrintFunc, _ *astPath, _ *printing.Options[*unist.Node]) (doc.Doc, error) {
			embedded, err := textToDoc(options.OriginalText, "json")
			if err != nil {
				return nil, err
			}

			if text, isText := embedded.(doc.Text); embedded == nil || (isText && text == "") {
				return nil, nil
			}
			return doc.Concat{embedded, doc.Hardline}, nil
		}
	}
	return nil
}

