func generate() ([]byte, error) {
	bundles, err := prettier.Bundles()
	if err != nil {
		return nil, err
	}
	markdown := string(bundles.Files["plugins/markdown.js"])

	matches := punctuationPattern.FindAllStringSubmatch(markdown, -1)
	if len(matches) != 1 {
		return nil, fmt.Errorf("found %d candidates for micromark's unicodePunctuation class in the markdown bundle, want exactly 1", len(matches))
	}

	runtime := goja.New()
	punctuation, err := unitRanges(runtime, matches[0][1], "u")
	if err != nil {
		return nil, err
	}
	whitespace, err := unitRanges(runtime, `\s`, "")
	if err != nil {
		return nil, err
	}

	for _, probe := range []struct {
		ranges [][2]int
		unit   int
		want   bool
	}{
		{punctuation, '!', true}, {punctuation, '$', true}, {punctuation, 0x00A9, true},
		{punctuation, 'a', false}, {punctuation, '7', false},
		{whitespace, ' ', true}, {whitespace, 0x00A0, true}, {whitespace, 'a', false},
	} {
		if contains(probe.ranges, probe.unit) != probe.want {
			return nil, fmt.Errorf("control failed: U+%04X answered %v, want %v", probe.unit, !probe.want, probe.want)
		}
	}

	var source bytes.Buffer
	source.WriteString("// Code generated by generate_characters. DO NOT EDIT.\n//\n")
	source.WriteString("// Captured from the embedded markdown bundle, run by goja: the fork's rewritten `\\p{P}|\\p{S}` and goja's\n")
	source.WriteString("// own `\\s`, each asked about every UTF-16 code unit. Regenerate with:\n//\n")
	source.WriteString("//\tgo run ./internal/format/markdown/micromark/tools/generate_characters\n\n")
	source.WriteString("package micromark\n\n")
	writeRanges(&source, "unicodePunctuationRanges", "are the code units micromark's unicodePunctuation accepts.", punctuation)
	writeRanges(&source, "unicodeWhitespaceRanges", "are the code units micromark's unicodeWhitespace accepts.", whitespace)

	return format.Source(source.Bytes())
}

func generate() ([]byte, error) {
	bundles, err := prettier.Bundles()
	if err != nil {
		return nil, err
	}
	markdown := string(bundles.Files["plugins/markdown.js"])

	start := -1
	for offset := 0; ; {
		index := strings.Index(markdown[offset:], anchor)
		if index < 0 {
			break
		}
		index += offset
		if !strings.HasSuffix(markdown[:index], "exports=") {
			if start >= 0 {
				return nil, fmt.Errorf("found two ES module copies of the character-entities table, want exactly 1")
			}
			start = index
		}
		offset = index + len(anchor)
	}
	if start < 0 {
		return nil, fmt.Errorf("found no ES module copy of the character-entities table")
	}

	runtime := goja.New()
	var entities map[string]string
	for end := start + len(anchor); end < len(markdown); end++ {
		if markdown[end] != '}' {
			continue
		}
		value, err := runtime.RunString("JSON.stringify((" + markdown[start:end+1] + "))")
		if err != nil {
			continue
		}
		if err := json.Unmarshal([]byte(value.String()), &entities); err != nil {
			return nil, err
		}
		break
	}

	if len(entities) < 2000 {
		return nil, fmt.Errorf("decoded %d entities, want the full table of over 2000", len(entities))
	}
	for name, want := range map[string]string{"amp": "&", "copy": "©", "AElig": "Æ", "ngE": "≧̸"} {
		if entities[name] != want {
			return nil, fmt.Errorf("control failed: %s decoded to %q, want %q", name, entities[name], want)
		}
	}

	names := make([]string, 0, len(entities))
	for name := range entities {
		names = append(names, name)
	}
	sort.Strings(names)

	var source bytes.Buffer
	source.WriteString("// Code generated by generate_entities. DO NOT EDIT.\n//\n")
	source.WriteString("// The character-entities table, cut out of the embedded markdown bundle and evaluated by goja.\n")
	source.WriteString("// Regenerate with:\n//\n//\tgo run ./internal/format/markdown/micromark/tools/generate_entities\n\n")
	source.WriteString("package micromark\n\n")
	source.WriteString("// characterEntities maps a reference name, without `&` and `;`, to what it decodes to.\n")
	source.WriteString("var characterEntities = map[string]string{\n")
	for _, name := range names {
		fmt.Fprintf(&source, "\t%q: %q,\n", name, entities[name])
	}
	source.WriteString("}\n")

	return format.Source(source.Bytes())
}

func generate() ([]byte, error) {
	bundles, err := prettier.Bundles()
	if err != nil {
		return nil, err
	}
	markdown := string(bundles.Files["plugins/markdown.js"])

	splitStart := strings.Index(markdown, `.split(/([\t\n ]+)/)`)
	if splitStart < 0 || strings.Count(markdown, `.split(/([\t\n ]+)/)`) != 1 {
		return nil, fmt.Errorf("could not find splitText's split exactly once")
	}
	splitText := markdown[splitStart : splitStart+1500]

	name := func(pattern *regexp.Regexp, what string) (string, error) {
		match := pattern.FindStringSubmatch(splitText)
		if match == nil {
			return "", fmt.Errorf("could not find how splitText uses %s", what)
		}
		return match[1], nil
	}
	cjkName, err := name(cjkUse, "CJK_REGEXP")
	if err != nil {
		return nil, err
	}
	punctuationName, err := name(punctuationUse, "PUNCTUATION_REGEXP")
	if err != nil {
		return nil, err
	}
	hangulName, err := name(hangulUse, "the Hangul regex")
	if err != nil {
		return nil, err
	}

	cjkLiteral, err := literal(markdown, cjkName)
	if err != nil {
		return nil, err
	}
	punctuationLiteral, err := literal(markdown, punctuationName)
	if err != nil {
		return nil, err
	}
	hangulLiteral, err := literal(markdown, hangulName)
	if err != nil {
		return nil, err
	}

	cjkParts := regexp.MustCompile(`^\(\?:(\[.*\])\)\(\?:(\[.*\])\)\?$`).FindStringSubmatch(cjkLiteral)
	if cjkParts == nil {
		return nil, fmt.Errorf("CJK_REGEXP does not have the shape (?:[...])(?:[...])?: %.80s", cjkLiteral)
	}

	spaces := spaceUse.FindAllStringSubmatch(markdown, -1)
	if len(spaces) == 0 {
		return nil, fmt.Errorf("could not find the space-separator class")
	}
	for _, space := range spaces[1:] {
		if space[1] != spaces[0][1] {
			return nil, fmt.Errorf("the space-separator class differs between uses")
		}
	}

	runtime := goja.New()
	classes := []struct {
		name        string
		description string
		pattern     string
	}{
		{"cjkRanges", "are the code points CJK_REGEXP's main class matches.", cjkParts[1]},
		{"variationSelectorRanges", "are the code points CJK_REGEXP's optional second class matches.", cjkParts[2]},
		{"punctuationRanges", "are the code points PUNCTUATION_REGEXP matches.", punctuationLiteral},
		{"hangulRanges", "are the code points the printer's Hangul test matches.", hangulLiteral},
		{"spaceSeparatorRanges", "are the code points of the class `[\\p{Space_Separator}\\t\\n\\f\\r]` was rewritten to.", spaces[0][1]},
	}

	var source bytes.Buffer
	source.WriteString("// Code generated by generate_classes. DO NOT EDIT.\n//\n")
	source.WriteString("// Captured from the embedded markdown bundle, run by goja: the rewritten classes the printer splits and\n")
	source.WriteString("// wraps prose by, each asked about every code point. Regenerate with:\n//\n")
	source.WriteString("//\tgo run ./internal/format/markdown/tools/generate_classes\n\n")
	source.WriteString("package markdown\n\n")

	answers := map[string][][2]int{}
	for _, class := range classes {
		ranges, err := codePointRanges(runtime, class.pattern)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", class.name, err)
		}
		answers[class.name] = ranges
		fmt.Fprintf(&source, "// %s %s\nvar %s = [][2]rune{\n", class.name, class.description, class.name)
		for _, entry := range ranges {
			fmt.Fprintf(&source, "\t{0x%04X, 0x%04X},\n", entry[0], entry[1])
		}
		source.WriteString("}\n\n")
	}

	for _, probe := range []struct {
		class string
		point int
		want  bool
	}{
		{"cjkRanges", 0x4E2D, true}, {"cjkRanges", 'a', false},
		{"variationSelectorRanges", 0xFE0F, true}, {"variationSelectorRanges", 'a', false},
		{"punctuationRanges", '!', true}, {"punctuationRanges", 0x3002, true}, {"punctuationRanges", 'a', false},
		{"hangulRanges", 0xAC00, true}, {"hangulRanges", 0x4E2D, false},
		{"spaceSeparatorRanges", ' ', true}, {"spaceSeparatorRanges", 0x3000, true}, {"spaceSeparatorRanges", 'a', false},
	} {
		if contains(answers[probe.class], probe.point) != probe.want {
			return nil, fmt.Errorf("control failed: %s U+%04X answered %v, want %v", probe.class, probe.point, !probe.want, probe.want)
		}
	}

	return format.Source(source.Bytes())
}

func generate() ([]byte, error) {
	bundles, err := prettier.Bundles()
	if err != nil {
		return nil, err
	}
	runtime := goja.New()
	for _, name := range prettier.BundleFiles {
		if _, err := runtime.RunString(string(bundles.Files[name])); err != nil {
			return nil, fmt.Errorf("evaluating %s: %w", name, err)
		}
	}

	value, err := runtime.RunString(`
		JSON.stringify(
			Object.values(prettierPlugins)
				.toReversed()
				.flatMap((plugin) => plugin.languages ?? [])
				.map((language) => ({
					name: language.name,
					aliases: language.aliases ?? [],
					extensions: language.extensions ?? [],
					parser: language.parsers[0],
				})),
		)
	`)
	if err != nil {
		return nil, err
	}
	var languages []language
	if err := json.Unmarshal([]byte(value.String()), &languages); err != nil {
		return nil, err
	}

	byName := map[string]string{}
	for _, language := range languages {
		byName[language.Name] = language.Parser
	}
	for name, parser := range map[string]string{"TypeScript": "typescript", "JSON": "json", "Markdown": "markdown", "YAML": "yaml"} {
		if byName[name] != parser {
			return nil, fmt.Errorf("control failed: %s answered %q, want %q", name, byName[name], parser)
		}
	}

	var source bytes.Buffer
	source.WriteString("// Code generated by generate_languages. DO NOT EDIT.\n//\n")
	source.WriteString("// Captured from the embedded bundles, run by goja: the languages inferParser searches, in its order.\n")
	source.WriteString("// Regenerate with:\n//\n")
	source.WriteString("//\tgo run ./internal/format/markdown/tools/generate_languages\n\n")
	source.WriteString("package markdown\n\n")
	source.WriteString("// inferableLanguages are options.plugins reversed and flattened into their languages, each with its\n")
	source.WriteString("// first parser.\n")
	source.WriteString("var inferableLanguages = []inferableLanguage{\n")
	for _, language := range languages {
		fmt.Fprintf(&source, "\t{name: %s, aliases: %s, extensions: %s, parser: %s},\n",
			strconv.Quote(language.Name), quoteAll(language.Aliases), quoteAll(language.Extensions), strconv.Quote(language.Parser))
	}
	source.WriteString("}\n")

	return format.Source(source.Bytes())
}

func generate(systems []system, packageName string) ([]byte, generationStats) {
	stats := generationStats{}
	pool := newReadingPool()

	rootIndex := make([]map[string]*rootEntry, len(systems))
	for index := range systems {
		rootIndex[index] = make(map[string]*rootEntry, len(systems[index].table.Roots))
		for entryIndex := range systems[index].table.Roots {
			entry := &systems[index].table.Roots[entryIndex]
			rootIndex[index][entry.Root] = entry
		}
	}
	sharedRoots := make([]string, 0, len(rootIndex[0]))
	for root := range rootIndex[0] {
		shared := true
		for index := 1; index < len(rootIndex); index++ {
			if _, found := rootIndex[index][root]; !found {
				shared = false
				break
			}
		}
		if shared {
			sharedRoots = append(sharedRoots, root)
			continue
		}
		stats.rootsDropped++
	}
	sort.Strings(sharedRoots)

	frameworkNamespaces := map[string]bool{}
	for _, root := range sharedRoots {
		for _, axis := range axes {
			maps := make([]map[string]*reading, len(systems))
			for index := range systems {
				maps[index] = axis.byNamespace(rootIndex[index][root])
			}
			for key, value := range maps[0] {
				if key == namespaceColorKeyword || key == namespaceNone {
					continue
				}
				if sameEverywhere(maps, key, value) {
					frameworkNamespaces[key] = true
				}
			}
		}
	}

	for _, root := range sharedRoots {
		for _, axis := range axes {
			for index := range systems {
				entry := rootIndex[index][root]
				namespaceMap := axis.byNamespace(entry)
				noneReading := namespaceMap[namespaceNone]
				maps := make([]map[string]*reading, len(systems))
				for other := range systems {
					maps[other] = axis.byNamespace(rootIndex[other][root])
				}
				for key, value := range namespaceMap {
					if key == namespaceColorKeyword || key == namespaceNone {
						continue
					}
					switch {
					case sameEverywhere(maps, key, value):
						stats.consumedBuckets++
					case readingKey(value) == readingKey(noneReading):
						stats.noneBuckets++
					default:
						stats.violations++
						fmt.Fprintf(os.Stderr,
							"generate_descriptor_base: %s %s namespace %q reads %s, which is neither shared by every system nor equal to its axis @none (%s)\n",
							root, axis.goName, key, readingKey(value), readingKey(noneReading))
					}
				}
			}
		}
	}

	if stats.violations > 0 {
		fmt.Fprintf(os.Stderr, "generate_descriptor_base: %d namespace buckets fit neither half of the split; refusing to generate\n", stats.violations)
		os.Exit(4)
	}

	stats.roots = len(sharedRoots)
	stats.frameworkNamespaces = len(frameworkNamespaces)

	var rootsBuffer bytes.Buffer
	for _, root := range sharedRoots {
		writeDescriptor(&rootsBuffer, rootIndex[0][root], frameworkNamespaces, pool)
	}

	staticSets := make([]map[string]*reading, len(systems))
	for index := range systems {
		staticSets[index] = make(map[string]*reading, len(systems[index].table.Statics))
		for name, value := range systems[index].context.UnlistedStatics {
			staticSets[index][name] = value
		}

		for name, value := range systems[index].table.Statics {
			staticSets[index][name] = value
		}
	}
	staticNames := make([]string, 0, len(staticSets[0]))
	for name, value := range staticSets[0] {
		if value == nil {
			continue
		}
		shared := true
		for index := 1; index < len(staticSets); index++ {
			other, found := staticSets[index][name]
			if !found || other == nil || readingKey(other) != readingKey(value) {
				shared = false
				break
			}
		}
		if shared {
			staticNames = append(staticNames, name)
			continue
		}
		stats.staticsDropped++
	}
	sort.Strings(staticNames)
	stats.statics = len(staticNames)

	var staticsBuffer bytes.Buffer
	for _, name := range staticNames {
		fmt.Fprintf(&staticsBuffer, "\t%q: baseReadings[%d],\n", name, pool.intern(staticSets[0][name]))
	}

	stats.distinctReadings = len(pool.readings)

	var body bytes.Buffer
	sources := make([]string, 0, len(systems))
	for index := range systems {
		sources = append(sources, jsonPathComment(systems[index].table.EntryPoint))
	}
	fmt.Fprintf(&body, `// Code generated by internal/lint/rules/tailwind/tools/generate_descriptor_base. DO NOT EDIT.
//
// Generated against Tailwind %s from %d design systems: %s.
//
// This is the half of the descriptor table that is a fact about Tailwind rather than about any one
// repository, and it is checked in because it was measured to be invariant rather than assumed to
// be. The other half — which theme namespaces exist, which keys are in them, and the repository's
// own `+"`@utility`"+` blocks — is read off the live design system by NewTable in descriptor_live.go.
//
// The seam is measured, and the measurement is the reason the split is exactly here:
//
//   - %d roots registered by every system, agreeing on TypeList, ByType, ByLiteral, the fallbacks
//     and the empties. Against a synthetic third system sharing no submodule with the corpus
//     repositories, 258 of 301 shared roots differ, and every one of them differs *only* in its
//     namespace maps.
//   - %d namespace buckets consumed identically by every system, keyed on the %d namespaces below.
//     Printed here.
//   - %d namespace buckets that read exactly their axis's `+"`@none`"+`. A namespace a root does not
//     consume produces no reading of its own; the value falls through the bare-value precedence to
//     the `+"`@none`"+` step, which is already in this file. Derived live, never printed, because
//     printing them would be printing one repository's token names.
//
// Zero buckets fell outside those two cases. The generator re-runs that check on every invocation
// and exits rather than printing a table if any bucket does, so this comment cannot quietly go stale.
//
// Regenerate with:
//
//	go run ./internal/lint/rules/tailwind/tools/generate_descriptor_base \
//	    -input <a.json> -context <a-context.json> \
//	    -input <b.json> -context <b-context.json> \
//	    -output internal/lint/rules/tailwind/collapse/descriptor_base_table.go

package %s

// baseReadings holds every distinct reading in the invariant table exactly once.
//
// Readings are immutable and shared; nothing in the port writes to one. NewTable copies no reading
// out of this array, it points at them, which is what keeps building a table per run cheap.
var baseReadings = []Reading{
`, systems[0].table.TailwindVersion, len(systems), strings.Join(sources, ", "),
		stats.roots, stats.consumedBuckets, stats.frameworkNamespaces, stats.noneBuckets, packageName)

	for _, value := range pool.readings {
		if len(value.Order) == 0 {
			fmt.Fprintf(&body, "\t{Count: %d},\n", value.Count)
			continue
		}
		orderParts := make([]string, len(value.Order))
		for index, order := range value.Order {
			orderParts[index] = fmt.Sprint(order)
		}
		fmt.Fprintf(&body, "\t{Order: []int{%s}, Count: %d},\n", strings.Join(orderParts, ", "), value.Count)
	}
	fmt.Fprintf(&body, "}\n\n")

	fmt.Fprintf(&body, `// BaseTailwindVersion is the engine version this file was generated against.
//
// Carried so a table built against an upgraded tailwindcss is a loud failure rather than a subtly
// wrong sort. NewTable compares it with the live design system's version.
const BaseTailwindVersion = %q

// FrameworkNamespaces is the set of theme namespaces a utility root actually consumes.
//
// %d of them, and every one is a namespace Tailwind itself defines. Its job is to let NewTable tell
// the two kinds of namespace apart: a namespace in this set has its reading printed per root below,
// and a namespace outside it reads its axis's `+"`@none`"+` on every root, whatever the repository
// chose to call it.
//
// It is emitted rather than inferred from the descriptors because "absent from every descriptor" and
// "consumed but reading like @none" are different facts that happen to look alike in the printed
// table, and only the generator, holding several systems at once, can tell them apart.
var FrameworkNamespaces = map[string]bool{
`, systems[0].table.TailwindVersion, stats.frameworkNamespaces)
	frameworkNames := make([]string, 0, len(frameworkNamespaces))
	for name := range frameworkNamespaces {
		frameworkNames = append(frameworkNames, name)
	}
	sort.Strings(frameworkNames)
	for _, name := range frameworkNames {
		fmt.Fprintf(&body, "\t%q: true,\n", name)
	}
	fmt.Fprintf(&body, "}\n\n")

	fmt.Fprintf(&body, `// baseStatics is every static utility whose reading is a fact about Tailwind.
//
// %d of them. A static one system registers and another does not is a repository `+"`@utility`"+`
// block — ahra declares `+"`markdown-content`"+` and `+"`typing-dots`"+`, www-connected-app declares
// neither — and NewTable adds those from the live evaluator rather than this file carrying one
// repository's utilities as framework facts.
var baseStatics = map[string]Reading{
`, stats.statics)
	body.Write(staticsBuffer.Bytes())
	fmt.Fprintf(&body, "}\n\n")

	fmt.Fprintf(&body, `// baseDescriptors is every functional root the framework registers, keyed by root.
//
// %d roots. The namespace maps hold only the framework namespaces plus the two pseudo-namespaces;
// NewTable adds nothing to them and instead consults FrameworkNamespaces to decide whether a theme
// namespace the repository declared reads here or falls through to `+"`@none`"+`.
var baseDescriptors = map[string]*Descriptor{
`, stats.roots)
	body.Write(rootsBuffer.Bytes())
	fmt.Fprintf(&body, "}\n")

	return body.Bytes(), stats
}

func generate(table *extractedTable, tableContext *extractedContext, packageName, variableName string) ([]byte, generationStats) {
	stats := generationStats{}
	stats.namespaces = len(tableContext.Namespaces)
	pool := newReadingPool()

	perDeclaration := make(map[string]bool, len(tableContext.PerDeclarationRoots))
	for _, root := range tableContext.PerDeclarationRoots {
		perDeclaration[root] = true
	}

	var body bytes.Buffer

	var rootsBuffer bytes.Buffer
	for index := range table.Roots {
		entry := &table.Roots[index]
		writeDescriptor(&rootsBuffer, entry, perDeclaration[entry.Root], pool, &stats)
	}

	var staticsBuffer bytes.Buffer

	allStatics := make(map[string]*reading, len(table.Statics)+len(tableContext.UnlistedStatics))
	for name, value := range tableContext.UnlistedStatics {
		allStatics[name] = value
	}
	for name, value := range table.Statics {
		allStatics[name] = value
	}
	staticNames := make([]string, 0, len(allStatics))
	for name := range allStatics {
		staticNames = append(staticNames, name)
	}
	sort.Strings(staticNames)
	for _, name := range staticNames {
		if allStatics[name] == nil {
			continue
		}
		fmt.Fprintf(&staticsBuffer, "\t\t%q: generatedReadings[%d],\n", name, pool.intern(allStatics[name]))
	}
	stats.statics = len(staticNames)

	stats.distinctReadings = len(pool.readings)
	for _, value := range pool.readings {
		stats.orderIntegers += len(value.Order)
	}

	fmt.Fprintf(&body, `// Code generated by internal/lint/rules/tailwind/tools/generate_descriptor_table. DO NOT EDIT.
//
// Generated from %s against Tailwind %s.
//
// This file is per-repository by construction and is not checked in: Namespaces and KeysByNamespace
// come from this repository's own @theme, and a committed copy would report one repository's tokens
// as facts about Tailwind. See the command's doc comment for the measurement behind that claim.

package %s

// generatedReadings holds every distinct reading in the table exactly once.
//
// %d buckets in the extractor's output hold %d distinct readings between them, so every bucket below
// is an index into this array rather than a copy. Readings are immutable and shared; nothing in the
// port writes to one.
var generatedReadings = []Reading{
`, jsonPathComment(table.EntryPoint), table.TailwindVersion, packageName, stats.bucketsIn, len(pool.readings))

	for _, value := range pool.readings {
		if len(value.Order) == 0 {
			fmt.Fprintf(&body, "\t{Count: %d},\n", value.Count)
			continue
		}
		orderParts := make([]string, len(value.Order))
		for index, order := range value.Order {
			orderParts[index] = fmt.Sprint(order)
		}
		fmt.Fprintf(&body, "\t{Order: []int{%s}, Count: %d},\n", strings.Join(orderParts, ", "), value.Count)
	}

	fmt.Fprintf(&body, "}\n\n// %s is this repository's descriptor table.\nvar %s = &Table{\n\tTailwindVersion: %q,\n\tDescriptors: map[string]*Descriptor{\n", variableName, variableName, table.TailwindVersion)
	body.Write(rootsBuffer.Bytes())
	fmt.Fprintf(&body, "\t},\n\tStatics: map[string]Reading{\n")
	body.Write(staticsBuffer.Bytes())
	fmt.Fprintf(&body, "\t},\n")

	fmt.Fprintf(&body, "\tNamespaces: []string{\n")
	for _, namespace := range tableContext.Namespaces {
		fmt.Fprintf(&body, "\t\t%q,\n", namespace)
	}
	fmt.Fprintf(&body, "\t},\n\tKeysByNamespace: map[string]map[string]bool{\n")
	for _, namespace := range tableContext.Namespaces {
		keys := tableContext.KeysByNamespace[namespace]
		if len(keys) == 0 {
			continue
		}
		sorted := append([]string(nil), keys...)
		sort.Strings(sorted)
		fmt.Fprintf(&body, "\t\t%q: {\n", namespace)
		for _, key := range sorted {
			fmt.Fprintf(&body, "\t\t\t%q: true,\n", key)
		}
		fmt.Fprintf(&body, "\t\t},\n")
	}
	fmt.Fprintf(&body, "\t},\n\tPropertyOrder: map[string]int{\n")
	for index, property := range tableContext.PropertyOrder {
		fmt.Fprintf(&body, "\t\t%q: %d,\n", property, index)
	}
	fmt.Fprintf(&body, "\t},\n}\n")

	return body.Bytes(), stats
}

genericPrint.Declaration:
func genericPrint(path *astPath, options *printerOptions, print printing.PrintFunc, _ any) doc.Doc {
	node := currentNode(path)

	if isFrontMatter(node) {
		return doc.Text(node.String("raw"))
	}

	switch node.Type() {
	case "css-root":
		nodes := printSequence(path, options, print)
		after := trim(rawString(node, "after"))
		if strings.HasPrefix(after, ";") {
			after = trim(after[1:])
		}

		var frontMatter doc.Doc = doc.Text("")
		if node.Child("frontMatter") != nil {
			frontMatter = doc.Concat{
				print("frontMatter", nil),
				doc.Hardline,
				choose(len(node.List("nodes")) > 0, func() doc.Doc { return doc.Hardline }),
			}
		}
		return doc.Concat{
			frontMatter,
			nodes,
			choose(after != "", func() doc.Doc { return doc.Text(" " + after) }),
			choose(len(node.List("nodes")) > 0, func() doc.Doc { return doc.Hardline }),
		}

	case "css-comment":
		isInlineComment := node.Truthy("inline") || estree.IsTruthy(rawsOf(node)["inline"])

		text := sliceText(options.OriginalText, locStart(node), locEnd(node))

		if isInlineComment {
			return doc.Text(trimEnd(text))
		}
		return doc.Text(text)

	case "css-rule":
		selector := node.Child("selector")
		var block doc.Doc = doc.Text(";")
		if isPresent(node.Get("nodes")) {
			var opening doc.Doc = doc.Text("")
			if selector.Type() == "selector-unknown" && lastLineHasInlineComment(selector.String("value")) {
				opening = doc.LineDoc
			} else if selector != nil {
				opening = doc.Text(" ")
			}
			block = doc.Concat{
				opening,
				doc.Text("{"),
				choose(len(node.List("nodes")) > 0, func() doc.Doc {
					return doc.NewIndent(doc.Concat{doc.Hardline, printSequence(path, options, print)})
				}),
				doc.Hardline,
				doc.Text("}"),
				choose(isDetachedRulesetDeclarationNode(node), func() doc.Doc { return doc.Text(";") }),
			}
		}
		return doc.Concat{
			print("selector", nil),
			choose(node.Truthy("important"), func() doc.Doc { return doc.Text(" !important") }),
			block,
		}

	case "css-decl":
		return printDeclaration(path, options, print)

	case "css-atrule":
		return printAtRule(path, options, print)

	case "media-query-list":
		parts := []doc.Doc{}
		path.Each(func(path *astPath, _ int, _ any) {
			node := currentNode(path)
			if node.Type() == "media-query" && node.String("value") == "" {
				return
			}
			parts = append(parts, print(nil, nil))
		}, "nodes")

		return doc.NewGroup(doc.NewIndent(doc.Join(doc.LineDoc, parts)), doc.GroupOptions{})

	case "media-query":
		return doc.Concat{
			doc.Join(doc.Text(" "), printAll(path, print, "nodes")),
			choose(!path.IsLast(), func() doc.Doc { return doc.Text(",") }),
		}

	case "media-type":
		return doc.Text(adjustNumbers(adjustStrings(node.String("value"), options)))

	case "media-feature-expression":
		if !isPresent(node.Get("nodes")) {
			return doc.Text(node.String("value"))
		}
		return doc.Concat(append(append([]doc.Doc{doc.Text("(")}, printAll(path, print, "nodes")...), doc.Text(")")))

	case "media-feature":
		return doc.Text(maybeToLowerCase(
			adjustStrings(mediaFeatureSpacesPattern.ReplaceAllString(node.String("value"), " "), options),
		))

	case "media-colon":
		return doc.Concat{doc.Text(node.String("value")), doc.Text(" ")}

	case "media-value":
		return doc.Text(adjustNumbers(adjustStrings(node.String("value"), options)))

	case "media-keyword":
		return doc.Text(adjustStrings(node.String("value"), options))

	case "media-url":
		value := mediaURLOpeningPattern.ReplaceAllString(node.String("value"), "url(")
		value = mediaURLClosingPattern.ReplaceAllString(value, ")")
		return doc.Text(adjustStrings(value, options))

	case "media-unknown":
		return doc.Text(node.String("value"))

	case "selector-root":
		var customSelector doc.Doc = doc.Text("")
		if insideAtRuleNode(path, "custom-selector") {
			atRule, _ := path.FindAncestor(func(node *estree.Node) bool { return node.Type() == "css-atrule" })
			customSelector = doc.Concat{doc.Text(atRule.String("customSelector")), doc.LineDoc}
		}
		var separator doc.Doc = doc.Hardline
		if insideAtRuleNode(path, "extend", "custom-selector", "nest") {
			separator = doc.LineDoc
		}
		return doc.NewGroup(doc.Concat{
			customSelector,
			doc.Join(doc.Concat{doc.Text(","), separator}, printAll(path, print, "nodes")),
		}, doc.GroupOptions{})

	case "selector-selector":
		shouldIndent := len(node.List("nodes")) > 2
		var contents doc.Doc = doc.Concat(printAll(path, print, "nodes"))
		if shouldIndent {
			contents = doc.NewIndent(contents)
		}
		return doc.NewGroup(contents, doc.GroupOptions{})

	case "selector-comment":
		return doc.Text(node.String("value"))

	case "selector-string":
		return doc.Text(adjustStrings(node.String("value"), options))

	case "selector-tag":
		value := node.String("value")
		previous, _ := path.Previous()
		if previous.Type() != "selector-nesting" {
			if isKeyframeAtRuleKeywords(path, value) {
				value = toLowerCase(value)
			}
			value = adjustNumbers(value)
		}
		return doc.Concat{printNamespace(node), doc.Text(value)}

	case "selector-id":
		return doc.Concat{doc.Text("#"), doc.Text(node.String("value"))}

	case "selector-class":
		return doc.Concat{doc.Text("."), doc.Text(adjustNumbers(adjustStrings(node.String("value"), options)))}

	case "selector-attribute":
		var value doc.Doc = doc.Text("")
		if node.String("value") != "" {
			value = doc.ReplaceEndOfLine(
				doc.Text(quoteAttributeValue(adjustStrings(trim(node.String("value")), options), options)),
				doc.LiterallineWithoutBreakParent,
			)
		}
		return doc.Concat{
			doc.Text("["),
			printNamespace(node),
			doc.Text(trim(node.String("attribute"))),
			doc.Text(node.String("operator")),
			value,
			choose(node.Truthy("insensitive"), func() doc.Doc { return doc.Text(" i") }),
			doc.Text("]"),
		}

	case "selector-combinator":
		value := node.String("value")
		if value == "+" || value == ">" || value == "~" || value == ">>>" {
			parentNode, _ := path.Parent()
			var leading doc.Doc = doc.LineDoc
			if parentNode.Type() == "selector-selector" && firstNode(parentNode.List("nodes")) == node {
				leading = doc.Text("")
			}

			return doc.Concat{leading, doc.Text(value), choose(!path.IsLast(), func() doc.Doc { return doc.Text(" ") })}
		}

		var leading doc.Doc = doc.Text("")
		if strings.HasPrefix(trimStart(value), "(") {
			leading = doc.LineDoc
		}
		var printed doc.Doc = doc.LineDoc
		if adjusted := adjustNumbers(adjustStrings(trim(value), options)); adjusted != "" {
			printed = doc.Text(adjusted)
		}

		return doc.Concat{leading, printed}

	case "selector-universal":
		return doc.Concat{printNamespace(node), doc.Text(node.String("value"))}

	case "selector-pseudo":
		return doc.Concat{
			doc.Text(maybeToLowerCase(node.String("value"))),
			choose(len(node.List("nodes")) > 0, func() doc.Doc {
				return doc.NewGroup(doc.Concat{
					doc.Text("("),
					doc.NewIndent(doc.Concat{doc.Softline, doc.Join(doc.Concat{doc.Text(","), doc.LineDoc}, printAll(path, print, "nodes"))}),
					doc.Softline,
					doc.Text(")"),
				}, doc.GroupOptions{})
			}),
		}

	case "selector-nesting":
		return doc.Text(node.String("value"))

	case "selector-unknown":
		return printSelectorUnknown(path, options)

	case "value-value", "value-root":
		return print("group", nil)

	case "value-comment":
		text := sliceText(options.OriginalText, locStart(node), locEnd(node))
		if node.Truthy("inline") {
			return doc.NewLineSuffix(doc.Text(trimEnd(text)))
		}
		return doc.Text(text)

	case "value-comma_group":
		return printCommaSeparatedValueGroup(path, options, print)

	case "value-paren_group":
		return printParenthesizedValueGroup(path, options, print)

	case "value-func":
		return doc.Concat{
			doc.Text(node.String("value")),
			choose(insideAtRuleNode(path, "supports") && isMediaAndSupportsKeywords(node), func() doc.Doc { return doc.Text(" ") }),
			print("group", nil),
		}

	case "value-paren":
		return doc.Text(node.String("value"))

	case "value-number":
		return doc.Concat{doc.Text(printCssNumber(node.String("value"))), doc.Text(printUnit(node.String("unit")))}

	case "value-operator":
		return doc.Text(node.String("value"))

	case "value-word":
		if (node.Truthy("isColor") && node.Truthy("isHex")) || isWideKeywords(node.String("value")) {
			return doc.Text(toLowerCase(node.String("value")))
		}

		return doc.Text(node.String("value"))

	case "value-colon":
		previous, _ := path.Previous()
		previousValue, previousValueIsString := previous.Get("value").(string)
		var after doc.Doc = doc.LineDoc

		if (previousValueIsString && strings.HasSuffix(previousValue, `\`)) ||

			insideValueFunctionNode(path, "url") {
			after = doc.Text("")
		}
		return doc.NewGroup(doc.Concat{doc.Text(node.String("value")), after}, doc.GroupOptions{})

	case "value-string":
		quote := rawString(node, "quote")
		return doc.Text(printString(quote+node.String("value")+quote, options))

	case "value-atword":
		return doc.Concat{doc.Text("@"), doc.Text(node.String("value"))}

	case "value-unicode-range":
		return doc.Text(node.String("value"))

	case "value-unknown":
		return doc.Text(node.String("value"))
	}

	panic(fmt.Sprintf("Unexpected PostCSS node type: %q.", node.Type()))
}

func genericPrint(path *astPath, options *printerOptions, print printing.PrintFunc, _ any) doc.Doc {
	node := currentNode(path)

	switch node.Type() {
	case "Document":
		return append(
			join(hardline, printSequence(path, options, print, "definitions")),
			hardline,
		)

	case "OperationDefinition":
		hasOperation := options.OriginalText[locStart(node)] != '{'
		hasName := node.Child("name") != nil
		return doc.Concat{
			printDescription(path, options, print),
			choose(hasOperation, text(node.String("operation"))),
			choose(hasOperation && hasName, doc.Concat{text(" "), print("name", nil)}),
			choose(hasOperation && !hasName && isNonEmptyArray(node, "variableDefinitions"), text(" ")),
			printVariableDefinitions(path, print),
			printDirectives(path, print),
			choose(!(!hasOperation && !hasName), text(" ")),
			print("selectionSet", nil),
		}

	case "FragmentDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			text("fragment "),
			print("name", nil),
			printVariableDefinitions(path, print),
			text(" on "),
			print("typeCondition", nil),
			printDirectives(path, print),
			text(" "),
			print("selectionSet", nil),
		}

	case "SelectionSet":
		return doc.Concat{
			text("{"),
			indent(
				hardline,
				join(hardline, printSequence(path, options, print, "selections")),
			),
			hardline,
			text("}"),
		}

	case "Field":
		return group(
			choose(node.Child("alias") != nil, doc.Concat{print("alias", nil), text(": ")}),
			print("name", nil),
			choose(isNonEmptyArray(node, "arguments"), group(
				text("("),
				indent(
					softline,
					join(
						doc.Concat{ifBreak(empty, text(", ")), softline},
						printSequence(path, options, print, "arguments"),
					),
				),
				softline,
				text(")"),
			)),
			printDirectives(path, print),
			choose(node.Child("selectionSet") != nil, text(" ")),
			print("selectionSet", nil),
		)

	case "Name":
		return text(node.String("value"))

	case "StringValue":
		if node.Bool("block") {
			lines := strings.Split(strings.ReplaceAll(node.String("value"), `"""`, `\"""`), "\n")
			if len(lines) == 1 {
				lines[0] = trim(lines[0])
			}

			allEmpty := true
			for _, line := range lines {
				if line != "" {
					allEmpty = false
					break
				}
			}
			if allEmpty {
				lines = lines[:0]
			}

			parts := []doc.Doc{text(`"""`)}
			for _, line := range lines {
				parts = append(parts, text(line))
			}
			parts = append(parts, text(`"""`))
			return join(hardline, parts)
		}
		return doc.Concat{
			text(`"`),
			text(strings.ReplaceAll(escapeQuoteAndBackslash.Replace(node.String("value")), "\n", `\n`)),
			text(`"`),
		}

	case "IntValue", "FloatValue", "EnumValue":
		return text(node.String("value"))

	case "BooleanValue":
		if node.Bool("value") {
			return text("true")
		}
		return text("false")

	case "NullValue":
		return text("null")

	case "Variable":
		return doc.Concat{text("$"), print("name", nil)}

	case "ListValue":
		isEmpty := !isNonEmptyArray(node, "values")
		return group(
			text("["),
			printing.PrintDanglingComments(path, options, printing.DanglingOptions[*estree.Node]{Indent: true}),
			choose(!isEmpty, indent(
				softline,
				join(doc.Concat{ifBreak(empty, text(", ")), softline}, printAll(path, print, "values")),
			)),
			softline,
			text("]"),
		)

	case "ObjectValue":
		isEmpty := !isNonEmptyArray(node, "fields")
		bracketSpace := choose(settingsOf(options).BracketSpacing && !isEmpty, text(" "))
		return group(
			text("{"),
			bracketSpace,
			printing.PrintDanglingComments(path, options, printing.DanglingOptions[*estree.Node]{Indent: true}),
			choose(!isEmpty, doc.Concat{
				indent(
					softline,
					join(doc.Concat{ifBreak(empty, text(", ")), softline}, printAll(path, print, "fields")),
				),
			}),
			softline,
			ifBreak(empty, bracketSpace),
			text("}"),
		)

	case "ObjectField", "Argument", "FragmentArgument":
		return doc.Concat{print("name", nil), text(": "), print("value", nil)}

	case "Directive":
		return doc.Concat{text("@"), print("name", nil), printArguments(path, options, print)}

	case "NamedType":
		return print("name", nil)

	case "VariableDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			print("variable", nil),
			text(": "),
			print("type", nil),
			choose(node.Child("defaultValue") != nil, doc.Concat{text(" = "), print("defaultValue", nil)}),
			printDirectives(path, print),
		}

	case "ObjectTypeExtension",
		"ObjectTypeDefinition",
		"InputObjectTypeExtension",
		"InputObjectTypeDefinition",
		"InterfaceTypeExtension",
		"InterfaceTypeDefinition":
		kind := node.Type()
		parts := doc.Concat{}

		if strings.HasSuffix(kind, "TypeDefinition") {
			parts = append(parts, printDescription(path, options, print))
		} else {
			parts = append(parts, text("extend "))
		}

		if strings.HasPrefix(kind, "ObjectType") {
			parts = append(parts, text("type"))
		} else if strings.HasPrefix(kind, "InputObjectType") {
			parts = append(parts, text("input"))
		} else {
			parts = append(parts, text("interface"))
		}
		parts = append(parts, text(" "), print("name", nil))

		if !strings.HasPrefix(kind, "InputObjectType") &&
			isNonEmptyArray(node, "interfaces") {
			parts = append(parts,
				text(" implements "),
				indent(group(join(doc.Concat{text(" &"), line}, printAll(path, print, "interfaces")))),
			)
		}

		parts = append(parts, printDirectives(path, print))

		if isNonEmptyArray(node, "fields") {
			parts = append(parts, doc.Concat{
				text(" {"),
				indent(
					hardline,
					join(hardline, printSequence(path, options, print, "fields")),
				),
				hardline,
				text("}"),
			})
		}

		return parts

	case "FieldDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			print("name", nil),
			choose(isNonEmptyArray(node, "arguments"), group(
				text("("),
				indent(
					softline,
					join(
						doc.Concat{ifBreak(empty, text(", ")), softline},
						printSequence(path, options, print, "arguments"),
					),
				),
				softline,
				text(")"),
			)),
			text(": "),
			print("type", nil),
			printDirectives(path, print),
		}

	case "DirectiveDefinition":
		return append(doc.Concat{
			printDescription(path, options, print),
			text("directive "),
			text("@"),
			print("name", nil),
			choose(isNonEmptyArray(node, "arguments"), group(
				text("("),
				indent(
					softline,
					join(
						doc.Concat{ifBreak(empty, text(", ")), softline},
						printSequence(path, options, print, "arguments"),
					),
				),
				softline,
				text(")"),
			)),
			printDirectives(path, print),
			choose(node.Bool("repeatable"), text(" repeatable")),
			text(" on "),
		}, join(text(" | "), printAll(path, print, "locations"))...)

	case "DirectiveExtension":
		return doc.Concat{
			text("extend directive @"),
			print("name", nil),
			printDirectives(path, print),
		}

	case "EnumTypeExtension", "EnumTypeDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			choose(node.Is("EnumTypeExtension"), text("extend ")),
			text("enum "),
			print("name", nil),
			printDirectives(path, print),
			choose(isNonEmptyArray(node, "values"), doc.Concat{
				text(" {"),
				indent(
					hardline,
					join(hardline, printSequence(path, options, print, "values")),
				),
				hardline,
				text("}"),
			}),
		}

	case "EnumValueDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			print("name", nil),
			printDirectives(path, print),
		}

	case "InputValueDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			print("name", nil),
			text(": "),
			print("type", nil),
			choose(node.Child("defaultValue") != nil, doc.Concat{text(" = "), print("defaultValue", nil)}),
			printDirectives(path, print),
		}

	case "SchemaExtension":
		parts := doc.Concat{
			text("extend schema"),
			printDirectives(path, print),
		}
		if isNonEmptyArray(node, "operationTypes") {
			parts = append(parts,
				text(" {"),
				indent(
					hardline,
					join(
						hardline,
						printSequence(path, options, print, "operationTypes"),
					),
				),
				hardline,
				text("}"),
			)
		}
		return parts

	case "SchemaDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			text("schema"),
			printDirectives(path, print),
			text(" {"),
			choose(isNonEmptyArray(node, "operationTypes"), indent(
				hardline,
				join(
					hardline,
					printSequence(path, options, print, "operationTypes"),
				),
			)),
			hardline,
			text("}"),
		}

	case "OperationTypeDefinition":
		return doc.Concat{text(node.String("operation")), text(": "), print("type", nil)}

	case "FragmentSpread":
		return doc.Concat{
			text("..."),
			print("name", nil),
			printArguments(path, options, print),
			printDirectives(path, print),
		}

	case "InlineFragment":
		return doc.Concat{
			text("..."),
			choose(node.Child("typeCondition") != nil, doc.Concat{text(" on "), print("typeCondition", nil)}),
			printDirectives(path, print),
			text(" "),
			print("selectionSet", nil),
		}

	case "UnionTypeExtension", "UnionTypeDefinition":
		return group(
			printDescription(path, options, print),
			group(
				choose(node.Is("UnionTypeExtension"), text("extend ")),
				text("union "),
				print("name", nil),
				printDirectives(path, print),
				choose(isNonEmptyArray(node, "types"), doc.Concat{
					text(" ="),
					ifBreak(empty, text(" ")),
					indent(
						ifBreak(doc.Concat{line, text("| ")}, nil),
						join(doc.Concat{line, text("| ")}, printAll(path, print, "types")),
					),
				}),
			),
		)

	case "ScalarTypeExtension", "ScalarTypeDefinition":
		return doc.Concat{
			printDescription(path, options, print),
			choose(node.Is("ScalarTypeExtension"), text("extend ")),
			text("scalar "),
			print("name", nil),
			printDirectives(path, print),
		}

	case "NonNullType":
		return doc.Concat{print("type", nil), text("!")}

	case "ListType":
		return doc.Concat{text("["), print("type", nil), text("]")}

	default:

		panic(fmt.Sprintf("Unexpected Graphql node kind: '%s'.", node.Type()))
	}
}

func genericPrint(path *astPath, options *options, print printing.PrintFunc, _ any) doc.Doc {
	node := currentNode(path)
	settings := settingsOf(options)

	parts := make(doc.Concat, 0, 4)

	if node.NodeType != "mappingValue" && hasLeadingComments(node) {
		parts = append(parts, doc.Concat{doc.Join(doc.Hardline, mapPrint(path, print, "leadingComments")), doc.Hardline})
	}

	tag, anchor := node.Tag, node.Anchor
	if tag != nil {
		parts = append(parts, print("tag", nil))
	}
	if tag != nil && anchor != nil {
		parts = append(parts, doc.Text(" "))
	}
	if anchor != nil {
		parts = append(parts, print("anchor", nil))
	}

	var nextEmptyLine doc.Doc = doc.Text("")

	if isNode(node, "mapping", "sequence", "comment", "directive", "mappingItem", "sequenceItem") &&
		!isLastDescendantNode(path) {
		nextEmptyLine = printNextEmptyLine(path, options.OriginalText, settings)
	}

	if tag != nil || anchor != nil {
		if isNode(node, "sequence", "mapping") && !hasMiddleComments(node) {
			parts = append(parts, doc.Hardline)
		} else {
			parts = append(parts, doc.Text(" "))
		}
	}

	if hasMiddleComments(node) {
		var first doc.Doc = doc.Hardline
		if len(node.MiddleComments) == 1 {
			first = doc.Text("")
		}
		parts = append(parts, doc.Concat{
			first,
			doc.Join(doc.Hardline, mapPrint(path, print, "middleComments")),
			doc.Hardline,
		})
	}

	if hasPrettierIgnore(path) {
		parts = append(parts, doc.ReplaceEndOfLine(
			doc.Text(trimEnd(options.OriginalText[node.Position.Start.Offset:node.Position.End.Offset])),
			nil,
		))
	} else {
		parts = append(parts, doc.NewGroup(printNode(path, options, print), doc.GroupOptions{}))
	}

	if hasTrailingComment(node) && !isNode(node, "document", "documentHead") {
		var space doc.Doc = doc.Text(" ")
		if node.NodeType == "mappingValue" && contentOf(node) == nil {
			space = doc.Text("")
		}
		var breakParent = doc.BreakParent
		if parent := parentNode(path); parent.NodeType == "mappingKey" {

			if greatGrandparent, _ := path.GetParentNode(2); greatGrandparent.NodeType == "mapping" && isInlineNode(node) {
				breakParent = doc.Text("")
			}
		}
		parts = append(parts, doc.NewLineSuffix(doc.Concat{space, breakParent, print("trailingComment", nil)}))
	}

	if shouldPrintEndComments(node) {
		width := 0
		if node.NodeType == "sequenceItem" {
			width = 2
		}
		endComments := printing.Map(path, func(path *astPath, _ int, _ any) doc.Doc {
			var emptyLine doc.Doc = doc.Text("")
			if printing.IsPreviousLineEmpty(options.OriginalText, locStart(currentNode(path))) {
				emptyLine = doc.Hardline
			}
			return doc.Concat{emptyLine, print(nil, nil)}
		}, "endComments")
		parts = append(parts, alignWithSpaces(width, doc.Concat{doc.Hardline, doc.Join(doc.Hardline, endComments)}))
	}
	parts = append(parts, nextEmptyLine)
	return parts
}

