func hasPrettierIgnore(path *astPath) bool {
	node := currentNode(path)
	if node == nil {
		return false
	}
	for _, comment := range node.Comments {
		if trim(comment.String("value")) == "prettier-ignore" {
			return true
		}
	}
	return false
}

func hasPrettierIgnore(path *astPath) bool {
	index, present := path.Index()
	return present && index > 0 && isPrettierIgnore(previousNode(path)) == "next"
}

func hasPrettierIgnore(path *astPath) bool {
	node := currentNode(path)

	if node.NodeType == "documentBody" {
		documentHead := childAt(parentNode(path), 0)
		return hasEndComments(documentHead) &&
			isPrettierIgnore(documentHead.EndComments[len(documentHead.EndComments)-1])
	}

	return hasLeadingComments(node) && isPrettierIgnore(node.LeadingComments[len(node.LeadingComments)-1])
}

hexValue.Declaration:
func hexValue(b byte) uint32 {
	switch {
	case b >= '0' && b <= '9':
		return uint32(b - '0')
	case b >= 'a' && b <= 'f':
		return uint32(b-'a') + 10
	case b >= 'A' && b <= 'F':
		return uint32(b-'A') + 10
	}
	return 0
}

func hexValue(character rune) int {
	switch {
	case character >= '0' && character <= '9':
		return int(character - '0')
	case character >= 'a' && character <= 'f':
		return int(character-'a') + 10
	case character >= 'A' && character <= 'F':
		return int(character-'A') + 10
	}
	return -1
}

