	}
	return index + from
}

indexOf.Declaration:
func indexOf(css []uint16, search string, from int) int {
	units := utf16.Encode([]rune(search))
	if from < 0 {
		from = 0
	}
	for index := from; index+len(units) <= len(css); index++ {
		matched := true
		for offset, unit := range units {
			if css[index+offset] != unit {
				matched = false
				break
			}
		}
		if matched {
			return index
		}
	}
	return -1
}

func indexOf(path *Path) int {
	index, inArray := path.Index()
	if !inArray {
		return -1
	}
	return index
}

func indexOf(text []uint16, character uint16, from int) int {
	if from < 0 {
		from = 0
	}
	for index := from; index < len(text); index++ {
		if text[index] == character {
			return index
		}
	}
	return -1
}

