func isNextLineEmpty(text string, startIndex int) bool {
	oldIndex := notFound - 1
	index := startIndex
	for index != oldIndex {
		oldIndex = index
		index = skipToLineEnd(text, index, false)
		index = printing.SkipInlineComment(text, index)
		index = skipSpaces(text, index, false)
	}
	index = printing.SkipTrailingComment(text, index)
	index = printing.SkipNewline(text, index, false)
	return index != notFound && hasNewline(text, index)
}

func isNextLineEmpty(node *unist.Node, text string) bool {
	newlineCount := 0
	index := node.Position.End.Offset
	if index > 0 {
		_, width := utf8.DecodeLastRuneInString(text[:index])
		index -= width
	}

	for index < len(text) {
		character, width := utf8.DecodeRuneInString(text[index:])

		if character == '\n' {
			newlineCount++
		}

		if newlineCount == 1 && !isJavaScriptWhitespace(character) {
			return false
		}

		if newlineCount == 2 {
			return true
		}
		index += width
	}

	return false
}

