jsonPathComment.Declaration:
func jsonPathComment(entryPoint string) string {
	if entryPoint == "" {
		return "an unnamed design system"
	}
	parts := strings.Split(entryPoint, "/")

	for index := len(parts) - 1; index > 0; index-- {
		if parts[index] == "app" || parts[index] == "src" {
			return parts[index-1]
		}
	}
	if len(parts) >= 2 {
		return parts[len(parts)-1]
	}
	return entryPoint
}

func jsonPathComment(entryPoint string) string {
	if entryPoint == "" {
		return "an unnamed design system"
	}
	parts := strings.Split(entryPoint, "/")
	if len(parts) <= 3 {
		return entryPoint
	}
	return ".../" + strings.Join(parts[len(parts)-3:], "/")
}

jsonStringify.Declaration:
func jsonStringify(value string) string {
	var builder strings.Builder
	builder.WriteByte('"')
	for _, character := range value {
		switch character {
		case '"':
			builder.WriteString(`\"`)
		case '\\':
			builder.WriteString(`\\`)
		case '\b':
			builder.WriteString(`\b`)
		case '\f':
			builder.WriteString(`\f`)
		case '\n':
			builder.WriteString(`\n`)
		case '\r':
			builder.WriteString(`\r`)
		case '\t':
			builder.WriteString(`\t`)
		default:
			if character < 0x20 {
				fmt.Fprintf(&builder, `\u%04x`, character)
			} else {
				builder.WriteRune(character)
			}
		}
	}
	builder.WriteByte('"')
	return builder.String()
}

func jsonStringify(units []uint16) string {
	var builder strings.Builder
	writeJSONString(&builder, units)
	return builder.String()
}

