func main() {
	sha := flag.String("sha", "", "facebook/react commit to vendor from (required)")
	out := flag.String("out", "", "directory to write the fixture pairs into (required unless -dry-run)")
	dryRun := flag.Bool("dry-run", false, "report the counts without writing")
	expect := flag.Int("expect", expectedFixtureCount, "fixture pairs a correct run finds; a mismatch aborts")
	expectClean := flag.Int("expect-clean", expectedCleanFixtureCount, "clean fixture pairs a correct run finds; a mismatch aborts")
	flag.Parse()

	if *sha == "" {
		fail("-sha is required; vendoring from a moving branch is the thing this corpus exists not to do")
	}
	if *out == "" && !*dryRun {
		fail("-out is required unless -dry-run")
	}

	names, err := errorFixtureNames(*sha)
	if err != nil {
		fail("listing the tree: %v", err)
	}

	topLevel, nested := 0, 0
	subdirectories := map[string]int{}
	for _, name := range names {
		if !strings.Contains(name, "/") {
			topLevel++
			continue
		}
		nested++
		subdirectories[path.Dir(name)]++
	}

	fmt.Printf("sha              %s\n", *sha)
	fmt.Printf("error fixtures   %d  (%d top-level, %d across %d subdirectories)\n",
		len(names), topLevel, nested, len(subdirectories))
	for _, directory := range sortedKeys(subdirectories) {
		fmt.Printf("                   %-40s %d\n", directory, subdirectories[directory])
	}

	if nested == 0 {
		fail("found no fixtures in subdirectories at all, which is the signature of a path-anchored filter rather than an empty tree")
	}
	if len(names) != *expect {
		fail("found %d error fixtures, expected %d; if upstream really changed, read the diff and pass -expect", len(names), *expect)
	}

	clean, err := cleanFixtureNames(*sha)
	if err != nil {
		fail("listing the clean fixtures: %v", err)
	}
	fmt.Printf("clean fixtures   %d  (carry %s and expect no error)\n", len(clean), preserveMemoizationPragma)

	if len(clean) != *expectClean {
		fail("found %d clean fixtures, expected %d; if upstream really changed, read the diff and pass -expect-clean",
			len(clean), *expectClean)
	}

	if *dryRun {
		fmt.Println("dry run, nothing written")
		return
	}

	written, err := writeFixtures(*sha, append(append([]string(nil), names...), clean...), *out)
	if err != nil {
		fail("writing fixtures: %v", err)
	}
	fmt.Printf("wrote            %d files (%d pairs) into %s\n", written, written/2, *out)
}

func main() {
	packageRoot := flag.String("package-root", "", "path to the tailwindcss package root (the directory holding package.json)")
	corpusRoot := flag.String("corpus-root", "", "path to a repository to scan for the classes it actually writes")
	themeEntry := flag.String("theme-entry", "", "path to the repository's CSS entry point, so its own @utility and @theme blocks are in the tables")
	output := flag.String("output", filepath.Join("internal", "tailwind", "testdata", "candidate_fixtures.json"), "where to write the fixture")
	check := flag.Bool("check", false, "regenerate and fail if the committed fixture disagrees")
	flag.Parse()

	if *packageRoot == "" {
		fmt.Fprintln(os.Stderr, "-package-root is required")
		os.Exit(2)
	}

	generated, err := enumerate(*packageRoot, *corpusRoot, *themeEntry)
	if err != nil {
		fmt.Fprintf(os.Stderr, "enumerate: %v\n", err)
		os.Exit(1)
	}

	if *check {
		committed, err := os.ReadFile(*output)
		if err != nil {
			fmt.Fprintf(os.Stderr, "read committed fixture: %v\n", err)
			os.Exit(1)
		}

		if !bytes.Equal(bytes.TrimSpace(committed), bytes.TrimSpace(generated)) {
			fmt.Fprintf(os.Stderr, "%s is out of date; rerun without -check\n", *output)
			os.Exit(1)
		}
		fmt.Fprintf(os.Stderr, "%s is up to date\n", *output)
		return
	}

	if err := os.WriteFile(*output, generated, 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "write %s: %v\n", *output, err)
		os.Exit(1)
	}

	var summary struct {
		TailwindVersion          string            `json:"tailwindVersion"`
		ThemeEntry               *string           `json:"themeEntry"`
		UtilityRootCount         int               `json:"utilityRootCount"`
		VariantRootCount         int               `json:"variantRootCount"`
		ClassNameOccurrences     int               `json:"classNameOccurrences"`
		RepositoryClassCount     int               `json:"repositoryClassCount"`
		AmbiguousCount           int               `json:"ambiguousCount"`
		AmbiguousRepositoryCount int               `json:"ambiguousRepositoryCount"`
		Cases                    []json.RawMessage `json:"cases"`
	}
	if err := json.Unmarshal(generated, &summary); err != nil {
		fmt.Fprintf(os.Stderr, "summarize: %v\n", err)
		os.Exit(1)
	}

	entry := "framework defaults only"
	if summary.ThemeEntry != nil {
		entry = *summary.ThemeEntry
	}
	fmt.Fprintf(
		os.Stderr,
		"wrote %s: tailwind %s via %s, %d utility roots and %d variant roots; "+
			"%d classes read, of which %d yield more than one candidate; "+
			"the repository contributed %d distinct classes from %d occurrences, %d of them ambiguous\n",
		*output,
		summary.TailwindVersion,
		entry,
		summary.UtilityRootCount,
		summary.VariantRootCount,
		len(summary.Cases),
		summary.AmbiguousCount,
		summary.RepositoryClassCount,
		summary.ClassNameOccurrences,
		summary.AmbiguousRepositoryCount,
	)
}

