func printBlock(path *Path, options *Options, print PrintFunc) Doc {
	bodyDoc := printBlockBody(path, options, print)
	current := node(path)
	parent := parentOf(path)

	if current.Is("Program") && !parent.Is("ModuleExpression") {
		if bodyDoc != nil {
			return concatIn(path, bodyDoc, hardline)
		}
		return emptyDoc
	}

	var parts []any
	if current.Is("StaticBlock") {
		parts = append(parts, "static ")
	}
	parts = append(parts, "{")
	if bodyDoc != nil {
		parts = append(parts, indentIn(path, concatIn(path, hardline, bodyDoc)), hardline)
	} else {
		parentParent := grandparentOf(path)
		if !(parent.Is("ArrowFunctionExpression", "FunctionExpression", "FunctionDeclaration", "ComponentDeclaration",
			"HookDeclaration", "ObjectMethod", "ClassMethod", "ClassPrivateMethod", "ForStatement", "WhileStatement",
			"DoWhileStatement", "DoExpression", "ModuleExpression") ||
			parent.Is("CatchClause") && parentParent.Child("finalizer") == nil ||
			parent.Is("TSModuleDeclaration", "DeclareModule", "MatchStatementCase") ||
			current.Is("StaticBlock")) {
			parts = append(parts, hardline)
		}
	}
	parts = append(parts, "}")
	return concatIn(path, parts...)
}

func printBlock(path *astPath, options *options, print printing.PrintFunc) doc.Doc {
	node := currentNode(path)
	settings := settingsOf(options)
	parentIndent := 0
	for _, ancestor := range path.Ancestors() {
		if ancestor.NodeType == "sequence" || ancestor.NodeType == "mapping" {
			parentIndent++
		}
	}
	isLastDescendant := isLastDescendantNode(path)
	parts := doc.Concat{}
	if node.NodeType == "blockFolded" {
		parts = append(parts, doc.Text(">"))
	} else {
		parts = append(parts, doc.Text("|"))
	}
	if node.Indent != nil {
		parts = append(parts, doc.Text(strconv.Itoa(*node.Indent)))
	}

	if node.Chomping != "clip" {
		if node.Chomping == "keep" {
			parts = append(parts, doc.Text("+"))
		} else {
			parts = append(parts, doc.Text("-"))
		}
	}

	if hasIndicatorComment(node) {
		parts = append(parts, doc.Text(" "), print("indicatorComment", nil))
	}

	lineContents := getBlockValueLineContents(node, parentIndent, isLastDescendant, options, settings)
	contentsParts := doc.Concat{}
	for index, lineWords := range lineContents {
		if index == 0 {
			contentsParts = append(contentsParts, doc.Hardline)
		}
		contentsParts = append(contentsParts, fillWords(lineWords))
		if index != len(lineContents)-1 {
			if len(lineWords) == 0 {
				contentsParts = append(contentsParts, doc.Hardline)
			} else {
				contentsParts = append(contentsParts, doc.MarkAsRoot(doc.Literalline))
			}
		} else if node.Chomping == "keep" && isLastDescendant {
			if len(lineWords) == 0 {
				contentsParts = append(contentsParts, doc.DedentToRoot(doc.Hardline))
			} else {
				contentsParts = append(contentsParts, doc.DedentToRoot(doc.Literalline))
			}
		}
	}
	if node.Indent == nil {
		parts = append(parts, doc.Dedent(alignWithSpaces(settings.tabWidth, contentsParts)))
	} else {
		parts = append(parts, doc.DedentToRoot(alignWithSpaces(*node.Indent-1+parentIndent, contentsParts)))
	}

	return parts
}

printChildren.Declaration:
func printChildren(path *astPath, options *options, print printing.PrintFunc, process processor) doc.Doc {
	if process == nil {
		process = func(*astPath) (doc.Doc, bool) { return print(nil, nil), true }
	}

	parts := doc.Concat{}

	path.Each(func(path *astPath, _ int, _ any) {
		result, keep := process(path)
		if keep {
			if len(parts) > 0 && shouldPrePrintHardline(path) {
				parts = append(parts, doc.Hardline)

				if shouldPrePrintDoubleHardline(path, options) {
					parts = append(parts, doc.Hardline)
				}
			}

			parts = append(parts, result)
		}
	}, "children")

	return parts
}

func printChildren(path *astPath, options *options, print printing.PrintFunc) doc.Doc {
	settings := settingsOf(options)
	return doc.Concat(printing.Map(path, func(path *astPath, _ int, _ any) doc.Doc {
		printed := print(nil, nil)
		if path.IsLast() {
			return doc.Concat{printed, doc.Text("")}
		}
		node := currentNode(path)
		next := nextNode(path)
		var emptyLine doc.Doc = doc.Text("")
		if node.Position.Start.Line != next.Position.Start.Line {
			emptyLine = printNextEmptyLine(path, options.OriginalText, settings)
		}
		return doc.Concat{printed, doc.Concat{doc.Text(","), doc.LineDoc, emptyLine}}
	}, "children"))
}

