func printComment(path *astPath, _ *printerOptions) doc.Doc {
	comment := currentNode(path)
	if comment.Is("Comment") {
		return text("#" + trimEnd(comment.String("value")))
	}

	encoded, _ := json.Marshal(comment.Type())
	panic("Not a comment: " + string(encoded))
}

func printComment(path *Path, options *Options) Doc {
	comment := node(path)
	if isLineComment(comment) {
		return concatIn(path, estree.TrimEndJavaScript(options.OriginalText[locStart(comment):locEnd(comment)]))
	}
	if estree.IsIndentableBlockComment(comment) {
		return printIndentableBlockComment(comment)
	}
	if isBlockComment(comment) {
		return concatIn(path, "/*", replaceEndOfLine(comment.String("value")), "*/")
	}
	panic("not a comment: " + comment.Type())
}

func printComment[N Node[N]](path *AstPath[N], options *Options[N]) doc.Doc {
	comment, _ := path.Node()
	comment.CommentData().Printed = true
	return options.Printer.PrintComment(path, options)
}

printFunction.Declaration:
func printFunction(path *Path, options *Options, print PrintFunc, args *printArguments) Doc {
	if isMethodValue(path) {
		return printMethodValue(path, options, print)
	}

	current := node(path)

	shouldExpandParameters := false
	if current.Is("FunctionExpression") && args != nil && args.expandLastArg {
		parent := parentOf(path)
		if isCallExpression(parent) &&
			(len(getCallArguments(parent)) > 1 ||
				!slices.ContainsFunc(getFunctionParameters(current), func(param Node) bool {

					return !(param.Is("Identifier") && !param.Truthy("typeAnnotation"))
				})) {
			shouldExpandParameters = true
		}
	}

	parametersDoc := printFunctionParameters(
		path,
		options,
		print,
		shouldExpandParameters,
		false,
	)
	returnTypeDoc := printReturnType(path, print)
	shouldGroupParameters := shouldGroupFunctionParameters(
		current,
		returnTypeDoc,
	)

	isFlowHookDeclaration := current.Is("HookDeclaration")
	keyword := "function"
	if isFlowHookDeclaration {
		keyword = "hook"
	}

	async := ""
	if current.Truthy("async") {
		async = "async "
	}
	generator := ""
	if current.Truthy("generator") {
		generator = "*"
	}

	idSpace := ""
	var idDoc Doc = emptyDoc
	if current.Truthy("id") {
		idSpace = " "
		idDoc = print("id", nil)
	}
	var parameters Doc = parametersDoc
	if shouldGroupParameters {
		parameters = groupIn(path, parametersDoc)
	}
	bodySpace := ""
	if current.Truthy("body") {
		bodySpace = " "
	}
	var semicolon Doc = emptyDoc
	if current.Truthy("declare") || !current.Truthy("body") {
		semicolon = printSemicolon(options)
	}

	return concatIn(path, printDeclareToken(path),
		async,
		keyword,
		generator,
		idSpace,
		idDoc,
		print("typeParameters", nil),
		groupIn(path, concatIn(path, parameters,
			returnTypeDoc,
		)),
		bodySpace,
		print("body", nil),
		semicolon,
	)
}

func printFunction(out *strings.Builder, function *Function, depth int) {
	indent := strings.Repeat("  ", depth)

	name := function.Name
	if name == "" {
		name = "<anonymous>"
	}
	fmt.Fprintf(out, "%sfunction %s(", indent, name)
	for index, param := range function.Params {
		if index > 0 {
			out.WriteString(", ")
		}
		out.WriteString(function.PlaceString(param))
	}
	out.WriteString(")")
	if function.Kind != FunctionKindOther {
		fmt.Fprintf(out, " [%s]", function.Kind)
	}
	out.WriteString("\n")

	for _, block := range function.Blocks {
		fmt.Fprintf(out, "%sbb%d (%s)", indent, block.Id, block.Kind)
		if len(block.Predecessors) > 0 {
			predecessors := make([]string, 0, len(block.Predecessors))
			for _, predecessor := range block.Predecessors {
				predecessors = append(predecessors, fmt.Sprintf("bb%d", predecessor))
			}
			sort.Strings(predecessors)
			fmt.Fprintf(out, " preds=[%s]", strings.Join(predecessors, " "))
		}
		out.WriteString(":\n")

		for _, phi := range block.Phis {
			operands := make([]string, 0, len(phi.Operands))
			for _, predecessorId := range PhiOperandsInOrder(phi) {
				operands = append(operands, fmt.Sprintf("bb%d: %s",
					predecessorId, function.PlaceString(phi.Operands.At(predecessorId))))
			}
			fmt.Fprintf(out, "%s  %s = phi(%s)\n",
				indent, function.PlaceString(phi.Place), strings.Join(operands, ", "))
		}
		for _, instructionId := range block.Instructions {
			instruction := function.Instructions[instructionId]
			fmt.Fprintf(
				out,
				"%s  %s = %s\n",
				indent,
				function.PlaceString(instruction.LValue),
				printValue(function, instruction.Value),
			)
		}
		fmt.Fprintf(out, "%s  %s\n", indent, printTerminal(function, block.Terminal))
	}

	for _, nested := range function.Functions {
		out.WriteString("\n")
		printFunction(out, nested, depth+1)
	}
}

