printSequence.Declaration:
func printSequence(path *astPath, options *printerOptions, print printing.PrintFunc) doc.Doc {
	parts := doc.Concat{}
	path.Each(func(path *astPath, _ int, _ any) {
		node := currentNode(path)
		previous, _ := path.Previous()
		if previous.Type() == "css-comment" && trim(previous.String("text")) == "prettier-ignore" {
			parts = append(parts, doc.Text(options.OriginalText[locStart(node):locEnd(node)]))
		} else {
			parts = append(parts, print(nil, nil))
		}

		if path.IsLast() {
			return
		}

		next, _ := path.Next()
		if (next.Type() == "css-comment" &&
			!printing.HasNewline(options.OriginalText, locStart(next), true) &&
			!isFrontMatter(node)) ||
			(next.Type() == "css-atrule" &&
				next.String("name") == "else" &&
				node.Type() != "css-comment") {
			parts = append(parts, doc.Text(" "))
		} else {

			parts = append(parts, doc.Hardline)
			if isNextLineEmpty(options.OriginalText, locEnd(node)) && !isFrontMatter(node) {
				parts = append(parts, doc.Hardline)
			}
		}
	}, "nodes")

	return parts
}

func printSequence(path *astPath, options *printerOptions, print printing.PrintFunc, property string) []doc.Doc {
	return printing.Map(path, func(path *astPath, _ int, _ any) doc.Doc {
		printed := print(nil, nil)

		if !path.IsLast() && isNextLineEmpty(options.OriginalText, locEnd(currentNode(path))) {
			return doc.Concat{printed, hardline}
		}

		return printed
	}, property)
}

printString.Declaration:
func printString(raw string, options *printerOptions) string {

	rawContent := ""
	if len(raw) >= 2 {
		rawContent = raw[1 : len(raw)-1]
	}

	enclosingQuote := getPreferredQuote(rawContent, settingsOf(options).SingleQuote)

	originalQuote := ""
	if len(raw) > 0 {
		originalQuote = raw[:1]
	}

	if originalQuote == enclosingQuote {
		return raw
	}

	return makeString(rawContent, enclosingQuote)
}

func printString(raw string, options *Options) string {
	rawContent := raw[1 : len(raw)-1]
	var enclosingQuote string
	switch settingsOf(options).Parser {
	case "json", "jsonc", "json-stringify":
		enclosingQuote = `"`
	default:
		enclosingQuote = getPreferredQuote(rawContent, settingsOf(options).SingleQuote)
	}
	if raw[:1] == enclosingQuote {
		return raw
	}
	return makeString(rawContent, enclosingQuote)
}

