func printToDoc(text string, prettierOptions formatoptions.Options, parser string) (doc.Doc, error) {
	root, err := parseWithParserName(text, parser)
	if err != nil {
		if !printing.IsSyntax(err) {
			err = printing.Syntax(err)
		}
		return nil, err
	}

	if frontMatter := root.Child("frontMatter"); frontMatter.String("language") == "yaml" && trim(frontMatter.String("value")) != "" {
		return nil, fmt.Errorf("%s: yaml front matter is formatted by the yaml printer, which css.Format cannot reach", parser)
	}

	printOptions := &printerOptions{
		Printer:                    postcssPrinter,
		OriginalText:               text,
		Settings:                   printSettings{Options: prettierOptions, parser: parser},
		EmbeddedLanguageFormatting: "auto",
	}
	return printing.PrintAstToDoc(root, nil, printOptions)
}

func printToDoc(text string, prettierOptions formatoptions.Options) (doc.Doc, error) {
	document, comments, err := Parse(text)
	if err != nil {
		return nil, err
	}
	printOptions := &printerOptions{
		Printer:                    graphqlPrinter,
		OriginalText:               text,
		Settings:                   prettierOptions,
		EmbeddedLanguageFormatting: "auto",
	}
	return printing.PrintAstToDoc(document, comments, printOptions)
}

func printToDoc(fileName string, text string, parsed *ast.SourceFile, options formatoptions.Options, parser string, parentParser string,
	textToDoc printing.TextToDoc, nodes *estree.Arena, docs *docMemory) (document doc.Doc, err error) {
	defer func() {
		if recovered := recover(); recovered != nil {
			document, err = nil, fmt.Errorf("formatting %s: %v", fileName, recovered)
		}
	}()

	var root *estree.Node
	var comments []*estree.Node
	var strippedText *estree.StrippedText
	printer := estreePrinter
	switch parser {
	case "typescript":
		root, comments, strippedText, err = estree.ParseTypeScriptFrom(fileName, text, parsed, nodes)
	case "babel":
		root, comments, strippedText, err = estree.ParseJavaScript(fileName, text, nodes)
	case "json":
		root, comments, err = estree.ParseJSON(text, true)

		options.TrailingComma = "none"
	case "json-stringify":
		root, comments, err = estree.ParseJSON(text, false)
		printer = estreeJSONPrinter
	default:
		err = fmt.Errorf("no parser %q", parser)
	}
	if err != nil {
		return nil, err
	}
	printOptions := &Options{
		Printer:                    printer,
		OriginalText:               text,
		Settings:                   &settings{Options: options, FilePath: fileName, Parser: parser, ParentParser: parentParser, docs: docs, strippedText: strippedText},
		EmbeddedLanguageFormatting: "auto",
		TextToDoc:                  textToDoc,
		NodeCount:                  nodes.Len(),
	}
	return printing.PrintAstToDoc(root, comments, printOptions)
}

