func render(result *enumeration) ([]byte, error) {
	var buffer bytes.Buffer

	fmt.Fprintf(&buffer, `// Code generated by internal/lint/rules/tailwind/tools/generate_collapse. DO NOT EDIT.
//
// Regenerate with:
//
//	go run ./internal/lint/rules/tailwind/tools/generate_collapse -entry-point <theme.css>
//
// Source: Tailwind %s, enumerated from %s.
// %d functional roots produced %d candidate pairs, of which %d collapse.
//
// Each entry is a fact about roots rather than about classes: %s
// holds for every value the two roots share, so the table is small and does not grow with the
// codebase. Enumerated from the design system's own class list rather than from any codebase's
// usage, because a table built from observed classes is silently missing every family nobody has
// written yet.
//
// Only CollapseFamilies is claimed invariant. The other tables in this file are per-repository by
// construction, and KnownStatics is the proof: it carries markdown-content, one of ahra's own
// @utility blocks, under a header naming only a Tailwind version. Read this file as one framework
// fact sitting beside several repository extractions, not as framework data throughout.
%s
package tailwind

// CollapseFamily is two utility roots that merge into a third.
//
// The merge only happens when everything except the root already agrees between the two classes:
// their variants, their importance, and their value. That precondition is the gate's job; this
// table answers only "if those match, do these two roots have a shorthand".
type CollapseFamily struct {
	First  string
	Second string
	Output string
	// RequiresLogicalToPhysical is true when the canonicalizer collapses this pair only while it
	// reads logical properties as their physical longhands, its logicalToPhysical option. With
	// `+"`logical: false`"+`, enforce-canonical-classes skips the family.
	RequiresLogicalToPhysical bool
}

// CollapseFamilies is every family the installed Tailwind knows, sorted by input roots.
//
// Upstream ships shorthand data and it does not derive this. Two maps keyed on CSS property,
// `+"`"+`padding-inline: [padding-left, padding-right]`+"`"+` and its kin, cover inset, margin, padding,
// scroll-margin, scroll-padding, border width/style/colour, gap, overflow, overscroll-behavior and
// ten logical block/inline pairs. This is keyed on utility roots, `+"`"+`pl + pr => px`+"`"+`, and bridging the
// two key spaces is `+"`"+`canonicalizeCandidates`+"`"+`, the signature-equivalence search `+"`"+`enumerate.mjs`+"`"+`
// prices at eight to ten thousand lines that changes every Tailwind minor.
//
// It also holds families no CSS shorthand covers, which is the half that makes the two genuinely
// different questions rather than one restated: `+"`"+`h + w => size`+"`"+`, `+"`"+`skew`+"`"+`, `+"`"+`translate`+"`"+`, the `+"`"+`rounded-*`+"`"+`
// corners, the `+"`"+`mask-*`+"`"+` edges and `+"`"+`border-spacing`+"`"+` collapse through a utility relationship rather
// than a property one.
var CollapseFamilies = []CollapseFamily{
`,
		result.TailwindVersion,
		result.EntryPoint,
		result.FunctionalRoots,
		result.PairsProbed,
		len(result.Families),
		exampleFamily(result.Families),
		invarianceProvenance(result.VerifiedAgainst),
	)

	for _, entry := range result.Families {
		if len(entry.Inputs) != 2 {
			return nil, fmt.Errorf("family %v does not have exactly two inputs", entry.Inputs)
		}
		fmt.Fprintf(&buffer, "\t{First: %q, Second: %q, Output: %q, RequiresLogicalToPhysical: %t},\n",
			entry.Inputs[0], entry.Inputs[1], entry.Output, entry.RequiresLogicalToPhysical)
	}

	fmt.Fprintf(&buffer, `}

// RootSelectorShapes used to be printed here and is not any more.
//
// internal/tailwind's SelectorShapeForRoot reads the nested-rule wrapper off the ported handle
// bodies, which is where upstream keeps it. The eight shapes this printed are reproduced exactly,
// and a repository block that declares a nested selector is answered rather than missed.

// ColorNames used to be printed here and is not any more.
//
// internal/rules/tailwind's valueIsColorIn asks the live theme's `+"`--color`"+` namespace, which is what
// upstream does, with IsColorKeyword beside it for the three keywords that sit in no namespace.
// Measured before the deletion: 558 of its 561 names answered by the theme and the other 3 by
// colorKeywords, 0 uncovered, and the table knew nothing of the three colours www-connected-app
// declares because it was generated from ahra.

// TailwindVersion is the version these families were enumerated from.
//
// Recorded so a mismatch between this and the installed Tailwind is greppable, and so a reader of a
// finding can tell which engine's opinion produced it.
const TailwindVersion = %q
`, result.TailwindVersion)

	formatted, err := format.Source(buffer.Bytes())
	if err != nil {
		return nil, fmt.Errorf("formatting the generated table: %w", err)
	}
	return formatted, nil
}

func render(result *enumeration) ([]byte, error) {
	entries := make([]registryEntry, len(result.Entries))
	copy(entries, result.Entries)

	sort.SliceStable(entries, func(left int, right int) bool {
		if entries[left].Order != entries[right].Order {
			return entries[left].Order < entries[right].Order
		}
		return entries[left].Name < entries[right].Name
	})

	comparisons := make([]groupedComparison, len(result.Comparisons))
	copy(comparisons, result.Comparisons)
	sort.SliceStable(comparisons, func(left int, right int) bool {
		return comparisons[left].Order < comparisons[right].Order
	})

	distinctOrders := map[int]bool{}
	sharedOrders := map[int][]string{}
	for _, entry := range entries {
		distinctOrders[entry.Order] = true
		sharedOrders[entry.Order] = append(sharedOrders[entry.Order], entry.Name)
	}
	sharedCount := 0
	for _, names := range sharedOrders {
		if len(names) > 1 {
			sharedCount++
		}
	}

	var builder strings.Builder
	fmt.Fprintf(&builder, `// Code generated by internal/lint/rules/tailwind/tools/generate_framework_variants. DO NOT EDIT.
//
// Regenerate with:
//
//	go run ./internal/lint/rules/tailwind/tools/generate_framework_variants -package-root <tailwindcss package>
//
// Source: Tailwind %s, read from the engine's own variant registry.
// %d registrations over %d distinct order numbers, %d of which are shared by more than one root,
// and %d of which carry a comparison function.
//
// Repository-invariant, and re-measured rather than asserted. An earlier version of this header
// claimed verification against "each of the two corpus repositories' own theme.css loaded through
// its own install", and that load did not exist: enumerate.mjs took only a package root and built
// every design system from a bare `+"`@import \"tailwindcss\"`"+`, so the four independent generations were
// one framework stylesheet read four times, and a set of readings that cannot differ cannot detect
// a table that varies. Those two repositories also vendor the same Structure submodule, so even a
// real comparison between them would have measured a shared dependency.
//
// The claim survives being measured properly. Identical names, orders and kinds across the corpus
// repositories, an independent design system sharing no submodule, and a bare install. The
// mechanism is Variants.set assigning kind onto an existing record without touching order, so a
// repository redefining `+"`dark`"+` changes the selector it emits without moving where it sorts, while a
// @custom-variant under a NEW name appends a position and stays live-loaded rather than being baked
// in here. Both halves were probed: two new names appended at 83 and 84 and moved no framework
// registration, which is also the control proving the comparison can fail.
%s//
// Keyed on registration roots rather than on composed prefixes. The other variant table in this
// package, VariantOrder in property_order_table.go, is keyed on shapes like `+"`group-hover:`"+`, which
// have no registration of their own; the two sitting side by side is the difference being argued.

package tailwind

`, result.TailwindVersion, len(entries), len(distinctOrders), sharedCount, len(comparisons), invarianceProvenance(result.VerifiedAgainst))

	builder.WriteString(`// FrameworkVariantRegistration is one variant the framework registers, with the order number the
// engine assigned it.
//
// Order is carried rather than re-derived, and that is the whole reason this type exists alongside
// FrameworkVariant. Replaying these through Register in sequence would give every root its own
// number, and the engine shares numbers: six roots hold one order in a default build. A shared
// order is where a comparison function gets to speak, and comparison is how the five breakpoints
// order by their resolved widths instead of alphabetically.
type FrameworkVariantRegistration struct {
	// Name is the registered root, as written before the colon: ` + "`hover`" + `, ` + "`group`" + `, ` + "`@max`" + `.
	Name string
	// Order is the registration number Variants.set assigned. Shared across every root registered
	// inside one Variants.group.
	Order int
	// Kind is the registration kind, which decides which branch of Compare applies.
	Kind ParsedVariantKind
}

// FrameworkVariantComparisonGroup is one order number whose members are separated by a comparison
// function rather than by registration.
//
// The function itself cannot be generated: upstream's is a closure over the design system's theme,
// and reading a hardcoded breakpoint scale here would be the per-repository bug this port exists to
// remove. Measured on the engine, redefining ` + "`--breakpoint-sm`" + ` to ` + "`200rem`" + ` moves ` + "`sm`" + ` from dense
// index 0 to index 4. So what is generated is the order number and the direction, and
// LoadDesignSystem attaches CompareBreakpoints over the live theme.
//
// Ascending is probed against the engine rather than read from variants.ts, so a release that
// flipped one produces a diff here instead of silently reversing every class in the group.
type FrameworkVariantComparisonGroup struct {
	// Order is the shared registration number the comparison is keyed on.
	Order int
	// Ascending is the direction: the breakpoints and the container queries ascend, ` + "`max`" + ` and
	// ` + "`@max`" + ` descend.
	Ascending bool
	// Members are the roots holding this order, for diagnostics and for the test that asserts the
	// generated groups still match the generated registrations.
	Members []string
}

`)

	fmt.Fprintf(&builder, `// FrameworkVariantRegistrations is every variant the installed Tailwind registers, in registration
// order.
//
// In order rather than sorted by name, so a reader sees the sequence the engine performed and an
// upgrade's diff shows where a new variant was inserted. Registrations() sorts by name when a
// caller needs that.
var FrameworkVariantRegistrations = []FrameworkVariantRegistration{
`)
	for _, entry := range entries {
		fmt.Fprintf(
			&builder,
			"\t{Name: %s, Order: %d, Kind: %s},\n",
			strconv.Quote(entry.Name), entry.Order, variantKindConstants[entry.Kind],
		)
	}
	builder.WriteString("}\n\n")

	builder.WriteString(`// FrameworkVariantComparisonGroups is every order number that carries a comparison function.
//
// All four are breakpoint comparisons in a default build. Without them the six roots sharing order
// 64 fall through to a root-name comparison, and ` + "`2xl`" + ` sorts before ` + "`sm`" + ` alphabetically, which
// reorders every responsive class in the tree.
var FrameworkVariantComparisonGroups = []FrameworkVariantComparisonGroup{
`)
	for _, comparison := range comparisons {
		members := make([]string, 0, len(comparison.Members))
		for _, member := range comparison.Members {
			members = append(members, strconv.Quote(member))
		}
		fmt.Fprintf(
			&builder,
			"\t{Order: %d, Ascending: %t, Members: []string{%s}},\n",
			comparison.Order, comparison.Ascending != nil && *comparison.Ascending, strings.Join(members, ", "),
		)
	}
	builder.WriteString("}\n")

	formatted, err := format.Source([]byte(builder.String()))
	if err != nil {
		return nil, fmt.Errorf("formatting the generated table: %w", err)
	}
	return formatted, nil
}

func render(systems []staticsFile, shared []staticEntry, dropped []string) ([]byte, error) {
	sources := make([]string, 0, len(systems))
	for _, system := range systems {
		sources = append(sources, filepath.Base(system.EntryPoint))
	}

	var body bytes.Buffer
	fmt.Fprintf(&body, `// Code generated by internal/lint/rules/tailwind/tools/generate_statics. DO NOT EDIT.
//
// Generated against Tailwind %s from %d design systems: %s.
//
// Every static utility the framework registers, with the declarations it compiles to. A static
// utility takes no value, so its body is a constant and its reading is PropertySort over that body.
// Carrying the declarations rather than the reading is what lets the Go side compute the reading
// with the same walk it uses for a repository's own `+"`@utility`"+` blocks, so the two paths cannot
// disagree about what a declaration list means.
//
// # Why this is checked in when the port exists to remove checked-in tables
//
// These are registrations, not readings of a repository's tokens. A static utility declares literal
// property/value pairs from Tailwind's own source and consults no theme, which is what makes it a
// framework fact; the generator proves that rather than asserting it, by keeping only the names every
// input system registers with identical declarations and refusing a run where the intersection
// removed nothing.
//
//   - %d statics registered identically by every input system, printed here.
//   - %d dropped as repository-specific, including %s.
//
// # Read from the registry, not from the class list
//
// `+"`getClassList()`"+` enumerates classes, so a utility advertising none is invisible to it. That
// hid fourteen functional roots until 33e12df and 6347b07, and it hides 21 statics here: the
// deprecated-but-registered ones such as `+"`bg-gradient-to-r`"+`, `+"`break-words`"+` and
// `+"`max-w-screen`"+`, which the base descriptor table never carried. enumerate.mjs reads
// `+"`utilities.keys('static')`"+` instead.
//
// Regenerate with:
//
//	node internal/lint/rules/tailwind/tools/generate_statics/enumerate.mjs <theme.css> > <system>.json   (once per system)
//	go run ./internal/lint/rules/tailwind/tools/generate_statics -input <a.json> -input <b.json> -input <c.json> \
//	    -output internal/lint/rules/tailwind/collapse/framework_statics_table.go

package tailwind

// FrameworkStaticDeclarations is the compiled body of every static utility the framework registers.
//
// Keyed by class name. The value is the declaration sequence in the order PropertySort visits it,
// which is the order the engine emitted, so a consumer walks it rather than re-deriving one.
var FrameworkStaticDeclarations = map[string][]StaticDeclaration{
`, systems[0].TailwindVersion, len(systems), strings.Join(sources, ", "),
		len(shared), len(dropped), strings.Join(firstFew(dropped, 3), ", "))

	for _, entry := range shared {
		fmt.Fprintf(&body, "\t%s: {", strconv.Quote(entry.Name))
		for index, declaration := range entry.Declarations {
			if index > 0 {
				body.WriteString(", ")
			}
			value := ""
			if declaration.Value != nil {
				value = *declaration.Value
			}
			fmt.Fprintf(&body, "{Property: %s, Value: %s", strconv.Quote(declaration.Property), strconv.Quote(value))
			if declaration.ValuePresent {
				body.WriteString(", ValuePresent: true")
			}
			if declaration.Important {
				body.WriteString(", Important: true")
			}
			body.WriteString("}")
		}
		body.WriteString("},\n")
	}
	body.WriteString("}\n")

	return format.Source(body.Bytes())
}

