func sliceUnits(body string, start int, units int) string {
	end := start
	for end < len(body) {
		character, size := utf8.DecodeRuneInString(body[end:])
		if units < utf16.RuneLen(character) {
			if units > 0 {
				return body[start:end] + string(utf8.RuneError)
			}
			break
		}
		end += size
		units -= utf16.RuneLen(character)
	}
	return body[start:end]
}

func sliceUnits(text string, count int) string {
	if count < 0 {
		return ""
	}
	units := 0
	for index, character := range text {
		if units >= count {
			return text[index:]
		}
		if character > 0xFFFF {
			units += 2
			if units > count {
				return "�" + text[index+utf8.RuneLen(character):]
			}
		} else {
			units++
		}
	}
	return ""
}

