func tokenize(css []uint16) []*token {
	tokens := []*token{}

	var code, next, nextLine, nextOffset, escapePos int
	var quote, content string
	var escape, escaped bool

	length := len(css)
	offset := -1
	line := 1
	pos := 0

	unclosed := func(what string) {
		throwError("Unclosed " + what)
	}

	for pos < length {
		code = charCodeAt(css, pos)

		if code == newline {
			offset = pos
			line += 1
		}

		switch code {
		case newline, space, tab, cr, feed:
			next = pos
			for {
				next += 1
				code = charCodeAt(css, next)
				if code == newline {
					offset = next
					line += 1
				}
				if !(code == space || code == newline || code == tab || code == cr || code == feed) {
					break
				}
			}

			tokens = append(tokens, &token{"space", slice(css, pos, next), []int{line, pos - offset, pos}})
			pos = next - 1

		case plus, gt, tilde, pipe:
			next = pos
			for {
				next += 1
				code = charCodeAt(css, next)
				if !(code == plus || code == gt || code == tilde || code == pipe) {
					break
				}
			}
			tokens = append(tokens, &token{"combinator", slice(css, pos, next), []int{line, pos - offset, pos}})
			pos = next - 1

		case asterisk:
			tokens = append(tokens, &token{"*", "*", []int{line, pos - offset, pos}})

		case ampersand:
			tokens = append(tokens, &token{"&", "&", []int{line, pos - offset, pos}})

		case comma:
			tokens = append(tokens, &token{",", ",", []int{line, pos - offset, pos}})

		case openSq:
			tokens = append(tokens, &token{"[", "[", []int{line, pos - offset, pos}})

		case closeSq:
			tokens = append(tokens, &token{"]", "]", []int{line, pos - offset, pos}})

		case colon:
			tokens = append(tokens, &token{":", ":", []int{line, pos - offset, pos}})

		case semicolon:
			tokens = append(tokens, &token{";", ";", []int{line, pos - offset, pos}})

		case openBracket:
			tokens = append(tokens, &token{"(", "(", []int{line, pos - offset, pos}})

		case closeBracket:
			tokens = append(tokens, &token{")", ")", []int{line, pos - offset, pos}})

		case singleQuote, doubleQuote:
			if code == singleQuote {
				quote = "'"
			} else {
				quote = "\""
			}
			next = pos
			for {
				escaped = false
				next = indexOf(css, quote, next+1)
				if next == -1 {
					unclosed("quote")
				}
				escapePos = next
				for charCodeAt(css, escapePos-1) == backslash {
					escapePos -= 1
					escaped = !escaped
				}
				if !escaped {
					break
				}
			}

			tokens = append(tokens, &token{"string", slice(css, pos, next+1), []int{line, pos - offset, line, next - offset, pos}})
			pos = next

		case at:

			lastIndex := 0
			for index := pos + 1; index < length; index++ {
				if atEnd(charCodeAt(css, index)) {
					lastIndex = index + 1
					break
				}
			}
			if lastIndex == 0 {
				next = length - 1
			} else {
				next = lastIndex - 2
			}
			tokens = append(tokens, &token{"at-word", slice(css, pos, next+1), []int{line, pos - offset, line, next - offset, pos}})
			pos = next

		case backslash:
			next = pos
			escape = true
			for charCodeAt(css, next+1) == backslash {
				next += 1
				escape = !escape
			}
			code = charCodeAt(css, next+1)
			if escape && code != slash && code != space && code != newline && code != tab && code != cr && code != feed {
				next += 1
			}
			tokens = append(tokens, &token{"word", slice(css, pos, next+1), []int{line, pos - offset, line, next - offset, pos}})
			pos = next

		default:
			if code == slash && charCodeAt(css, pos+1) == asterisk {
				next = indexOf(css, "*/", pos+2) + 1
				if next == 0 {
					unclosed("comment")
				}

				content = slice(css, pos, next+1)

				last := 0
				lastLineStart := pos
				for index := pos; index <= next && index < length; index++ {
					if css[index] == newline {
						last++
						lastLineStart = index + 1
					}
				}
				lastLineLength := next + 1 - lastLineStart

				if last > 0 {
					nextLine = line + last
					nextOffset = next - lastLineLength
				} else {
					nextLine = line
					nextOffset = offset
				}

				tokens = append(tokens, &token{"comment", content, []int{line, pos - offset, nextLine, next - nextOffset, pos}})

				offset = nextOffset
				line = nextLine
				pos = next
			} else {

				lastIndex := 0
				for index := pos + 1; index < length; index++ {
					if wordEnd(css, index) {
						lastIndex = index + 1
						break
					}
				}
				if lastIndex == 0 {
					next = length - 1
				} else {
					next = lastIndex - 2
				}

				tokens = append(tokens, &token{"word", slice(css, pos, next+1), []int{line, pos - offset, line, next - offset, pos}})
				pos = next
			}
		}

		pos++
	}

	return tokens
}

func tokenize(input []uint16, options Options) []token {
	tokens := []token{}
	css := input
	length := len(css)
	offset := -1
	line := 1
	pos := 0
	parentCount := 0
	isURLArg := false

	var code int
	next := undefinedNext
	var quote uint16
	var escaped bool
	var escapePos int

	charCodeAt := func(index int) int {
		if index < 0 || index >= length {
			return -1
		}
		return int(css[index])
	}

	slice := func(start int, end int) []uint16 {
		start = min(max(start, 0), length)
		end = min(max(end, 0), length)
		if end < start {
			end = start
		}
		return css[start:end]
	}

	push := func(kind string, value []uint16, startLine int, startColumn int, endLine int, endColumn int, index int) {
		tokens = append(tokens, token{kind: kind, value: value, startLine: startLine, startColumn: startColumn, endLine: endLine, endColumn: endColumn, index: index})
	}

	pushStale := func(kind string) {
		each := token{kind: kind, value: slice(pos, pos+1), startLine: line, startColumn: pos - offset, endLine: line, index: pos}
		if next == undefinedNext {
			each.endColumnIsNaN = true
		} else {
			each.endColumn = next - offset
		}
		tokens = append(tokens, each)
	}

	unclosed := func(what string) {
		panic(&Error{Name: "TokenizeError", Message: "Unclosed " + what + " at line: " + itoa(line) + ", column: " + itoa(pos-offset) + ", token: " + itoa(pos)})
	}

	for pos < length {
		code = charCodeAt(pos)

		if code == newline {
			offset = pos
			line += 1
		}

		switch code {
		case newline, space, tab, cr, feed:
			next = pos
			for {
				next += 1
				code = charCodeAt(next)
				if code == newline {
					offset = next
					line += 1
				}
				if !(code == space || code == newline || code == tab || code == cr || code == feed) {
					break
				}
			}

			push("space", slice(pos, next), line, pos-offset, line, next-offset, pos)

			pos = next - 1

		case colon:
			next = pos + 1
			push("colon", slice(pos, next), line, pos-offset, line, next-offset, pos)

			pos = next - 1

		case comma:
			next = pos + 1
			push("comma", slice(pos, next), line, pos-offset, line, next-offset, pos)

			pos = next - 1

		case openBracket:
			pushStale("{")

		case closeBracket:
			pushStale("}")

		case openParen:
			parentCount++
			isURLArg = !isURLArg && parentCount == 1 &&
				len(tokens) > 0 &&
				tokens[len(tokens)-1].kind == "word" &&
				string(utf16Decode(tokens[len(tokens)-1].value)) == "url"
			pushStale("(")

		case closeParen:
			parentCount--
			isURLArg = isURLArg && parentCount > 0
			pushStale(")")

		case singleQuote, doubleQuote:
			if code == singleQuote {
				quote = '\''
			} else {
				quote = '"'
			}
			next = pos
			for {
				escaped = false
				next = indexOfUnits(css, []uint16{quote}, next+1)
				if next == -1 {
					unclosed("quote")
				}
				escapePos = next
				for charCodeAt(escapePos-1) == backslash {
					escapePos -= 1
					escaped = !escaped
				}
				if !escaped {
					break
				}
			}

			push("string", slice(pos, next+1), line, pos-offset, line, next-offset, pos)
			pos = next

		case at:
			lastIndex := regexLastIndex(css, pos+1, func(css []uint16, index int) bool { return atEnd(css[index]) })

			if lastIndex == 0 {
				next = length - 1
			} else {
				next = lastIndex - 2
			}

			push("atword", slice(pos, next+1), line, pos-offset, line, next-offset, pos)
			pos = next

		case backslash:
			next = pos
			code = charCodeAt(next + 1)

			push("word", slice(pos, next+1), line, pos-offset, line, next-offset, pos)

			pos = next

		case plus, minus, asterisk:
			next = pos + 1
			nextChar := charCodeAt(pos + 1)

			if code == minus && nextChar == minus {
				next++

				push("word", slice(pos, next), line, pos-offset, line, next-offset, pos)

				pos = next - 1
				break
			}

			push("operator", slice(pos, next), line, pos-offset, line, next-offset, pos)

			pos = next - 1

		default:
			if code == slash && (charCodeAt(pos+1) == asterisk || (options.Loose && !isURLArg && charCodeAt(pos+1) == slash)) {
				isStandardComment := charCodeAt(pos+1) == asterisk

				if isStandardComment {
					next = indexOfUnits(css, []uint16{'*', '/'}, pos+2) + 1
					if next == 0 {
						unclosed("comment")
					}
				} else {
					newlinePos := indexOfUnits(css, []uint16{'\n'}, pos+2)

					if newlinePos != -1 {
						next = newlinePos - 1
					} else {
						next = length
					}
				}

				content := slice(pos, next+1)

				last := 0
				lastLineLength := len(content)
				for index, unit := range content {
					if unit == '\n' {
						last++
						lastLineLength = len(content) - index - 1
					}
				}

				var nextLine, nextOffset int
				if last > 0 {
					nextLine = line + last
					nextOffset = next - lastLineLength
				} else {
					nextLine = line
					nextOffset = offset
				}

				push("comment", content, line, pos-offset, nextLine, next-nextOffset, pos)

				offset = nextOffset
				line = nextLine
				pos = next

			} else if code == pound && !(pos+1 < length && alphaNum(css[pos+1])) {
				next = pos + 1

				push("#", slice(pos, next), line, pos-offset, line, next-offset, pos)

				pos = next - 1
			} else if (code == lowerU || code == upperU) && charCodeAt(pos+1) == plus {
				next = pos + 2

				for {
					next += 1
					code = charCodeAt(next)
					if !(next < length && unicodeRange(css[next])) {
						break
					}
				}

				push("unicoderange", slice(pos, next), line, pos-offset, line, next-offset, pos)
				pos = next - 1
			} else if code == slash {

				next = pos + 1

				push("operator", slice(pos, next), line, pos-offset, line, next-offset, pos)

				pos = next - 1
			} else {
				regex := wordEnd
				isWordEndNum := false

				if code >= digit0 && code <= digit9 {
					regex = wordEndNum
					isWordEndNum = true
				}

				lastIndex := regexLastIndex(css, pos+1, regex)

				if lastIndex == 0 {
					next = length - 1
				} else {
					next = lastIndex - 2
				}

				if isWordEndNum || code == period {
					ncode := charCodeAt(next)
					ncode1 := charCodeAt(next + 1)
					ncode2 := charCodeAt(next + 2)

					if (ncode == lowerE || ncode == upperE) &&
						(ncode1 == minus || ncode1 == plus) &&
						(ncode2 >= digit0 && ncode2 <= digit9) {
						lastIndex := regexLastIndex(css, next+2, wordEndNum)

						if lastIndex == 0 {
							next = length - 1
						} else {
							next = lastIndex - 2
						}
					}
				}

				push("word", slice(pos, next+1), line, pos-offset, line, next-offset, pos)
				pos = next
			}
		}

		pos++
	}

	return tokens
}

